-- complain if script is sourced in psql, rather than via CREATE EXTENSION
\echo Use "CREATE EXTENSION pgkv" to load this file. \quit

-- Generated by build.sh from sql/. Do not edit: change the files in sql/ and run ./build.sh.

-- Create dedicated schema for namespace isolation
CREATE SCHEMA IF NOT EXISTS pgkv;

-- One row per key. Strings and JSON documents keep their value here; a collection (hash,
-- list, set, sorted set) keeps one row per element in a side table, found through `id`.
--   card: number of elements of a collection
--   head: position of a list's first element in pgkv.list_items
-- key is COLLATE "C", so the primary key index orders keys by byte and serves prefix scans.
CREATE TABLE pgkv.store (
    key TEXT COLLATE "C" PRIMARY KEY,
    value JSONB,
    type TEXT NOT NULL DEFAULT 'string',
    expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    id BIGINT,
    card BIGINT,
    head BIGINT,
    CONSTRAINT valid_type CHECK (type IN ('string', 'list', 'set', 'hash', 'zset', 'json'))
) WITH (fillfactor = 90);

-- Index for TTL cleanup
CREATE INDEX idx_pgkv_expires_at ON pgkv.store(expires_at)
    WHERE expires_at IS NOT NULL;

-- Collection elements, one row each, keyed by the owning key's pgkv.store.id.
CREATE SEQUENCE pgkv.collection_id;

CREATE TABLE pgkv.hash_fields (
    id BIGINT NOT NULL,
    field TEXT COLLATE "C" NOT NULL,
    value JSONB NOT NULL,
    PRIMARY KEY (id, field)
);

-- Positions are contiguous: head .. head + card - 1.
CREATE TABLE pgkv.list_items (
    id BIGINT NOT NULL,
    pos BIGINT NOT NULL,
    value TEXT NOT NULL,
    PRIMARY KEY (id, pos)
);

CREATE TABLE pgkv.set_members (
    id BIGINT NOT NULL,
    member TEXT COLLATE "C" NOT NULL,
    PRIMARY KEY (id, member)
);

CREATE TABLE pgkv.zset_members (
    id BIGINT NOT NULL,
    member TEXT COLLATE "C" NOT NULL,
    score DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (id, member)
);

-- Score order, ties in byte order of the member: the order of ZRANGE.
CREATE INDEX idx_pgkv_zset_score ON pgkv.zset_members (id, score, member);

-- Data lives in these tables, so pg_dump must include their contents. Registering them is
-- only possible (and only needed) when this runs as an extension script; a copy applied as
-- plain SQL is dumped like any other table.
DO $$
BEGIN
    PERFORM pg_catalog.pg_extension_config_dump('pgkv.store', '');
    PERFORM pg_catalog.pg_extension_config_dump('pgkv.hash_fields', '');
    PERFORM pg_catalog.pg_extension_config_dump('pgkv.list_items', '');
    PERFORM pg_catalog.pg_extension_config_dump('pgkv.set_members', '');
    PERFORM pg_catalog.pg_extension_config_dump('pgkv.zset_members', '');
    PERFORM pg_catalog.pg_extension_config_dump('pgkv.collection_id', '');
EXCEPTION WHEN feature_not_supported THEN
    NULL;
END;
$$;

-- ============================================================================
-- Internal helpers
--
-- Names starting with an underscore are not part of the API. They are called only by the
-- public functions (which are SECURITY DEFINER and pin search_path), so they carry neither
-- attribute themselves; every reference to a pgkv object is schema-qualified.
--
-- Errors a Redis server would send as an error reply are raised with SQLSTATE class KV,
-- and their message starts with the Redis error code:
--   KV000  ERR ...        (bad argument, syntax, range)
--   KV001  WRONGTYPE ...  (key holds another type)
--   KV002  ERR ...        (unknown command or wrong number of arguments, from pgkv.call)
--   KV003  EXECABORT ...  (internal to pgkv.pipeline, which returns it as a value)
-- ============================================================================

CREATE OR REPLACE FUNCTION pgkv._err(p_message TEXT)
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION '%', p_message USING ERRCODE = 'KV000';
END;
$$;

CREATE OR REPLACE FUNCTION pgkv._wrongtype()
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'WRONGTYPE Operation against a key holding the wrong kind of value' USING ERRCODE = 'KV001';
END;
$$;

-- _INT: parse an integer the way Redis does: no spaces, no plus sign, no leading zeros.
CREATE OR REPLACE FUNCTION pgkv._int(p_text TEXT, p_message TEXT DEFAULT 'ERR value is not an integer or out of range')
RETURNS BIGINT
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v NUMERIC;
BEGIN
    IF p_text ~ '^(0|-?[1-9][0-9]{0,18})$' THEN
        v := p_text::numeric;
        IF v BETWEEN -9223372036854775808 AND 9223372036854775807 THEN
            RETURN v::bigint;
        END IF;
    END IF;
    RAISE EXCEPTION '%', p_message USING ERRCODE = 'KV000';
END;
$$;

-- _FLOAT: parse a double the way Redis does (C strtod, without leading spaces): decimal or
-- exponent notation, inf, hexadecimal integers. NaN and values outside the double range are
-- errors.
CREATE OR REPLACE FUNCTION pgkv._float(p_text TEXT, p_message TEXT DEFAULT 'ERR value is not a valid float')
RETURNS DOUBLE PRECISION
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v NUMERIC;
BEGIN
    IF p_text ~ '^-?[0-9]{1,15}$' THEN
        RETURN p_text::double precision;
    END IF;
    IF length(p_text) <= 400 AND p_text ~ '^[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)([eE][+-]?[0-9]{1,4})?$' THEN
        v := p_text::numeric;
        IF abs(v) <= 1.7976931348623158e308 AND (v = 0 OR abs(v) >= 2.4703282292062328e-324) THEN
            RETURN p_text::double precision;
        END IF;
    ELSIF p_text ~* '^[+-]?inf(inity)?$' THEN
        RETURN CASE WHEN left(p_text, 1) = '-' THEN '-infinity' ELSE 'infinity' END::double precision;
    ELSIF p_text ~* '^[+-]?0x[0-9a-f]{1,15}$' THEN
        RETURN (CASE WHEN left(p_text, 1) = '-' THEN -1 ELSE 1 END)
            * ('x' || lpad(regexp_replace(p_text, '^[+-]?0[xX]', ''), 16, '0'))::bit(64)::bigint;
    END IF;
    RAISE EXCEPTION '%', p_message USING ERRCODE = 'KV000';
END;
$$;

-- _DECIMAL: parse a number for INCRBYFLOAT, which Redis computes in long double: the same
-- syntax as pgkv._float over a wider range. o_value is NULL if the text is not a number;
-- o_infinite is 1 or -1 for an infinity.
CREATE OR REPLACE FUNCTION pgkv._decimal(p_text TEXT, OUT o_value NUMERIC, OUT o_infinite INTEGER)
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
    o_infinite := 0;
    IF length(p_text) <= 5000 AND p_text ~ '^[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)([eE][+-]?[0-9]{1,4})?$' THEN
        o_value := p_text::numeric;
        IF abs(o_value) > 1.18973149535723176e4932 THEN
            o_value := NULL;
        END IF;
    ELSIF p_text ~* '^[+-]?inf(inity)?$' THEN
        o_infinite := CASE WHEN left(p_text, 1) = '-' THEN -1 ELSE 1 END;
        o_value := 0;
    ELSIF p_text ~* '^[+-]?0x[0-9a-f]{1,15}$' THEN
        o_value := pgkv._float(p_text);
    END IF;
END;
$$;

-- _FMT: a double as Redis prints it: whole numbers as integers, otherwise the shortest digits
-- that read back as the same double, in plain or exponent notation by the rules of Redis's
-- fpconv_dtoa ("0.000001", "1e-7", "123456789012345680", "1e+20").
CREATE OR REPLACE FUNCTION pgkv._fmt(p_value DOUBLE PRECISION)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_text TEXT;
    v_parts TEXT[];
    v_digits TEXT;
    v_k INTEGER;
    v_n INTEGER;
    v_exp INTEGER;
    v_sign TEXT := '';
BEGIN
    IF p_value IS NULL THEN
        RETURN NULL;
    ELSIF p_value = 'infinity' THEN
        RETURN 'inf';
    ELSIF p_value = '-infinity' THEN
        RETURN '-inf';
    ELSIF p_value = 0 THEN
        RETURN p_value::text;
    ELSIF abs(p_value) <= 4611686018427387903 AND p_value = trunc(p_value) THEN
        RETURN (p_value::bigint)::text;
    END IF;

    -- PostgreSQL prints the shortest round-trip digits; only the layout differs.
    v_text := p_value::text;
    IF left(v_text, 1) = '-' THEN
        v_sign := '-';
        v_text := substr(v_text, 2);
    END IF;
    v_parts := regexp_match(v_text, '^([0-9]*)\.?([0-9]*)(?:e([+-]?[0-9]+))?$');
    v_k := COALESCE(v_parts[3]::integer, 0) - length(v_parts[2]);
    v_digits := ltrim(v_parts[1] || v_parts[2], '0');
    v_k := v_k + length(v_digits) - length(rtrim(v_digits, '0'));
    v_digits := rtrim(v_digits, '0');
    v_n := length(v_digits);
    v_exp := abs(v_k + v_n - 1);

    IF v_k >= 0 AND v_exp < v_n + 7 THEN
        RETURN v_sign || v_digits || repeat('0', v_k);
    ELSIF v_k < 0 AND (v_k > -7 OR v_exp < 4) THEN
        IF v_n + v_k <= 0 THEN
            RETURN v_sign || '0.' || repeat('0', -(v_n + v_k)) || v_digits;
        END IF;
        RETURN v_sign || left(v_digits, v_n + v_k) || '.' || substr(v_digits, v_n + v_k + 1);
    END IF;
    RETURN v_sign || left(v_digits, 1) || CASE WHEN v_n > 1 THEN '.' || substr(v_digits, 2) ELSE '' END
        || 'e' || CASE WHEN v_k + v_n - 1 < 0 THEN '-' ELSE '+' END || v_exp;
END;
$$;

-- _FADD, _FMUL, _FSUM: double arithmetic that overflows to infinity (and underflows to 0)
-- as IEEE arithmetic does in Redis, where PostgreSQL raises an error.
CREATE OR REPLACE FUNCTION pgkv._fadd(a DOUBLE PRECISION, b DOUBLE PRECISION)
RETURNS DOUBLE PRECISION
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
    SELECT CASE
        WHEN a > 0 AND b > 0 AND a > 1.7976931348623157e308::double precision - b THEN 'infinity'::double precision
        WHEN a < 0 AND b < 0 AND a < -1.7976931348623157e308::double precision - b THEN '-infinity'::double precision
        ELSE a + b END
$$;

CREATE OR REPLACE FUNCTION pgkv._fmul(a DOUBLE PRECISION, b DOUBLE PRECISION)
RETURNS DOUBLE PRECISION
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
    SELECT CASE
        WHEN a = 0 OR b = 0 OR a = 'NaN' OR b = 'NaN' THEN a * b
        WHEN abs(a) = 'infinity' OR abs(b) = 'infinity' THEN sign(a) * sign(b) * 'infinity'::double precision
        WHEN abs(a) > 1 AND abs(b) > 1.7976931348623157e308::double precision / abs(a)
            THEN sign(a) * sign(b) * 'infinity'::double precision
        WHEN abs(a) < 1 AND abs(b) < 4.9406564584124654e-324::double precision / abs(a) THEN 0
        ELSE a * b END
$$;

CREATE OR REPLACE AGGREGATE pgkv._fsum(DOUBLE PRECISION) (
    SFUNC = pgkv._fadd,
    STYPE = DOUBLE PRECISION
);

-- _ROUND17: a numeric rounded to 17 decimal places, which is how Redis prints an
-- INCRBYFLOAT result ("%.17Lf", trailing zeros removed).
CREATE OR REPLACE FUNCTION pgkv._round17(p_value NUMERIC)
RETURNS NUMERIC
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT round(p_value, 17)
$$;

-- _NUM_TEXT: a numeric without trailing zeros (INCRBYFLOAT results).
CREATE OR REPLACE FUNCTION pgkv._num_text(p_value NUMERIC)
RETURNS TEXT
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT CASE WHEN p_value::text LIKE '%.%'
        THEN regexp_replace(regexp_replace(p_value::text, '0+$', ''), '\.$', '')
        ELSE p_value::text END
$$;

-- _GLOB_RE: a Redis glob pattern as an anchored regular expression.
CREATE OR REPLACE FUNCTION pgkv._glob_re(p_pattern TEXT)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_out TEXT := '^';
    v_i INTEGER := 1;
    v_len INTEGER := length(p_pattern);
    v_ch TEXT;
    v_j INTEGER;
    v_class TEXT;
    v_closed BOOLEAN;
BEGIN
    WHILE v_i <= v_len LOOP
        v_ch := substr(p_pattern, v_i, 1);
        IF v_ch = '*' THEN
            v_out := v_out || '.*';
        ELSIF v_ch = '?' THEN
            v_out := v_out || '.';
        ELSIF v_ch = E'\\' AND v_i < v_len THEN
            v_i := v_i + 1;
            v_out := v_out || regexp_replace(substr(p_pattern, v_i, 1), '([!-/:-@\[-`{-~])', '\\\1');
        ELSIF v_ch = '[' THEN
            v_j := v_i + 1;
            v_class := '';
            v_closed := FALSE;
            IF substr(p_pattern, v_j, 1) = '^' THEN
                v_class := '^';
                v_j := v_j + 1;
            END IF;
            WHILE v_j <= v_len LOOP
                v_ch := substr(p_pattern, v_j, 1);
                IF v_ch = ']' THEN
                    v_closed := TRUE;
                    EXIT;
                ELSIF v_ch = E'\\' AND v_j < v_len THEN
                    v_j := v_j + 1;
                    v_class := v_class || regexp_replace(substr(p_pattern, v_j, 1), '([!-/:-@\[-`{-~])', '\\\1');
                ELSIF v_ch = '-' AND v_class NOT IN ('', '^') AND v_j < v_len AND substr(p_pattern, v_j + 1, 1) <> ']' THEN
                    v_class := v_class || '-';
                ELSE
                    v_class := v_class || regexp_replace(v_ch, '([!-/:-@\[-`{-~])', '\\\1');
                END IF;
                v_j := v_j + 1;
            END LOOP;
            IF v_closed AND v_class NOT IN ('', '^') THEN
                v_out := v_out || '[' || v_class || ']';
                v_i := v_j;
            ELSE
                v_out := v_out || '\[';
            END IF;
        ELSE
            v_out := v_out || regexp_replace(v_ch, '([!-/:-@\[-`{-~])', '\\\1');
        END IF;
        v_i := v_i + 1;
    END LOOP;
    RETURN v_out || '$';
END;
$$;

-- _LIKE_PREFIX: a LIKE pattern matching keys that start with p_prefix, taken literally.
CREATE OR REPLACE FUNCTION pgkv._like_prefix(p_prefix TEXT)
RETURNS TEXT
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT replace(replace(replace(COALESCE(p_prefix, ''), E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%'
$$;

-- _DROP_ELEMS: delete the elements of one collection.
CREATE OR REPLACE FUNCTION pgkv._drop_elems(p_id BIGINT, p_type TEXT)
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    IF p_id IS NULL THEN
        RETURN;
    END IF;
    CASE p_type
        WHEN 'hash' THEN DELETE FROM pgkv.hash_fields WHERE id = p_id;
        WHEN 'list' THEN DELETE FROM pgkv.list_items WHERE id = p_id;
        WHEN 'set' THEN DELETE FROM pgkv.set_members WHERE id = p_id;
        WHEN 'zset' THEN DELETE FROM pgkv.zset_members WHERE id = p_id;
        ELSE NULL;
    END CASE;
END;
$$;

-- _DROP_MANY: delete the elements of several collections whose rows are already gone.
CREATE OR REPLACE FUNCTION pgkv._drop_many(p_ids BIGINT[])
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    IF p_ids IS NULL OR cardinality(p_ids) = 0 THEN
        RETURN;
    END IF;
    DELETE FROM pgkv.hash_fields WHERE id = ANY(p_ids);
    DELETE FROM pgkv.list_items WHERE id = ANY(p_ids);
    DELETE FROM pgkv.set_members WHERE id = ANY(p_ids);
    DELETE FROM pgkv.zset_members WHERE id = ANY(p_ids);
END;
$$;

-- _LOCK_KEY: lock a key's row for the rest of the transaction and return its live contents.
-- o_type IS NULL means the key is absent (an expired key counts as absent and is removed,
-- with its elements). With p_create, an absent key gets a placeholder row (already expired,
-- so no reader sees it) that this transaction holds; the caller must overwrite it with
-- pgkv._put or pgkv._save, or delete it. This is what makes read-modify-write safe under
-- READ COMMITTED: a second writer of the same key waits here, then reads what the first
-- one committed.
CREATE OR REPLACE FUNCTION pgkv._lock_key(
    p_key TEXT,
    p_create BOOLEAN,
    OUT o_value JSONB,
    OUT o_type TEXT,
    OUT o_expires_at TIMESTAMPTZ,
    OUT o_id BIGINT,
    OUT o_card BIGINT,
    OUT o_head BIGINT
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_attempt INTEGER;
BEGIN
    FOR v_attempt IN 1..100 LOOP
        SELECT s.value, s.type, s.expires_at, s.id, s.card, s.head
        INTO o_value, o_type, o_expires_at, o_id, o_card, o_head
        FROM pgkv.store s
        WHERE s.key = p_key
        FOR UPDATE;

        IF FOUND THEN
            IF o_expires_at IS NULL OR o_expires_at >= clock_timestamp() THEN
                RETURN;
            END IF;
            -- Expired: the row is locked, so nobody can have replaced it. Remove it.
            PERFORM pgkv._drop_elems(o_id, o_type);
            DELETE FROM pgkv.store s WHERE s.key = p_key;
            o_value := NULL;
            o_type := NULL;
            o_expires_at := NULL;
            o_id := NULL;
            o_card := NULL;
            o_head := NULL;
        END IF;

        IF NOT p_create THEN
            RETURN;
        END IF;

        INSERT INTO pgkv.store (key, value, type, expires_at)
        VALUES (p_key, NULL, 'string', '-infinity')
        ON CONFLICT (key) DO NOTHING;
        IF FOUND THEN
            RETURN;
        END IF;

        -- Another session created the key in the meantime. At READ COMMITTED the next pass sees it;
        -- a snapshot isolation level never will, so report the conflict for the caller to retry.
        IF current_setting('transaction_isolation') <> 'read committed' THEN
            RAISE EXCEPTION 'could not serialize access to key due to concurrent update'
                USING ERRCODE = 'serialization_failure';
        END IF;
    END LOOP;

    RAISE EXCEPTION 'could not lock key after repeated concurrent changes'
        USING ERRCODE = 'serialization_failure';
END;
$$;

-- _PUT: write a string or JSON value to a key whose row the transaction holds through
-- pgkv._lock_key. The caller removes the elements first if the key held a collection.
CREATE OR REPLACE FUNCTION pgkv._put(p_key TEXT, p_value JSONB, p_type TEXT, p_expires_at TIMESTAMPTZ)
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE pgkv.store s
    SET value = p_value,
        type = p_type,
        expires_at = p_expires_at,
        id = NULL,
        card = NULL,
        head = NULL,
        updated_at = NOW()
    WHERE s.key = p_key;
END;
$$;

-- _SAVE: write a collection's header to a key whose row the transaction holds through
-- pgkv._lock_key. A collection with no elements does not exist, so its row is deleted.
CREATE OR REPLACE FUNCTION pgkv._save(p_key TEXT, p_type TEXT, p_id BIGINT, p_card BIGINT, p_head BIGINT, p_expires_at TIMESTAMPTZ)
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    IF p_card <= 0 THEN
        DELETE FROM pgkv.store s WHERE s.key = p_key;
    ELSE
        UPDATE pgkv.store s
        SET value = NULL,
            type = p_type,
            expires_at = p_expires_at,
            id = p_id,
            card = p_card,
            head = p_head,
            updated_at = NOW()
        WHERE s.key = p_key;
    END IF;
END;
$$;

-- _OPEN: lock a key for a write to a collection of type p_type. Raises WRONGTYPE if the key
-- holds something else. A key that is absent comes back with o_new set and, with p_create,
-- a fresh id and a placeholder row that the caller must finish with pgkv._save.
CREATE OR REPLACE FUNCTION pgkv._open(
    p_key TEXT,
    p_type TEXT,
    p_create BOOLEAN,
    OUT o_id BIGINT,
    OUT o_card BIGINT,
    OUT o_head BIGINT,
    OUT o_expires_at TIMESTAMPTZ,
    OUT o_new BOOLEAN
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_locked RECORD;
    v_type TEXT;
BEGIN
    -- The common case, a key that exists and has not expired, takes one statement.
    SELECT s.type, s.id, s.card, s.head, s.expires_at INTO v_type, o_id, o_card, o_head, o_expires_at
    FROM pgkv.store s
    WHERE s.key = p_key
    FOR UPDATE;

    IF NOT FOUND OR o_expires_at < clock_timestamp() THEN
        v_locked := pgkv._lock_key(p_key, p_create);
        v_type := v_locked.o_type;
        o_id := v_locked.o_id;
        o_card := v_locked.o_card;
        o_head := v_locked.o_head;
        o_expires_at := v_locked.o_expires_at;
    END IF;

    IF v_type IS NULL THEN
        o_new := TRUE;
        o_card := 0;
        o_head := 0;
        o_expires_at := NULL;
        IF p_create THEN
            o_id := nextval('pgkv.collection_id');
        END IF;
    ELSIF v_type <> p_type THEN
        PERFORM pgkv._wrongtype();
    ELSE
        o_new := FALSE;
    END IF;
END;
$$;

-- _PEEK: read a collection's header without locking. o_id IS NULL means the key is absent.
-- Raises WRONGTYPE if the key holds another type.
CREATE OR REPLACE FUNCTION pgkv._peek(p_key TEXT, p_type TEXT, OUT o_id BIGINT, OUT o_card BIGINT, OUT o_head BIGINT)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_type TEXT;
BEGIN
    SELECT s.type, s.id, s.card, s.head INTO v_type, o_id, o_card, o_head
    FROM pgkv.store s
    WHERE s.key = p_key AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp());

    IF v_type IS NOT NULL AND v_type <> p_type THEN
        PERFORM pgkv._wrongtype();
    END IF;
END;
$$;

-- _REQUIRE_STRING: raise WRONGTYPE if the key exists and is not a string.
CREATE OR REPLACE FUNCTION pgkv._require_string(p_key TEXT)
RETURNS VOID
LANGUAGE plpgsql
STABLE
AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pgkv.store s
        WHERE s.key = p_key
          AND s.type != 'string'
          AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp())
    ) THEN
        PERFORM pgkv._wrongtype();
    END IF;
END;
$$;

-- _WHEN: the expiry time for a Redis expire argument. p_unit is 's' or 'ms'; p_absolute means
-- a Unix time rather than a duration. Times PostgreSQL cannot hold are an error, as overflow
-- is in Redis.
CREATE OR REPLACE FUNCTION pgkv._when(p_amount BIGINT, p_unit TEXT, p_absolute BOOLEAN, p_command TEXT)
RETURNS TIMESTAMPTZ
LANGUAGE plpgsql
AS $$
DECLARE
    v_ms NUMERIC := p_amount::numeric * CASE WHEN p_unit = 's' THEN 1000 ELSE 1 END;
BEGIN
    -- Redis keeps the time as a 64-bit count of milliseconds and rejects what overflows it.
    IF v_ms NOT BETWEEN -9223372036854775808 AND 9223372036854775807 THEN
        RAISE EXCEPTION 'ERR invalid expire time in ''%'' command', p_command USING ERRCODE = 'KV000';
    END IF;
    IF NOT p_absolute THEN
        v_ms := v_ms + trunc(extract(epoch FROM clock_timestamp())::numeric * 1000);
    END IF;
    -- 9999-12-31; beyond it a timestamp is no longer a usable expiry.
    IF v_ms > 253402300799999 THEN
        RAISE EXCEPTION 'ERR invalid expire time in ''%'' command', p_command USING ERRCODE = 'KV000';
    END IF;
    IF v_ms < -62135596800000 THEN
        RETURN '-infinity';
    END IF;
    RETURN to_timestamp(v_ms / 1000.0);
END;
$$;

-- _EXPIRES_AT: the expiry time for SET-style options. NULL means no expiry.
CREATE OR REPLACE FUNCTION pgkv._expires_at(p_ex BIGINT, p_px BIGINT, p_exat BIGINT, p_pxat BIGINT, p_keepttl BOOLEAN, p_command TEXT DEFAULT 'set')
RETURNS TIMESTAMPTZ
LANGUAGE plpgsql
AS $$
BEGIN
    IF (CASE WHEN p_ex IS NOT NULL THEN 1 ELSE 0 END +
        CASE WHEN p_px IS NOT NULL THEN 1 ELSE 0 END +
        CASE WHEN p_exat IS NOT NULL THEN 1 ELSE 0 END +
        CASE WHEN p_pxat IS NOT NULL THEN 1 ELSE 0 END +
        CASE WHEN p_keepttl THEN 1 ELSE 0 END) > 1 THEN
        RAISE EXCEPTION 'ERR syntax error' USING ERRCODE = 'KV000';
    END IF;

    IF COALESCE(p_ex, p_px, p_exat, p_pxat) <= 0 THEN
        RAISE EXCEPTION 'ERR invalid expire time in ''%'' command', p_command USING ERRCODE = 'KV000';
    END IF;

    IF p_ex IS NOT NULL THEN
        RETURN pgkv._when(p_ex, 's', FALSE, p_command);
    ELSIF p_px IS NOT NULL THEN
        RETURN pgkv._when(p_px, 'ms', FALSE, p_command);
    ELSIF p_exat IS NOT NULL THEN
        RETURN pgkv._when(p_exat, 's', TRUE, p_command);
    ELSIF p_pxat IS NOT NULL THEN
        RETURN pgkv._when(p_pxat, 'ms', TRUE, p_command);
    END IF;
    RETURN NULL;
END;
$$;

-- _LOCK_KEYS: lock several keys in key order, so that two multi-key commands cannot
-- deadlock each other. p_create lists the keys that get a placeholder row if absent.
CREATE OR REPLACE FUNCTION pgkv._lock_keys(p_keys TEXT[], p_create TEXT[] DEFAULT NULL)
RETURNS VOID
LANGUAGE plpgsql
AS $$
DECLARE
    v_key TEXT;
BEGIN
    FOR v_key IN
        SELECT k FROM unnest(p_keys || COALESCE(p_create, '{}')) AS u(k) WHERE k IS NOT NULL GROUP BY k ORDER BY k COLLATE "C"
    LOOP
        PERFORM pgkv._lock_key(v_key, v_key = ANY(COALESCE(p_create, '{}')));
    END LOOP;
END;
$$;

-- _RANGE: turn Redis start/stop indexes (negative counts from the end) into a zero-based
-- offset and a length over p_card elements. o_len is 0 when the range is empty.
CREATE OR REPLACE FUNCTION pgkv._range(p_start BIGINT, p_stop BIGINT, p_card BIGINT, OUT o_off BIGINT, OUT o_len BIGINT)
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_start NUMERIC := p_start;
    v_stop NUMERIC := p_stop;
BEGIN
    IF v_start < 0 THEN v_start := GREATEST(v_start + p_card, 0); END IF;
    IF v_stop < 0 THEN v_stop := v_stop + p_card; END IF;
    IF v_stop >= p_card THEN v_stop := p_card - 1; END IF;
    IF p_card IS NULL OR v_start > v_stop OR v_start >= p_card THEN
        o_off := 0;
        o_len := 0;
    ELSE
        o_off := v_start;
        o_len := v_stop - v_start + 1;
    END IF;
END;
$$;

-- REDIS_TO_PG_PATTERN: Convert Redis glob pattern to PostgreSQL LIKE pattern.
-- Returns NULL if the pattern contains character classes (pgkv matches those as a regular expression).
CREATE OR REPLACE FUNCTION pgkv.redis_to_pg_pattern(p_redis_pattern TEXT)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_result TEXT := '';
    v_i INTEGER := 1;
    v_char TEXT;
    v_next_char TEXT;
    v_len INTEGER := length(p_redis_pattern);
BEGIN
    WHILE v_i <= v_len LOOP
        v_char := substring(p_redis_pattern FROM v_i FOR 1);

        -- Handle Redis escape sequences
        IF v_char = E'\\' AND v_i < v_len THEN
            v_next_char := substring(p_redis_pattern FROM v_i + 1 FOR 1);
            -- Escaped character becomes literal, but must escape PostgreSQL special chars
            IF v_next_char IN ('%', '_', E'\\') THEN
                v_result := v_result || E'\\' || v_next_char;
            ELSE
                v_result := v_result || v_next_char;
            END IF;
            v_i := v_i + 2;
            CONTINUE;
        END IF;

        -- Check for character classes (not supported by LIKE, need regex)
        IF v_char = '[' THEN
            -- Return NULL to signal caller to use regex
            RETURN NULL;
        END IF;

        -- Convert Redis wildcards to PostgreSQL LIKE wildcards
        IF v_char = '*' THEN
            v_result := v_result || '%';
        ELSIF v_char = '?' THEN
            v_result := v_result || '_';
        -- Escape PostgreSQL special characters
        ELSIF v_char IN ('%', '_', E'\\') THEN
            v_result := v_result || E'\\' || v_char;
        ELSE
            v_result := v_result || v_char;
        END IF;

        v_i := v_i + 1;
    END LOOP;

    RETURN v_result;
END;
$$;

-- ============================================================================
-- Keys and expiry
-- ============================================================================

-- DEL: Delete one or more keys
-- Returns the number of keys that existed (an expired key is removed but not counted)
CREATE OR REPLACE FUNCTION pgkv.del(VARIADIC p_keys TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_deleted INTEGER;
    v_ids BIGINT[];
BEGIN
    -- Lock the rows in key order first, so two multi-key calls cannot deadlock each other.
    WITH locked AS (
        SELECT s.key FROM pgkv.store s WHERE s.key = ANY(p_keys) ORDER BY s.key FOR UPDATE
    ), deleted AS (
        DELETE FROM pgkv.store s USING locked l WHERE s.key = l.key RETURNING s.expires_at, s.id
    )
    SELECT (COUNT(*) FILTER (WHERE d.expires_at IS NULL OR d.expires_at >= clock_timestamp()))::integer,
           array_agg(d.id) FILTER (WHERE d.id IS NOT NULL)
    INTO v_deleted, v_ids
    FROM deleted d;

    IF v_ids IS NOT NULL THEN
        PERFORM pgkv._drop_many(v_ids);
    END IF;
    RETURN v_deleted;
END;
$$;

-- EXISTS: Count the keys that exist (a key named twice counts twice)
CREATE OR REPLACE FUNCTION pgkv.exists(VARIADIC p_keys TEXT[])
RETURNS INTEGER
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
    SELECT COUNT(*)::integer
    FROM unnest(p_keys) AS k(key)
    JOIN pgkv.store s ON s.key = k.key
    WHERE s.expires_at IS NULL OR s.expires_at >= clock_timestamp()
$$;

-- TOUCH: Count the keys that exist (pgkv keeps no access time to update)
CREATE OR REPLACE FUNCTION pgkv.touch(VARIADIC p_keys TEXT[])
RETURNS INTEGER
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
    SELECT pgkv.exists(VARIADIC p_keys)
$$;

-- TYPE: Get the type of value stored at key ('none' if the key does not exist)
CREATE OR REPLACE FUNCTION pgkv.type(p_key TEXT)
RETURNS TEXT
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
    SELECT COALESCE((
        SELECT s.type FROM pgkv.store s
        WHERE s.key = p_key AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp())
    ), 'none')
$$;

-- _EXPIRE_MODE: check the options of EXPIRE and friends (any of NX, XX, GT, LT) and return
-- them in upper case.
CREATE OR REPLACE FUNCTION pgkv._expire_mode(p_options TEXT[])
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_option TEXT;
    v_mode TEXT := '';
BEGIN
    FOREACH v_option IN ARRAY COALESCE(p_options, '{}') LOOP
        IF upper(v_option) NOT IN ('NX', 'XX', 'GT', 'LT') THEN
            RAISE EXCEPTION 'ERR Unsupported option %', v_option USING ERRCODE = 'KV000';
        END IF;
        v_mode := v_mode || upper(v_option) || ' ';
    END LOOP;
    IF v_mode ~ 'NX' AND v_mode ~ '(XX|GT|LT)' THEN
        RAISE EXCEPTION 'ERR NX and XX, GT or LT options at the same time are not compatible' USING ERRCODE = 'KV000';
    ELSIF v_mode ~ 'GT' AND v_mode ~ 'LT' THEN
        RAISE EXCEPTION 'ERR GT and LT options at the same time are not compatible' USING ERRCODE = 'KV000';
    END IF;
    RETURN v_mode;
END;
$$;

-- _EXPIRE: set a key's expiry time. p_mode holds any of NX, XX, GT, LT (Redis 7 semantics:
-- a key without expiry counts as infinite for GT and LT). A time in the past deletes the key.
CREATE OR REPLACE FUNCTION pgkv._expire(p_key TEXT, p_at TIMESTAMPTZ, p_mode TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_locked RECORD;
    v_type TEXT;
    v_id BIGINT;
    v_current TIMESTAMPTZ;
    v_mode TEXT := pgkv._expire_mode(regexp_split_to_array(NULLIF(btrim(p_mode), ''), '\s+'));
BEGIN
    v_locked := pgkv._lock_key(p_key, FALSE);
    v_type := v_locked.o_type;
    v_id := v_locked.o_id;
    v_current := v_locked.o_expires_at;
    IF v_type IS NULL THEN
        RETURN 0;
    END IF;

    IF (v_mode ~ 'NX' AND v_current IS NOT NULL)
        OR (v_mode ~ 'XX' AND v_current IS NULL)
        OR (v_mode ~ 'GT' AND (v_current IS NULL OR p_at <= v_current))
        OR (v_mode ~ 'LT' AND v_current IS NOT NULL AND p_at >= v_current) THEN
        RETURN 0;
    END IF;

    IF p_at <= clock_timestamp() THEN
        PERFORM pgkv._drop_elems(v_id, v_type);
        DELETE FROM pgkv.store s WHERE s.key = p_key;
    ELSE
        UPDATE pgkv.store s SET expires_at = p_at, updated_at = NOW() WHERE s.key = p_key;
    END IF;
    RETURN 1;
END;
$$;

-- EXPIRE: Set a timeout on a key, in seconds. p_mode is NX, XX, GT or LT.
-- Returns 1 if the timeout was set, 0 if not (the key does not exist, or p_mode stopped it).
CREATE OR REPLACE FUNCTION pgkv.expire(p_key TEXT, p_seconds BIGINT, p_mode TEXT DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._expire(p_key, pgkv._when(p_seconds, 's', FALSE, 'expire'), p_mode);
END;
$$;

-- PEXPIRE: EXPIRE in milliseconds
CREATE OR REPLACE FUNCTION pgkv.pexpire(p_key TEXT, p_milliseconds BIGINT, p_mode TEXT DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._expire(p_key, pgkv._when(p_milliseconds, 'ms', FALSE, 'pexpire'), p_mode);
END;
$$;

-- EXPIREAT: Set the expiry of a key as a Unix time in seconds
CREATE OR REPLACE FUNCTION pgkv.expireat(p_key TEXT, p_unix_seconds BIGINT, p_mode TEXT DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._expire(p_key, pgkv._when(p_unix_seconds, 's', TRUE, 'expireat'), p_mode);
END;
$$;

-- PEXPIREAT: Set the expiry of a key as a Unix time in milliseconds
CREATE OR REPLACE FUNCTION pgkv.pexpireat(p_key TEXT, p_unix_milliseconds BIGINT, p_mode TEXT DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._expire(p_key, pgkv._when(p_unix_milliseconds, 'ms', TRUE, 'pexpireat'), p_mode);
END;
$$;

-- PERSIST: Remove the expiry from a key. Returns 1 if an expiry was removed.
CREATE OR REPLACE FUNCTION pgkv.persist(p_key TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    UPDATE pgkv.store s SET expires_at = NULL, updated_at = NOW()
    WHERE s.key = p_key AND s.expires_at >= clock_timestamp();
    RETURN CASE WHEN FOUND THEN 1 ELSE 0 END;
END;
$$;

-- PEXPIRETIME: The Unix time in milliseconds at which a key expires
-- Returns -2 if the key does not exist, -1 if it has no expiry
CREATE OR REPLACE FUNCTION pgkv.pexpiretime(p_key TEXT)
RETURNS BIGINT
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
    SELECT COALESCE((
        SELECT CASE WHEN s.expires_at IS NULL THEN -1
                    ELSE round(extract(epoch FROM s.expires_at)::numeric * 1000)::bigint END
        FROM pgkv.store s
        WHERE s.key = p_key AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp())
    ), -2)
$$;

-- EXPIRETIME: The Unix time in seconds at which a key expires (-2 no key, -1 no expiry)
CREATE OR REPLACE FUNCTION pgkv.expiretime(p_key TEXT)
RETURNS BIGINT
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
    SELECT CASE WHEN t < 0 THEN t ELSE t / 1000 END FROM pgkv.pexpiretime(p_key) AS t
$$;

-- PTTL: Time to live of a key in milliseconds (-2 no key, -1 no expiry)
CREATE OR REPLACE FUNCTION pgkv.pttl(p_key TEXT)
RETURNS BIGINT
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
    SELECT COALESCE((
        SELECT CASE WHEN s.expires_at IS NULL THEN -1
                    ELSE GREATEST(round(extract(epoch FROM s.expires_at - clock_timestamp())::numeric * 1000), 0)::bigint END
        FROM pgkv.store s
        WHERE s.key = p_key AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp())
    ), -2)
$$;

-- TTL: Time to live of a key in seconds, rounded (-2 no key, -1 no expiry)
-- The result is capped at the largest integer; pgkv.pttl has no cap.
CREATE OR REPLACE FUNCTION pgkv.ttl(p_key TEXT)
RETURNS INTEGER
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
    SELECT CASE WHEN t < 0 THEN t ELSE LEAST((t + 500) / 1000, 2147483647) END::integer FROM pgkv.pttl(p_key) AS t
$$;

-- KEYS: Find all keys matching a Redis glob pattern (*, ?, [abc], [a-z], [^a], \x)
-- Reads the whole table unless the pattern starts with a literal prefix.
CREATE OR REPLACE FUNCTION pgkv.keys(p_pattern TEXT DEFAULT '*')
RETURNS SETOF TEXT
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    -- The pattern goes in as a literal so the planner can turn its prefix into index bounds.
    RETURN QUERY EXECUTE format(
        'SELECT s.key::text FROM pgkv.store s
         WHERE %s AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp())
         ORDER BY s.key',
        CASE WHEN p_pattern = '*' THEN 'TRUE' ELSE format('s.key ~ %L', pgkv._glob_re(p_pattern)) END
    );
END;
$$;

-- _SCAN: one page of keys in byte order. o_next is 0 when the sweep is complete.
CREATE OR REPLACE FUNCTION pgkv._scan(p_cursor BIGINT, p_pattern TEXT, p_count BIGINT, p_type TEXT, OUT o_next BIGINT, OUT o_keys TEXT[])
LANGUAGE plpgsql
STABLE
AS $$
BEGIN
    EXECUTE format(
        'SELECT ARRAY(
             SELECT s.key::text FROM pgkv.store s
             WHERE %s AND %s AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp())
             ORDER BY s.key
             OFFSET $1 LIMIT $2)',
        CASE WHEN COALESCE(p_pattern, '*') = '*' THEN 'TRUE' ELSE format('s.key ~ %L', pgkv._glob_re(p_pattern)) END,
        CASE WHEN p_type IS NULL THEN 'TRUE' ELSE format('s.type = %L', lower(p_type)) END)
    INTO o_keys USING p_cursor, p_count + 1;

    IF cardinality(o_keys) > p_count THEN
        o_next := p_cursor + p_count;
        o_keys := o_keys[1:p_count];
    ELSE
        o_next := 0;
    END IF;
END;
$$;

-- SCAN: Iterate the keys matching a pattern, p_count at a time, optionally of one type.
-- Each row carries the cursor for the next call; 0 means the sweep is complete. The cursor
-- is an offset, so keys added or removed during a sweep can shift later pages:
-- pgkv.scan_prefix pages by key and does not have that problem.
CREATE OR REPLACE FUNCTION pgkv.scan(p_cursor BIGINT DEFAULT 0, p_pattern TEXT DEFAULT '*', p_count INTEGER DEFAULT 10, p_type TEXT DEFAULT NULL)
RETURNS TABLE(cursor BIGINT, key TEXT)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_next BIGINT;
    v_keys TEXT[];
BEGIN
    IF p_cursor < 0 OR p_count <= 0 THEN
        PERFORM pgkv._err('ERR invalid cursor or count');
    END IF;
    SELECT s.o_next, s.o_keys INTO v_next, v_keys FROM pgkv._scan(p_cursor, p_pattern, p_count, p_type) s;
    RETURN QUERY SELECT v_next, u.k FROM unnest(v_keys) WITH ORDINALITY AS u(k, ord) ORDER BY u.ord;
END;
$$;

-- _VALUE: a key's value as one JSONB document: the stored value for a string or JSON key,
-- and for a collection its elements (hash: object, list and set: array, sorted set: object
-- of member to score, infinite scores as strings).
CREATE OR REPLACE FUNCTION pgkv._value(p_type TEXT, p_value JSONB, p_id BIGINT)
RETURNS JSONB
LANGUAGE sql
STABLE
AS $$
    SELECT CASE p_type
        WHEN 'hash' THEN (SELECT COALESCE(jsonb_object_agg(f.field, f.value), '{}'::jsonb) FROM pgkv.hash_fields f WHERE f.id = p_id)
        WHEN 'list' THEN (SELECT COALESCE(jsonb_agg(i.value ORDER BY i.pos), '[]'::jsonb) FROM pgkv.list_items i WHERE i.id = p_id)
        WHEN 'set' THEN (SELECT COALESCE(jsonb_agg(m.member ORDER BY m.member), '[]'::jsonb) FROM pgkv.set_members m WHERE m.id = p_id)
        WHEN 'zset' THEN (SELECT COALESCE(jsonb_object_agg(z.member,
                CASE WHEN z.score IN ('infinity', '-infinity') THEN to_jsonb(z.score::text) ELSE to_jsonb(z.score) END), '{}'::jsonb)
            FROM pgkv.zset_members z WHERE z.id = p_id)
        ELSE p_value
    END
$$;

-- SCAN_PREFIX: List the keys that start with p_prefix (taken literally, no wildcards), in
-- byte order, p_count at a time. To page, pass the last key of the previous page as p_after;
-- a page shorter than p_count is the last. This is keyset paging: keys added or removed
-- during a sweep never shift, repeat or hide other keys. It reads an index range, skips
-- expired keys and writes nothing. A collection's value is assembled from its elements.
CREATE OR REPLACE FUNCTION pgkv.scan_prefix(p_prefix TEXT DEFAULT '', p_after TEXT DEFAULT NULL, p_count INTEGER DEFAULT 10)
RETURNS TABLE(key TEXT, type TEXT, value JSONB, expires_at TIMESTAMPTZ)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    IF p_count IS NULL OR p_count <= 0 THEN
        PERFORM pgkv._err('ERR invalid count');
    END IF;

    -- Prefix and cursor go in as literals so the planner can use them as index bounds.
    RETURN QUERY EXECUTE format(
        'SELECT p.key::text, p.type, pgkv._value(p.type, p.value, p.id), p.expires_at
         FROM (
             SELECT s.key, s.type, s.value, s.id, s.expires_at
             FROM pgkv.store s
             WHERE s.key LIKE %L
               AND %s
               AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp())
             ORDER BY s.key
             LIMIT %s
         ) p
         ORDER BY p.key',
        pgkv._like_prefix(p_prefix),
        CASE WHEN p_after IS NULL THEN 'TRUE' ELSE format('s.key > %L', p_after) END,
        p_count
    );
END;
$$;

-- RANDOMKEY: A random key, NULL if there are none. Reads every key.
CREATE OR REPLACE FUNCTION pgkv.randomkey()
RETURNS TEXT
LANGUAGE sql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
    SELECT s.key::text FROM pgkv.store s
    WHERE s.expires_at IS NULL OR s.expires_at >= clock_timestamp()
    ORDER BY random() LIMIT 1
$$;

-- RENAME: Rename a key, replacing p_new_key if it exists. The key keeps its expiry.
CREATE OR REPLACE FUNCTION pgkv.rename(p_key TEXT, p_new_key TEXT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_id BIGINT;
    v_type TEXT;
BEGIN
    PERFORM pgkv._lock_keys(ARRAY[p_key, p_new_key]);
    IF NOT EXISTS (SELECT 1 FROM pgkv.store s WHERE s.key = p_key AND s.expires_at IS DISTINCT FROM '-infinity') THEN
        PERFORM pgkv._err('ERR no such key');
    END IF;
    IF p_key <> p_new_key THEN
        DELETE FROM pgkv.store s WHERE s.key = p_new_key RETURNING s.id, s.type INTO v_id, v_type;
        PERFORM pgkv._drop_elems(v_id, v_type);
        UPDATE pgkv.store s SET key = p_new_key, updated_at = NOW() WHERE s.key = p_key;
    END IF;
    RETURN 'OK';
END;
$$;

-- RENAMENX: Rename a key unless p_new_key exists. Returns 1 if renamed, 0 if not.
CREATE OR REPLACE FUNCTION pgkv.renamenx(p_key TEXT, p_new_key TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    PERFORM pgkv._lock_keys(ARRAY[p_key, p_new_key]);
    IF NOT EXISTS (SELECT 1 FROM pgkv.store s WHERE s.key = p_key AND s.expires_at IS DISTINCT FROM '-infinity') THEN
        PERFORM pgkv._err('ERR no such key');
    END IF;
    IF EXISTS (SELECT 1 FROM pgkv.store s WHERE s.key = p_new_key AND s.expires_at IS DISTINCT FROM '-infinity') THEN
        RETURN 0;
    END IF;
    DELETE FROM pgkv.store s WHERE s.key = p_new_key;
    UPDATE pgkv.store s SET key = p_new_key, updated_at = NOW() WHERE s.key = p_key;
    RETURN 1;
END;
$$;

-- COPY: Copy a key's value and expiry to p_destination. Returns 1 if copied, 0 if the
-- source does not exist or the destination exists and p_replace is false.
CREATE OR REPLACE FUNCTION pgkv.copy(p_source TEXT, p_destination TEXT, p_replace BOOLEAN DEFAULT FALSE)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_src pgkv.store%ROWTYPE;
    v_dst pgkv.store%ROWTYPE;
    v_id BIGINT;
BEGIN
    IF p_source = p_destination THEN
        PERFORM pgkv._err('ERR source and destination objects are the same');
    END IF;
    PERFORM pgkv._lock_keys(ARRAY[p_source], ARRAY[p_destination]);
    SELECT * INTO v_src FROM pgkv.store s WHERE s.key = p_source;
    SELECT * INTO v_dst FROM pgkv.store s WHERE s.key = p_destination;

    IF v_src.key IS NULL OR v_src.expires_at = '-infinity'
        OR (v_dst.expires_at IS DISTINCT FROM '-infinity' AND NOT p_replace) THEN
        DELETE FROM pgkv.store s WHERE s.key = p_destination AND s.expires_at = '-infinity';
        RETURN 0;
    END IF;

    PERFORM pgkv._drop_elems(v_dst.id, v_dst.type);
    IF v_src.id IS NOT NULL THEN
        v_id := nextval('pgkv.collection_id');
        CASE v_src.type
            WHEN 'hash' THEN INSERT INTO pgkv.hash_fields SELECT v_id, f.field, f.value FROM pgkv.hash_fields f WHERE f.id = v_src.id;
            WHEN 'list' THEN INSERT INTO pgkv.list_items SELECT v_id, i.pos, i.value FROM pgkv.list_items i WHERE i.id = v_src.id;
            WHEN 'set' THEN INSERT INTO pgkv.set_members SELECT v_id, m.member FROM pgkv.set_members m WHERE m.id = v_src.id;
            WHEN 'zset' THEN INSERT INTO pgkv.zset_members SELECT v_id, z.member, z.score FROM pgkv.zset_members z WHERE z.id = v_src.id;
        END CASE;
    END IF;
    UPDATE pgkv.store s
    SET value = v_src.value, type = v_src.type, expires_at = v_src.expires_at,
        id = v_id, card = v_src.card, head = v_src.head, updated_at = NOW()
    WHERE s.key = p_destination;
    RETURN 1;
END;
$$;

-- CLEANUP_EXPIRED: Delete expired keys, at most p_limit of them if given. Returns the number
-- deleted. Expired keys are invisible to every command and are removed when written to, so
-- this only reclaims space: schedule it (pg_cron, for example) if keys expire unread.
-- Keys another transaction is working on are skipped rather than waited for.
CREATE OR REPLACE FUNCTION pgkv.cleanup_expired(p_limit INTEGER DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_deleted INTEGER;
    v_ids BIGINT[];
BEGIN
    WITH expired AS (
        SELECT s.key FROM pgkv.store s
        WHERE s.expires_at IS NOT NULL AND s.expires_at < clock_timestamp()
        ORDER BY s.expires_at
        LIMIT p_limit
        FOR UPDATE SKIP LOCKED
    ), deleted AS (
        DELETE FROM pgkv.store s USING expired e WHERE s.key = e.key RETURNING s.id
    )
    SELECT COUNT(*)::integer, array_agg(d.id) FILTER (WHERE d.id IS NOT NULL) INTO v_deleted, v_ids FROM deleted d;

    IF v_ids IS NOT NULL THEN
        PERFORM pgkv._drop_many(v_ids);
    END IF;
    RETURN v_deleted;
END;
$$;

-- FLUSHALL: Delete all keys in the store
CREATE OR REPLACE FUNCTION pgkv.flushall()
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    TRUNCATE TABLE pgkv.store, pgkv.hash_fields, pgkv.list_items, pgkv.set_members, pgkv.zset_members;
    RETURN 'OK';
END;
$$;

-- DBSIZE: Return the number of keys in the store. Counts every row.
CREATE OR REPLACE FUNCTION pgkv.dbsize()
RETURNS BIGINT
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
    SELECT COUNT(*) FROM pgkv.store s WHERE s.expires_at IS NULL OR s.expires_at >= clock_timestamp()
$$;

-- SET_UNLOGGED: Make all of pgkv's tables UNLOGGED (true) or logged again (false).
-- Unlogged tables skip the write-ahead log: writes are several times faster, but the data
-- is emptied after a crash or unclean shutdown and is not replicated to standbys. That is
-- a reasonable trade for a cache and nothing else. The tables must change together (a key's
-- row without its elements would be corrupt), which is why this is a function.
-- Rewrites the tables under an exclusive lock; the caller must own them.
CREATE OR REPLACE FUNCTION pgkv.set_unlogged(p_unlogged BOOLEAN DEFAULT TRUE)
RETURNS TEXT
LANGUAGE plpgsql
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_table TEXT;
BEGIN
    FOREACH v_table IN ARRAY ARRAY['store', 'hash_fields', 'list_items', 'set_members', 'zset_members'] LOOP
        EXECUTE format('ALTER TABLE pgkv.%I SET %s', v_table, CASE WHEN p_unlogged THEN 'UNLOGGED' ELSE 'LOGGED' END);
    END LOOP;
    RETURN CASE WHEN p_unlogged THEN 'unlogged' ELSE 'logged' END;
END;
$$;

-- ============================================================================
-- Strings
--
-- A string value is stored as JSONB: a JSON string, or a JSON number after INCR-style
-- commands. Functions that return the value return that JSONB; `#>> '{}'` gives its text.
-- Lengths and offsets are in bytes of the UTF-8 encoding, as in Redis.
-- ============================================================================

-- _REPLACE: slow path of SET for a key that holds a collection (or an expired one).
CREATE OR REPLACE FUNCTION pgkv._replace(p_key TEXT, p_value JSONB, p_expires_at TIMESTAMPTZ, p_keepttl BOOLEAN)
RETURNS VOID
LANGUAGE plpgsql
AS $$
DECLARE
    v_locked RECORD;
    v_type TEXT;
    v_id BIGINT;
    v_expires_at TIMESTAMPTZ;
BEGIN
    v_locked := pgkv._lock_key(p_key, TRUE);
    v_type := v_locked.o_type;
    v_id := v_locked.o_id;
    v_expires_at := v_locked.o_expires_at;
    PERFORM pgkv._drop_elems(v_id, v_type);
    PERFORM pgkv._put(p_key, p_value, 'string', CASE WHEN p_keepttl THEN v_expires_at ELSE p_expires_at END);
END;
$$;

-- _SET: write a string unconditionally. One statement unless the key holds a collection.
CREATE OR REPLACE FUNCTION pgkv._set(p_key TEXT, p_value JSONB, p_expires_at TIMESTAMPTZ, p_keepttl BOOLEAN)
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO pgkv.store AS s (key, value, type, expires_at, updated_at)
    VALUES (p_key, p_value, 'string', p_expires_at, NOW())
    ON CONFLICT (key) DO UPDATE
    SET value = EXCLUDED.value,
        type = 'string',
        expires_at = CASE
            WHEN p_keepttl AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp()) THEN s.expires_at
            ELSE EXCLUDED.expires_at
        END,
        updated_at = NOW()
    WHERE s.id IS NULL;

    IF NOT FOUND THEN
        PERFORM pgkv._replace(p_key, p_value, p_expires_at, p_keepttl);
    END IF;
END;
$$;

-- SET: Set a key to a string value, with an optional TTL (time-to-live in seconds)
CREATE OR REPLACE FUNCTION pgkv.set(p_key TEXT, p_value TEXT, p_ttl_seconds INTEGER DEFAULT NULL)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_expires_at TIMESTAMPTZ := clock_timestamp() + make_interval(secs => p_ttl_seconds);
BEGIN
    INSERT INTO pgkv.store AS s (key, value, type, expires_at, updated_at)
    VALUES (p_key, to_jsonb(p_value), 'string', v_expires_at, NOW())
    ON CONFLICT (key) DO UPDATE
    SET value = EXCLUDED.value,
        type = 'string',
        expires_at = EXCLUDED.expires_at,
        updated_at = NOW()
    WHERE s.id IS NULL;

    IF NOT FOUND THEN
        PERFORM pgkv._replace(p_key, to_jsonb(p_value), v_expires_at, FALSE);
    END IF;
    RETURN 'OK';
END;
$$;

-- GET: Retrieve the value of a key (NULL if expired or not found)
-- Returns the JSONB value; raises WRONGTYPE if the key does not hold a string
CREATE OR REPLACE FUNCTION pgkv.get(p_key TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_value JSONB;
    v_type TEXT;
BEGIN
    SELECT s.value, s.type INTO v_value, v_type
    FROM pgkv.store s
    WHERE s.key = p_key AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp());

    IF v_type <> 'string' THEN
        PERFORM pgkv._wrongtype();
    END IF;
    RETURN v_value;
END;
$$;

-- SET_OPTS: SET with Redis options (NX, XX, GET, EX, PX, EXAT, PXAT, KEEPTTL)
-- Returns "OK" when the key was set, NULL when NX or XX stopped it.
-- With p_get: the value the key held before (NULL if it did not exist), whether or not the
-- key was set; WRONGTYPE if it holds something other than a string.
-- An expired key counts as absent. Each form is atomic.
CREATE OR REPLACE FUNCTION pgkv.set_opts(
    p_key TEXT,
    p_value TEXT,
    p_nx BOOLEAN DEFAULT FALSE,
    p_xx BOOLEAN DEFAULT FALSE,
    p_get BOOLEAN DEFAULT FALSE,
    p_ex BIGINT DEFAULT NULL,
    p_px BIGINT DEFAULT NULL,
    p_exat BIGINT DEFAULT NULL,
    p_pxat BIGINT DEFAULT NULL,
    p_keepttl BOOLEAN DEFAULT FALSE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_locked RECORD;
    v_value JSONB;
    v_type TEXT;
    v_id BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new_expires_at TIMESTAMPTZ;
BEGIN
    IF p_nx AND p_xx THEN
        PERFORM pgkv._err('ERR syntax error');
    END IF;

    v_new_expires_at := pgkv._expires_at(p_ex, p_px, p_exat, p_pxat, p_keepttl);

    IF NOT (p_nx OR p_xx OR p_get) THEN
        PERFORM pgkv._set(p_key, to_jsonb(p_value), v_new_expires_at, p_keepttl);
        RETURN to_jsonb('OK'::text);
    END IF;

    IF p_nx AND NOT p_get THEN
        -- Fast path: the key is not there at all.
        INSERT INTO pgkv.store (key, value, type, expires_at, updated_at)
        VALUES (p_key, to_jsonb(p_value), 'string', v_new_expires_at, NOW())
        ON CONFLICT (key) DO NOTHING;
        IF FOUND THEN
            RETURN to_jsonb('OK'::text);
        END IF;
    END IF;

    v_locked := pgkv._lock_key(p_key, NOT p_xx);
    v_value := v_locked.o_value;
    v_type := v_locked.o_type;
    v_id := v_locked.o_id;
    v_expires_at := v_locked.o_expires_at;

    IF p_get AND v_type IS NOT NULL AND v_type <> 'string' THEN
        PERFORM pgkv._wrongtype();
    END IF;

    IF (p_nx AND v_type IS NOT NULL) OR (p_xx AND v_type IS NULL) THEN
        RETURN CASE WHEN p_get THEN v_value END;
    END IF;

    PERFORM pgkv._drop_elems(v_id, v_type);
    PERFORM pgkv._put(p_key, to_jsonb(p_value), 'string', CASE WHEN p_keepttl THEN v_expires_at ELSE v_new_expires_at END);
    RETURN CASE WHEN p_get THEN v_value ELSE to_jsonb('OK'::text) END;
END;
$$;

-- SETNX: Set key only if it does not already exist. Returns 1 if set, 0 if not.
CREATE OR REPLACE FUNCTION pgkv.setnx(p_key TEXT, p_value TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN CASE WHEN pgkv.set_opts(p_key, p_value, p_nx => TRUE) IS NULL THEN 0 ELSE 1 END;
END;
$$;

-- SETEX: Set key with an expiry in seconds
CREATE OR REPLACE FUNCTION pgkv.setex(p_key TEXT, p_seconds INTEGER, p_value TEXT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    PERFORM pgkv._set(p_key, to_jsonb(p_value), pgkv._expires_at(p_seconds, NULL, NULL, NULL, FALSE, 'setex'), FALSE);
    RETURN 'OK';
END;
$$;

-- PSETEX: Set key with an expiry in milliseconds
CREATE OR REPLACE FUNCTION pgkv.psetex(p_key TEXT, p_milliseconds BIGINT, p_value TEXT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    PERFORM pgkv._set(p_key, to_jsonb(p_value), pgkv._expires_at(NULL, p_milliseconds, NULL, NULL, FALSE, 'psetex'), FALSE);
    RETURN 'OK';
END;
$$;

-- GETSET: Set a key and return the value it held (the expiry is cleared)
CREATE OR REPLACE FUNCTION pgkv.getset(p_key TEXT, p_value TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv.set_opts(p_key, p_value, p_get => TRUE);
END;
$$;

-- GETDEL: Get the value of a key and delete it
CREATE OR REPLACE FUNCTION pgkv.getdel(p_key TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_locked RECORD;
    v_value JSONB;
    v_type TEXT;
BEGIN
    v_locked := pgkv._lock_key(p_key, FALSE);
    v_value := v_locked.o_value;
    v_type := v_locked.o_type;
    IF v_type IS NULL THEN
        RETURN NULL;
    END IF;
    IF v_type <> 'string' THEN
        PERFORM pgkv._wrongtype();
    END IF;
    DELETE FROM pgkv.store s WHERE s.key = p_key;
    RETURN v_value;
END;
$$;

-- GETEX: Get the value of a key and set its expiry (p_ex seconds, p_px milliseconds,
-- p_exat / p_pxat Unix time) or remove it (p_persist). With no option it is GET.
CREATE OR REPLACE FUNCTION pgkv.getex(
    p_key TEXT,
    p_ex BIGINT DEFAULT NULL,
    p_px BIGINT DEFAULT NULL,
    p_exat BIGINT DEFAULT NULL,
    p_pxat BIGINT DEFAULT NULL,
    p_persist BOOLEAN DEFAULT FALSE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_locked RECORD;
    v_value JSONB;
    v_type TEXT;
    v_at TIMESTAMPTZ;
BEGIN
    v_at := pgkv._expires_at(p_ex, p_px, p_exat, p_pxat, p_persist, 'getex');
    IF v_at IS NULL AND NOT p_persist THEN
        RETURN pgkv.get(p_key);
    END IF;

    v_locked := pgkv._lock_key(p_key, FALSE);
    v_value := v_locked.o_value;
    v_type := v_locked.o_type;
    IF v_type IS NULL THEN
        RETURN NULL;
    END IF;
    IF v_type <> 'string' THEN
        PERFORM pgkv._wrongtype();
    END IF;
    IF v_at <= clock_timestamp() THEN
        DELETE FROM pgkv.store s WHERE s.key = p_key;
    ELSE
        UPDATE pgkv.store s SET expires_at = v_at, updated_at = NOW() WHERE s.key = p_key;
    END IF;
    RETURN v_value;
END;
$$;

-- INCRBY: Increment the integer value of a key by the given amount
-- Stores the result as a JSONB number
CREATE OR REPLACE FUNCTION pgkv.incrby(p_key TEXT, p_increment BIGINT)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_locked RECORD;
    v_value JSONB;
    v_type TEXT;
    v_expires_at TIMESTAMPTZ;
    v_result NUMERIC;
BEGIN
    v_locked := pgkv._lock_key(p_key, TRUE);
    v_value := v_locked.o_value;
    v_type := v_locked.o_type;
    v_expires_at := v_locked.o_expires_at;

    IF v_type IS NULL THEN
        v_result := p_increment;
    ELSIF v_type <> 'string' THEN
        PERFORM pgkv._wrongtype();
    ELSE
        v_result := pgkv._int(v_value #>> '{}')::numeric + p_increment;
    END IF;

    IF v_result NOT BETWEEN -9223372036854775808 AND 9223372036854775807 THEN
        PERFORM pgkv._err('ERR increment or decrement would overflow');
    END IF;

    PERFORM pgkv._put(p_key, to_jsonb(v_result::bigint), 'string', v_expires_at);
    RETURN v_result::bigint;
END;
$$;

-- INCR: Increment the integer value of a key by 1
CREATE OR REPLACE FUNCTION pgkv.incr(p_key TEXT)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv.incrby(p_key, 1);
END;
$$;

-- DECR: Decrement the integer value of a key by 1
CREATE OR REPLACE FUNCTION pgkv.decr(p_key TEXT)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv.incrby(p_key, -1);
END;
$$;

-- DECRBY: Decrement the integer value of a key by the given amount
CREATE OR REPLACE FUNCTION pgkv.decrby(p_key TEXT, p_decrement BIGINT)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    IF p_decrement = -9223372036854775808 THEN
        PERFORM pgkv._err('ERR decrement would overflow');
    END IF;
    RETURN pgkv.incrby(p_key, -p_decrement);
END;
$$;

-- _INCRBYFLOAT: INCRBYFLOAT with the increment as text, checked in the order Redis checks:
-- the key's type, the stored value, then the increment.
CREATE OR REPLACE FUNCTION pgkv._incrbyfloat(p_key TEXT, p_increment TEXT)
RETURNS NUMERIC
LANGUAGE plpgsql
AS $$
DECLARE
    v_locked RECORD;
    v_value JSONB;
    v_type TEXT;
    v_expires_at TIMESTAMPTZ;
    v_current NUMERIC := 0;
    v_increment NUMERIC;
    v_inf INTEGER := 0;
    v_inf2 INTEGER;
    v_result NUMERIC;
BEGIN
    v_locked := pgkv._lock_key(p_key, TRUE);
    v_value := v_locked.o_value;
    v_type := v_locked.o_type;
    v_expires_at := v_locked.o_expires_at;

    IF v_type IS NOT NULL THEN
        IF v_type <> 'string' THEN
            PERFORM pgkv._wrongtype();
        END IF;
        SELECT d.o_value, d.o_infinite INTO v_current, v_inf FROM pgkv._decimal(v_value #>> '{}') d;
    END IF;
    SELECT d.o_value, d.o_infinite INTO v_increment, v_inf2 FROM pgkv._decimal(p_increment) d;
    IF v_current IS NULL OR v_increment IS NULL THEN
        PERFORM pgkv._err('ERR value is not a valid float');
    END IF;

    v_result := v_current + v_increment;
    IF v_inf <> 0 OR v_inf2 <> 0 OR abs(v_result) > 1.18973149535723176e4932 THEN
        PERFORM pgkv._err('ERR increment would produce NaN or Infinity');
    END IF;

    v_result := pgkv._num_text(pgkv._round17(v_result))::numeric;
    PERFORM pgkv._put(p_key, to_jsonb(v_result), 'string', v_expires_at);
    RETURN v_result;
END;
$$;

-- INCRBYFLOAT: Increment the numeric value of a key by a decimal amount. Exact decimal
-- arithmetic, where Redis uses long double: results can differ past the 17th digit.
CREATE OR REPLACE FUNCTION pgkv.incrbyfloat(p_key TEXT, p_increment NUMERIC)
RETURNS NUMERIC
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._incrbyfloat(p_key, p_increment::text);
END;
$$;

-- APPEND: Append a value to a key's string, creating the key if needed
-- Returns the length of the string after the append, in bytes
CREATE OR REPLACE FUNCTION pgkv.append(p_key TEXT, p_value TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_locked RECORD;
    v_value JSONB;
    v_type TEXT;
    v_expires_at TIMESTAMPTZ;
    v_text TEXT;
BEGIN
    v_locked := pgkv._lock_key(p_key, TRUE);
    v_value := v_locked.o_value;
    v_type := v_locked.o_type;
    v_expires_at := v_locked.o_expires_at;

    IF v_type IS NOT NULL AND v_type <> 'string' THEN
        PERFORM pgkv._wrongtype();
    END IF;

    v_text := COALESCE(v_value #>> '{}', '') || p_value;
    PERFORM pgkv._put(p_key, to_jsonb(v_text), 'string', v_expires_at);
    RETURN octet_length(v_text);
END;
$$;

-- STRLEN: Length of the string stored at key, in bytes (0 if the key does not exist)
CREATE OR REPLACE FUNCTION pgkv.strlen(p_key TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN COALESCE(octet_length(pgkv.get(p_key) #>> '{}'), 0);
END;
$$;

-- _SLICE: bytes p_from .. p_to (zero-based, inclusive) of a text value. A range that would
-- cut a multi-byte character in half is an error: pgkv stores text, not bytes.
CREATE OR REPLACE FUNCTION pgkv._slice(p_bytes BYTEA, p_from BIGINT, p_to BIGINT, p_command TEXT)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_len BIGINT := length(p_bytes);
BEGIN
    IF p_from > p_to THEN
        RETURN '';
    END IF;
    IF (get_byte(p_bytes, p_from::integer) & 192) = 128
        OR (p_to + 1 < v_len AND (get_byte(p_bytes, (p_to + 1)::integer) & 192) = 128) THEN
        RAISE EXCEPTION 'ERR % range splits a multi-byte UTF-8 character (pgkv stores text, not bytes)', p_command
            USING ERRCODE = 'KV000';
    END IF;
    RETURN convert_from(substring(p_bytes FROM (p_from + 1)::integer FOR (p_to - p_from + 1)::integer), 'UTF8');
END;
$$;

-- GETRANGE: Substring of the string stored at key, by byte offsets (negative from the end)
CREATE OR REPLACE FUNCTION pgkv.getrange(p_key TEXT, p_start BIGINT, p_end BIGINT)
RETURNS TEXT
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_bytes BYTEA := convert_to(COALESCE(pgkv.get(p_key) #>> '{}', ''), 'UTF8');
    v_len BIGINT := length(v_bytes);
    v_start NUMERIC := p_start;
    v_end NUMERIC := p_end;
BEGIN
    IF v_start < 0 AND v_end < 0 AND v_start > v_end THEN
        RETURN '';
    END IF;
    IF v_start < 0 THEN v_start := GREATEST(v_len + v_start, 0); END IF;
    IF v_end < 0 THEN v_end := GREATEST(v_len + v_end, 0); END IF;
    IF v_end >= v_len THEN v_end := v_len - 1; END IF;
    IF v_len = 0 OR v_start > v_end THEN
        RETURN '';
    END IF;
    RETURN pgkv._slice(v_bytes, v_start::bigint, v_end::bigint, 'GETRANGE');
END;
$$;

-- SETRANGE: Overwrite part of the string stored at key, starting at a byte offset
-- Returns the length of the string afterwards, in bytes. Writing past the end would need
-- zero-byte padding, which a text value cannot hold, and is an error.
CREATE OR REPLACE FUNCTION pgkv.setrange(p_key TEXT, p_offset BIGINT, p_value TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_locked RECORD;
    v_value JSONB;
    v_type TEXT;
    v_expires_at TIMESTAMPTZ;
    v_old BYTEA;
    v_new BYTEA := convert_to(p_value, 'UTF8');
    v_len BIGINT;
    v_text TEXT;
BEGIN
    IF p_offset < 0 THEN
        PERFORM pgkv._err('ERR offset is out of range');
    END IF;
    IF p_offset::numeric + length(v_new) > 536870912 THEN
        PERFORM pgkv._err('ERR string exceeds maximum allowed size (proto-max-bulk-len)');
    END IF;

    v_locked := pgkv._lock_key(p_key, length(v_new) > 0);
    v_value := v_locked.o_value;
    v_type := v_locked.o_type;
    v_expires_at := v_locked.o_expires_at;

    IF v_type IS NOT NULL AND v_type <> 'string' THEN
        PERFORM pgkv._wrongtype();
    END IF;

    v_old := convert_to(COALESCE(v_value #>> '{}', ''), 'UTF8');
    v_len := length(v_old);
    IF length(v_new) = 0 THEN
        RETURN v_len;
    END IF;
    IF p_offset > v_len THEN
        PERFORM pgkv._err('ERR SETRANGE past the end of the string needs zero-byte padding, which pgkv text values cannot hold');
    END IF;

    v_text := pgkv._slice(v_old, 0, p_offset - 1, 'SETRANGE') || p_value
        || CASE WHEN p_offset + length(v_new) < v_len
                THEN pgkv._slice(v_old, p_offset + length(v_new), v_len - 1, 'SETRANGE') ELSE '' END;
    PERFORM pgkv._put(p_key, to_jsonb(v_text), 'string', v_expires_at);
    RETURN octet_length(v_text);
END;
$$;

-- MGET: Get the values of all specified keys, in order
-- value is NULL for a key that does not exist or does not hold a string
CREATE OR REPLACE FUNCTION pgkv.mget(VARIADIC p_keys TEXT[])
RETURNS TABLE(key TEXT, value JSONB)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
    SELECT k.key, s.value
    FROM unnest(p_keys) WITH ORDINALITY AS k(key, ord)
    LEFT JOIN pgkv.store s
        ON s.key = k.key AND s.type = 'string'
        AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp())
    ORDER BY k.ord
$$;

-- MSET: Set multiple keys to multiple values, atomically
CREATE OR REPLACE FUNCTION pgkv.mset(VARIADIC p_pairs TEXT[])
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_count INTEGER;
    v_written INTEGER;
    v_key TEXT;
    v_value TEXT;
BEGIN
    IF p_pairs IS NULL OR array_length(p_pairs, 1) % 2 != 0 THEN
        PERFORM pgkv._err('ERR wrong number of arguments for ''mset'' command');
    END IF;

    -- A key given twice takes its last value. Rows are written in key order, so two
    -- multi-key calls cannot deadlock each other.
    WITH input AS (
        SELECT DISTINCT ON (p_pairs[i]) p_pairs[i] AS k, p_pairs[i + 1] AS v
        FROM generate_series(1, array_length(p_pairs, 1), 2) AS i
        ORDER BY p_pairs[i], i DESC
    ), written AS (
        INSERT INTO pgkv.store AS s (key, value, type, expires_at, updated_at)
        SELECT d.k, to_jsonb(d.v), 'string', NULL, NOW()
        FROM input d
        ORDER BY d.k COLLATE "C"
        ON CONFLICT (key) DO UPDATE
        SET value = EXCLUDED.value, type = 'string', expires_at = NULL, updated_at = NOW()
        WHERE s.id IS NULL
        RETURNING 1
    )
    SELECT (SELECT COUNT(*) FROM input), (SELECT COUNT(*) FROM written) INTO v_count, v_written;

    IF v_written < v_count THEN
        -- Some of the keys hold collections: replace those one at a time.
        FOR v_key, v_value IN
            SELECT DISTINCT ON (p_pairs[i]) p_pairs[i], p_pairs[i + 1]
            FROM generate_series(1, array_length(p_pairs, 1), 2) AS i
            ORDER BY p_pairs[i], i DESC
        LOOP
            IF EXISTS (SELECT 1 FROM pgkv.store s WHERE s.key = v_key AND s.id IS NOT NULL) THEN
                PERFORM pgkv._replace(v_key, to_jsonb(v_value), NULL, FALSE);
            END IF;
        END LOOP;
    END IF;
    RETURN 'OK';
END;
$$;

-- MSETNX: Set multiple keys only if none of them exist. Returns 1 if set, 0 if not.
CREATE OR REPLACE FUNCTION pgkv.msetnx(VARIADIC p_pairs TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_keys TEXT[];
BEGIN
    IF p_pairs IS NULL OR array_length(p_pairs, 1) % 2 != 0 THEN
        PERFORM pgkv._err('ERR wrong number of arguments for ''msetnx'' command');
    END IF;

    SELECT array_agg(p_pairs[i]) INTO v_keys FROM generate_series(1, array_length(p_pairs, 1), 2) AS i;
    PERFORM pgkv._lock_keys('{}', v_keys);

    IF EXISTS (SELECT 1 FROM pgkv.store s WHERE s.key = ANY(v_keys) AND s.expires_at IS DISTINCT FROM '-infinity') THEN
        DELETE FROM pgkv.store s WHERE s.key = ANY(v_keys) AND s.expires_at = '-infinity';
        RETURN 0;
    END IF;

    UPDATE pgkv.store s
    SET value = to_jsonb(d.v), type = 'string', expires_at = NULL, updated_at = NOW()
    FROM (
        SELECT DISTINCT ON (p_pairs[i]) p_pairs[i] AS k, p_pairs[i + 1] AS v
        FROM generate_series(1, array_length(p_pairs, 1), 2) AS i
        ORDER BY p_pairs[i], i DESC
    ) d
    WHERE s.key = d.k;
    RETURN 1;
END;
$$;

-- CAS: Compare-and-set. Set p_key to p_value only if it currently holds p_expected,
-- compared as text (what `pgkv.get(key) #>> '{}'` returns). A NULL p_expected means
-- "only if the key does not exist" (an expired key does not exist), which is SET NX.
-- Returns 1 if it wrote, 0 if the key held something else (or, for NULL, existed).
-- Expiry options are those of set_opts; without one the new value has no expiry.
-- Of several sessions holding the same expected value exactly one wins.
-- The Redis equivalent is `SET key value IFEQ expected` (Redis 8.4); earlier Redis needs a script.
CREATE OR REPLACE FUNCTION pgkv.cas(
    p_key TEXT,
    p_expected TEXT,
    p_value TEXT,
    p_ex BIGINT DEFAULT NULL,
    p_px BIGINT DEFAULT NULL,
    p_exat BIGINT DEFAULT NULL,
    p_pxat BIGINT DEFAULT NULL,
    p_keepttl BOOLEAN DEFAULT FALSE
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_new_expires_at TIMESTAMPTZ;
BEGIN
    v_new_expires_at := pgkv._expires_at(p_ex, p_px, p_exat, p_pxat, p_keepttl);

    IF p_expected IS NULL THEN
        RETURN CASE WHEN pgkv.set_opts(p_key, p_value, p_nx => TRUE, p_ex => p_ex, p_px => p_px,
                                       p_exat => p_exat, p_pxat => p_pxat) IS NULL THEN 0 ELSE 1 END;
    END IF;

    UPDATE pgkv.store s
    SET value = to_jsonb(p_value),
        expires_at = CASE WHEN p_keepttl THEN s.expires_at ELSE v_new_expires_at END,
        updated_at = NOW()
    WHERE s.key = p_key
      AND s.type = 'string'
      AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp())
      AND s.value #>> '{}' = p_expected;

    IF FOUND THEN
        RETURN 1;
    END IF;

    -- Not written. Say so, unless the key holds another type, which is an error as for get.
    PERFORM pgkv._require_string(p_key);
    RETURN 0;
END;
$$;

-- CAD: Compare-and-delete. Delete p_key only if it currently holds p_expected (compared as
-- text, as for cas). Returns 1 if it deleted, 0 otherwise. One statement.
-- The Redis equivalent is `DELEX key IFEQ expected` (Redis 8.4).
CREATE OR REPLACE FUNCTION pgkv.cad(p_key TEXT, p_expected TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    DELETE FROM pgkv.store s
    WHERE s.key = p_key
      AND s.type = 'string'
      AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp())
      AND s.value #>> '{}' = p_expected;

    IF FOUND THEN
        RETURN 1;
    END IF;

    PERFORM pgkv._require_string(p_key);
    RETURN 0;
END;
$$;

-- ============================================================================
-- Hashes: one row per field in pgkv.hash_fields
-- ============================================================================

-- HSET: Set field(s) in a hash. Returns the number of fields added (not updated).
CREATE OR REPLACE FUNCTION pgkv.hset(p_key TEXT, VARIADIC p_pairs TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_added INTEGER;
BEGIN
    IF p_pairs IS NULL OR array_length(p_pairs, 1) % 2 != 0 THEN
        PERFORM pgkv._err('ERR wrong number of arguments for ''hset'' command');
    END IF;

    v_opened := pgkv._open(p_key, 'hash', TRUE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;

    IF array_length(p_pairs, 1) = 2 THEN
        INSERT INTO pgkv.hash_fields AS f (id, field, value)
        VALUES (v_id, p_pairs[1], to_jsonb(p_pairs[2]))
        ON CONFLICT (id, field) DO UPDATE SET value = EXCLUDED.value
        RETURNING (f.xmax = 0)::integer INTO v_added;
    ELSE
        WITH written AS (
            INSERT INTO pgkv.hash_fields AS f (id, field, value)
            SELECT v_id, d.k, to_jsonb(d.v)
            FROM (
                SELECT DISTINCT ON (p_pairs[i]) p_pairs[i] AS k, p_pairs[i + 1] AS v
                FROM generate_series(1, array_length(p_pairs, 1), 2) AS i
                ORDER BY p_pairs[i], i DESC
            ) d
            ON CONFLICT (id, field) DO UPDATE SET value = EXCLUDED.value
            RETURNING (f.xmax = 0) AS inserted
        )
        SELECT (COUNT(*) FILTER (WHERE inserted))::integer INTO v_added FROM written;
    END IF;

    IF v_added > 0 THEN
        PERFORM pgkv._save(p_key, 'hash', v_id, v_card + v_added, NULL, v_expires_at);
    END IF;
    RETURN v_added;
END;
$$;

-- HSETNX: Set a field only if it does not exist. Returns 1 if set, 0 if not.
CREATE OR REPLACE FUNCTION pgkv.hsetnx(p_key TEXT, p_field TEXT, p_value TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
BEGIN
    v_opened := pgkv._open(p_key, 'hash', TRUE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;

    INSERT INTO pgkv.hash_fields (id, field, value) VALUES (v_id, p_field, to_jsonb(p_value))
    ON CONFLICT (id, field) DO NOTHING;
    IF NOT FOUND THEN
        RETURN 0;
    END IF;
    PERFORM pgkv._save(p_key, 'hash', v_id, v_card + 1, NULL, v_expires_at);
    RETURN 1;
END;
$$;

-- HGET: Get the value of a hash field
CREATE OR REPLACE FUNCTION pgkv.hget(p_key TEXT, p_field TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_type TEXT;
    v_value JSONB;
BEGIN
    SELECT s.type, f.value INTO v_type, v_value
    FROM pgkv.store s
    LEFT JOIN pgkv.hash_fields f ON f.id = s.id AND f.field = p_field
    WHERE s.key = p_key AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp());

    IF v_type <> 'hash' THEN
        PERFORM pgkv._wrongtype();
    END IF;
    RETURN v_value;
END;
$$;

-- HMGET: Get the values of several hash fields, in order (NULL for a missing field)
CREATE OR REPLACE FUNCTION pgkv.hmget(p_key TEXT, VARIADIC p_fields TEXT[])
RETURNS TABLE(field TEXT, value JSONB)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
BEGIN
    v_peeked := pgkv._peek(p_key, 'hash');
    v_id := v_peeked.o_id;
    RETURN QUERY
    SELECT k.f, h.value
    FROM unnest(p_fields) WITH ORDINALITY AS k(f, ord)
    LEFT JOIN pgkv.hash_fields h ON h.id = v_id AND h.field = k.f
    ORDER BY k.ord;
END;
$$;

-- HGETALL: Get all fields and values of a hash, in byte order of the field
CREATE OR REPLACE FUNCTION pgkv.hgetall(p_key TEXT)
RETURNS TABLE(field TEXT, value JSONB)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
BEGIN
    v_peeked := pgkv._peek(p_key, 'hash');
    v_id := v_peeked.o_id;
    RETURN QUERY SELECT h.field::text, h.value FROM pgkv.hash_fields h WHERE h.id = v_id ORDER BY h.field;
END;
$$;

-- HDEL: Delete field(s) from a hash. Returns the number of fields removed.
CREATE OR REPLACE FUNCTION pgkv.hdel(p_key TEXT, VARIADIC p_fields TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_removed INTEGER;
BEGIN
    v_opened := pgkv._open(p_key, 'hash', FALSE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;
    IF v_new THEN
        RETURN 0;
    END IF;

    DELETE FROM pgkv.hash_fields f WHERE f.id = v_id AND f.field = ANY(p_fields);
    GET DIAGNOSTICS v_removed = ROW_COUNT;
    IF v_removed > 0 THEN
        PERFORM pgkv._save(p_key, 'hash', v_id, v_card - v_removed, NULL, v_expires_at);
    END IF;
    RETURN v_removed;
END;
$$;

-- HEXISTS: 1 if the field exists in the hash, 0 if not
CREATE OR REPLACE FUNCTION pgkv.hexists(p_key TEXT, p_field TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN CASE WHEN pgkv.hget(p_key, p_field) IS NULL THEN 0 ELSE 1 END;
END;
$$;

-- HLEN: Number of fields in a hash
CREATE OR REPLACE FUNCTION pgkv.hlen(p_key TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN COALESCE((SELECT p.o_card FROM pgkv._peek(p_key, 'hash') p), 0);
END;
$$;

-- HSTRLEN: Length in bytes of the value of a hash field (0 if missing)
CREATE OR REPLACE FUNCTION pgkv.hstrlen(p_key TEXT, p_field TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN COALESCE(octet_length(pgkv.hget(p_key, p_field) #>> '{}'), 0);
END;
$$;

-- HKEYS: All field names of a hash, in byte order
CREATE OR REPLACE FUNCTION pgkv.hkeys(p_key TEXT)
RETURNS SETOF TEXT
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT h.field FROM pgkv.hgetall(p_key) h;
END;
$$;

-- HVALS: All values of a hash, in byte order of their fields
CREATE OR REPLACE FUNCTION pgkv.hvals(p_key TEXT)
RETURNS SETOF JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT h.value FROM pgkv.hgetall(p_key) h;
END;
$$;

-- HINCRBY: Increment the integer value of a hash field
CREATE OR REPLACE FUNCTION pgkv.hincrby(p_key TEXT, p_field TEXT, p_increment BIGINT)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_current JSONB;
    v_result NUMERIC;
BEGIN
    v_opened := pgkv._open(p_key, 'hash', TRUE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;

    SELECT f.value INTO v_current FROM pgkv.hash_fields f WHERE f.id = v_id AND f.field = p_field;
    IF v_current IS NULL THEN
        v_result := p_increment;
    ELSE
        v_result := pgkv._int(v_current #>> '{}', 'ERR hash value is not an integer')::numeric + p_increment;
    END IF;
    IF v_result NOT BETWEEN -9223372036854775808 AND 9223372036854775807 THEN
        PERFORM pgkv._err('ERR increment or decrement would overflow');
    END IF;

    IF v_current IS NULL THEN
        INSERT INTO pgkv.hash_fields (id, field, value) VALUES (v_id, p_field, to_jsonb(v_result::bigint));
        PERFORM pgkv._save(p_key, 'hash', v_id, v_card + 1, NULL, v_expires_at);
    ELSE
        UPDATE pgkv.hash_fields f SET value = to_jsonb(v_result::bigint) WHERE f.id = v_id AND f.field = p_field;
    END IF;
    RETURN v_result::bigint;
END;
$$;

-- _HINCRBYFLOAT: HINCRBYFLOAT with the increment as text, checked in the order Redis checks.
CREATE OR REPLACE FUNCTION pgkv._hincrbyfloat(p_key TEXT, p_field TEXT, p_increment TEXT)
RETURNS NUMERIC
LANGUAGE plpgsql
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_stored JSONB;
    v_current NUMERIC := 0;
    v_increment NUMERIC;
    v_inf INTEGER := 0;
    v_inf2 INTEGER;
    v_result NUMERIC;
BEGIN
    SELECT d.o_value, d.o_infinite INTO v_increment, v_inf2 FROM pgkv._decimal(p_increment) d;
    IF v_increment IS NULL THEN
        PERFORM pgkv._err('ERR value is not a valid float');
    ELSIF v_inf2 <> 0 THEN
        PERFORM pgkv._err('ERR value is NaN or Infinity');
    END IF;

    v_opened := pgkv._open(p_key, 'hash', TRUE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;

    SELECT f.value INTO v_stored FROM pgkv.hash_fields f WHERE f.id = v_id AND f.field = p_field;
    IF v_stored IS NOT NULL THEN
        SELECT d.o_value, d.o_infinite INTO v_current, v_inf FROM pgkv._decimal(v_stored #>> '{}') d;
        IF v_current IS NULL THEN
            PERFORM pgkv._err('ERR hash value is not a float');
        END IF;
    END IF;

    v_result := v_current + v_increment;
    IF v_inf <> 0 OR abs(v_result) > 1.18973149535723176e4932 THEN
        PERFORM pgkv._err('ERR increment would produce NaN or Infinity');
    END IF;
    v_result := pgkv._num_text(pgkv._round17(v_result))::numeric;

    IF v_stored IS NULL THEN
        INSERT INTO pgkv.hash_fields (id, field, value) VALUES (v_id, p_field, to_jsonb(v_result));
        PERFORM pgkv._save(p_key, 'hash', v_id, v_card + 1, NULL, v_expires_at);
    ELSE
        UPDATE pgkv.hash_fields f SET value = to_jsonb(v_result) WHERE f.id = v_id AND f.field = p_field;
    END IF;
    RETURN v_result;
END;
$$;

-- HINCRBYFLOAT: Increment the numeric value of a hash field by a decimal amount
CREATE OR REPLACE FUNCTION pgkv.hincrbyfloat(p_key TEXT, p_field TEXT, p_increment NUMERIC)
RETURNS NUMERIC
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._hincrbyfloat(p_key, p_field, p_increment::text);
END;
$$;

-- HRANDFIELD: Random fields of a hash. A positive p_count returns up to that many distinct
-- fields; a negative one returns exactly that many, possibly repeating.
CREATE OR REPLACE FUNCTION pgkv.hrandfield(p_key TEXT, p_count BIGINT DEFAULT 1)
RETURNS TABLE(field TEXT, value JSONB)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
    v_card BIGINT;
BEGIN
    v_peeked := pgkv._peek(p_key, 'hash');
    v_id := v_peeked.o_id;
    v_card := v_peeked.o_card;
    IF v_id IS NULL OR p_count = 0 THEN
        RETURN;
    END IF;
    IF p_count > 0 THEN
        RETURN QUERY SELECT h.field::text, h.value FROM pgkv.hash_fields h WHERE h.id = v_id ORDER BY random() LIMIT p_count;
    ELSE
        RETURN QUERY
        SELECT r.field::text, r.value
        FROM generate_series(1, -p_count) AS g
        CROSS JOIN LATERAL (
            SELECT h.field, h.value FROM pgkv.hash_fields h
            WHERE h.id = v_id ORDER BY h.field OFFSET floor(random() * v_card + g * 0)::bigint LIMIT 1
        ) r;
    END IF;
END;
$$;

-- HSCAN: Iterate the fields of a hash matching a pattern, p_count at a time, in byte order.
-- Each row carries the cursor for the next call; 0 means the sweep is complete.
CREATE OR REPLACE FUNCTION pgkv.hscan(p_key TEXT, p_cursor BIGINT DEFAULT 0, p_pattern TEXT DEFAULT '*', p_count INTEGER DEFAULT 10)
RETURNS TABLE(cursor BIGINT, field TEXT, value JSONB)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
    v_re TEXT := CASE WHEN COALESCE(p_pattern, '*') = '*' THEN NULL ELSE pgkv._glob_re(p_pattern) END;
BEGIN
    v_peeked := pgkv._peek(p_key, 'hash');
    v_id := v_peeked.o_id;
    RETURN QUERY
    WITH page AS (
        SELECT h.field, h.value, row_number() OVER (ORDER BY h.field) AS rn
        FROM pgkv.hash_fields h
        WHERE h.id = v_id AND (v_re IS NULL OR h.field ~ v_re)
        ORDER BY h.field
        OFFSET p_cursor LIMIT p_count + 1
    )
    SELECT CASE WHEN (SELECT COUNT(*) FROM page) > p_count THEN p_cursor + p_count ELSE 0 END,
           page.field::text, page.value
    FROM page WHERE page.rn <= p_cursor + p_count ORDER BY page.field;
END;
$$;

-- ============================================================================
-- Lists: one row per element in pgkv.list_items, at positions head .. head + card - 1.
-- Pushing and popping at either end touch only the rows they add or remove.
-- ============================================================================

-- _LIST_REPACK: rewrite the elements at positions p_from .. p_to so that they sit at
-- consecutive positions starting at p_start, keeping their order.
CREATE OR REPLACE FUNCTION pgkv._list_repack(p_id BIGINT, p_from BIGINT, p_to BIGINT, p_start BIGINT)
RETURNS VOID
LANGUAGE plpgsql
AS $$
DECLARE
    v_values TEXT[];
BEGIN
    WITH moved AS (
        DELETE FROM pgkv.list_items i WHERE i.id = p_id AND i.pos BETWEEN p_from AND p_to RETURNING i.pos, i.value
    )
    SELECT array_agg(m.value ORDER BY m.pos) INTO v_values FROM moved m;

    IF v_values IS NOT NULL THEN
        INSERT INTO pgkv.list_items (id, pos, value)
        SELECT p_id, p_start + u.ord - 1, u.v FROM unnest(v_values) WITH ORDINALITY AS u(v, ord);
    END IF;
END;
$$;

-- _PUSH: add values to the head (p_left) or tail of a list. Each value is pushed in turn,
-- so the last one given ends up outermost. p_must_exist is LPUSHX / RPUSHX.
CREATE OR REPLACE FUNCTION pgkv._push(p_key TEXT, p_values TEXT[], p_left BOOLEAN, p_must_exist BOOLEAN)
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_head BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_n INTEGER := COALESCE(array_length(p_values, 1), 0);
BEGIN
    v_opened := pgkv._open(p_key, 'list', NOT p_must_exist);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_head := v_opened.o_head;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;
    IF v_new AND p_must_exist THEN
        RETURN 0;
    END IF;

    IF v_n = 1 THEN
        INSERT INTO pgkv.list_items (id, pos, value)
        VALUES (v_id, CASE WHEN p_left THEN v_head - 1 ELSE v_head + v_card END, p_values[1]);
    ELSIF p_left THEN
        INSERT INTO pgkv.list_items (id, pos, value)
        SELECT v_id, v_head - u.ord, u.v FROM unnest(p_values) WITH ORDINALITY AS u(v, ord);
    ELSE
        INSERT INTO pgkv.list_items (id, pos, value)
        SELECT v_id, v_head + v_card + u.ord - 1, u.v FROM unnest(p_values) WITH ORDINALITY AS u(v, ord);
    END IF;

    IF p_left THEN
        v_head := v_head - v_n;
    END IF;
    PERFORM pgkv._save(p_key, 'list', v_id, v_card + v_n, v_head, v_expires_at);
    RETURN (v_card + v_n)::integer;
END;
$$;

-- LPUSH: Insert value(s) at the head of a list. Returns the length of the list afterwards.
CREATE OR REPLACE FUNCTION pgkv.lpush(p_key TEXT, VARIADIC p_values TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._push(p_key, p_values, TRUE, FALSE);
END;
$$;

-- RPUSH: Insert value(s) at the tail of a list. Returns the length of the list afterwards.
CREATE OR REPLACE FUNCTION pgkv.rpush(p_key TEXT, VARIADIC p_values TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._push(p_key, p_values, FALSE, FALSE);
END;
$$;

-- LPUSHX: LPUSH only if the list exists
CREATE OR REPLACE FUNCTION pgkv.lpushx(p_key TEXT, VARIADIC p_values TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._push(p_key, p_values, TRUE, TRUE);
END;
$$;

-- RPUSHX: RPUSH only if the list exists
CREATE OR REPLACE FUNCTION pgkv.rpushx(p_key TEXT, VARIADIC p_values TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._push(p_key, p_values, FALSE, TRUE);
END;
$$;

-- _POP: remove up to p_count elements from the head (p_left) or tail of a list and return
-- them in the order popped. NULL if the key does not exist.
CREATE OR REPLACE FUNCTION pgkv._pop(p_key TEXT, p_count BIGINT, p_left BOOLEAN)
RETURNS TEXT[]
LANGUAGE plpgsql
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_head BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_n BIGINT;
    v_values TEXT[];
BEGIN
    IF p_count < 0 THEN
        PERFORM pgkv._err('ERR value is out of range, must be positive');
    END IF;

    v_opened := pgkv._open(p_key, 'list', FALSE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_head := v_opened.o_head;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;
    IF v_new THEN
        RETURN NULL;
    END IF;

    v_n := LEAST(p_count, v_card);
    IF v_n = 0 THEN
        RETURN '{}';
    END IF;

    IF v_n = 1 THEN
        DELETE FROM pgkv.list_items i
        WHERE i.id = v_id AND i.pos = CASE WHEN p_left THEN v_head ELSE v_head + v_card - 1 END
        RETURNING ARRAY[i.value] INTO v_values;
        IF p_left THEN
            v_head := v_head + 1;
        END IF;
    ELSIF p_left THEN
        WITH popped AS (
            DELETE FROM pgkv.list_items i WHERE i.id = v_id AND i.pos < v_head + v_n RETURNING i.pos, i.value
        )
        SELECT array_agg(p.value ORDER BY p.pos) INTO v_values FROM popped p;
        v_head := v_head + v_n;
    ELSE
        WITH popped AS (
            DELETE FROM pgkv.list_items i WHERE i.id = v_id AND i.pos >= v_head + v_card - v_n RETURNING i.pos, i.value
        )
        SELECT array_agg(p.value ORDER BY p.pos DESC) INTO v_values FROM popped p;
    END IF;

    PERFORM pgkv._save(p_key, 'list', v_id, v_card - v_n, v_head, v_expires_at);
    RETURN v_values;
END;
$$;

-- LPOP: Remove and return the first element(s) of a list
CREATE OR REPLACE FUNCTION pgkv.lpop(p_key TEXT, p_count BIGINT DEFAULT 1)
RETURNS SETOF JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT to_jsonb(u.v) FROM unnest(pgkv._pop(p_key, p_count, TRUE)) WITH ORDINALITY AS u(v, ord) ORDER BY u.ord;
END;
$$;

-- RPOP: Remove and return the last element(s) of a list
CREATE OR REPLACE FUNCTION pgkv.rpop(p_key TEXT, p_count BIGINT DEFAULT 1)
RETURNS SETOF JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT to_jsonb(u.v) FROM unnest(pgkv._pop(p_key, p_count, FALSE)) WITH ORDINALITY AS u(v, ord) ORDER BY u.ord;
END;
$$;

-- LLEN: Length of a list
CREATE OR REPLACE FUNCTION pgkv.llen(p_key TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN COALESCE((SELECT p.o_card FROM pgkv._peek(p_key, 'list') p), 0);
END;
$$;

-- _LRANGE: the elements of a list between two indexes, as an array.
CREATE OR REPLACE FUNCTION pgkv._lrange(p_key TEXT, p_start BIGINT, p_stop BIGINT)
RETURNS TEXT[]
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_head BIGINT;
    v_off BIGINT;
    v_len BIGINT;
BEGIN
    v_peeked := pgkv._peek(p_key, 'list');
    v_id := v_peeked.o_id;
    v_card := v_peeked.o_card;
    v_head := v_peeked.o_head;
    IF v_id IS NULL THEN
        RETURN '{}';
    END IF;
    SELECT r.o_off, r.o_len INTO v_off, v_len FROM pgkv._range(p_start, p_stop, v_card) r;
    IF v_len = 0 THEN
        RETURN '{}';
    END IF;
    RETURN ARRAY(
        SELECT i.value FROM pgkv.list_items i
        WHERE i.id = v_id AND i.pos BETWEEN v_head + v_off AND v_head + v_off + v_len - 1
        ORDER BY i.pos
    );
END;
$$;

-- LRANGE: Get a range of elements from a list (indexes are zero-based, negative from the end)
CREATE OR REPLACE FUNCTION pgkv.lrange(p_key TEXT, p_start BIGINT, p_stop BIGINT)
RETURNS SETOF JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT to_jsonb(u.v) FROM unnest(pgkv._lrange(p_key, p_start, p_stop)) WITH ORDINALITY AS u(v, ord) ORDER BY u.ord;
END;
$$;

-- LINDEX: Get an element of a list by its index
CREATE OR REPLACE FUNCTION pgkv.lindex(p_key TEXT, p_index BIGINT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_head BIGINT;
BEGIN
    v_peeked := pgkv._peek(p_key, 'list');
    v_id := v_peeked.o_id;
    v_card := v_peeked.o_card;
    v_head := v_peeked.o_head;
    IF v_id IS NULL OR p_index >= v_card OR p_index < -v_card THEN
        RETURN NULL;
    END IF;
    RETURN (
        SELECT to_jsonb(i.value) FROM pgkv.list_items i
        WHERE i.id = v_id AND i.pos = v_head + CASE WHEN p_index < 0 THEN v_card + p_index ELSE p_index END
    );
END;
$$;

-- LSET: Set the value of an element of a list by its index
CREATE OR REPLACE FUNCTION pgkv.lset(p_key TEXT, p_index BIGINT, p_value TEXT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_head BIGINT;
    v_new BOOLEAN;
BEGIN
    v_opened := pgkv._open(p_key, 'list', FALSE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_head := v_opened.o_head;
    v_new := v_opened.o_new;
    IF v_new THEN
        PERFORM pgkv._err('ERR no such key');
    END IF;
    IF p_index >= v_card OR p_index < -v_card THEN
        PERFORM pgkv._err('ERR index out of range');
    END IF;

    UPDATE pgkv.list_items i SET value = p_value
    WHERE i.id = v_id AND i.pos = v_head + CASE WHEN p_index < 0 THEN v_card + p_index ELSE p_index END;
    RETURN 'OK';
END;
$$;

-- LTRIM: Trim a list to the given range of indexes
CREATE OR REPLACE FUNCTION pgkv.ltrim(p_key TEXT, p_start BIGINT, p_stop BIGINT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_head BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_off BIGINT;
    v_len BIGINT;
BEGIN
    v_opened := pgkv._open(p_key, 'list', FALSE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_head := v_opened.o_head;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;
    IF v_new THEN
        RETURN 'OK';
    END IF;

    SELECT r.o_off, r.o_len INTO v_off, v_len FROM pgkv._range(p_start, p_stop, v_card) r;
    IF v_len = v_card THEN
        RETURN 'OK';
    END IF;
    IF v_len = 0 THEN
        DELETE FROM pgkv.list_items i WHERE i.id = v_id;
    ELSE
        DELETE FROM pgkv.list_items i
        WHERE i.id = v_id AND (i.pos < v_head + v_off OR i.pos >= v_head + v_off + v_len);
    END IF;
    PERFORM pgkv._save(p_key, 'list', v_id, v_len, v_head + v_off, v_expires_at);
    RETURN 'OK';
END;
$$;

-- LREM: Remove elements equal to p_value: the first p_count from the head if p_count > 0,
-- the last -p_count from the tail if p_count < 0, all of them if p_count = 0.
-- Returns the number removed. Rewrites the shorter side of the list around the removals.
CREATE OR REPLACE FUNCTION pgkv.lrem(p_key TEXT, p_count BIGINT, p_value TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_head BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_positions BIGINT[];
    v_n INTEGER;
    v_first BIGINT;
    v_last BIGINT;
    v_tail BIGINT;
BEGIN
    v_opened := pgkv._open(p_key, 'list', FALSE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_head := v_opened.o_head;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;
    IF v_new THEN
        RETURN 0;
    END IF;

    IF p_count >= 0 THEN
        v_positions := ARRAY(
            SELECT i.pos FROM pgkv.list_items i WHERE i.id = v_id AND i.value = p_value
            ORDER BY i.pos LIMIT NULLIF(p_count, 0));
    ELSE
        v_positions := ARRAY(
            SELECT i.pos FROM pgkv.list_items i WHERE i.id = v_id AND i.value = p_value
            ORDER BY i.pos DESC LIMIT -p_count);
    END IF;
    v_n := cardinality(v_positions);
    IF v_n = 0 THEN
        RETURN 0;
    END IF;

    DELETE FROM pgkv.list_items i WHERE i.id = v_id AND i.pos = ANY(v_positions);
    SELECT min(p), max(p) INTO v_first, v_last FROM unnest(v_positions) AS p;
    v_tail := v_head + v_card - 1;

    IF v_n < v_card THEN
        IF v_tail - v_first <= v_last - v_head THEN
            -- Close the gaps by pulling the tail side down.
            PERFORM pgkv._list_repack(v_id, v_first, v_tail, v_first);
        ELSE
            -- Close the gaps by pushing the head side up.
            PERFORM pgkv._list_repack(v_id, v_head, v_last, v_head + v_n);
            v_head := v_head + v_n;
        END IF;
    END IF;
    PERFORM pgkv._save(p_key, 'list', v_id, v_card - v_n, v_head, v_expires_at);
    RETURN v_n;
END;
$$;

-- LINSERT: Insert a value before or after the first element equal to p_pivot.
-- Returns the length of the list afterwards, -1 if the pivot was not found, 0 if the key
-- does not exist.
CREATE OR REPLACE FUNCTION pgkv.linsert(p_key TEXT, p_before_after TEXT, p_pivot TEXT, p_value TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_head BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_where TEXT := upper(p_before_after);
    v_pos BIGINT;
BEGIN
    IF v_where NOT IN ('BEFORE', 'AFTER') THEN
        PERFORM pgkv._err('ERR syntax error');
    END IF;

    v_opened := pgkv._open(p_key, 'list', FALSE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_head := v_opened.o_head;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;
    IF v_new THEN
        RETURN 0;
    END IF;

    SELECT i.pos INTO v_pos FROM pgkv.list_items i WHERE i.id = v_id AND i.value = p_pivot
    ORDER BY i.pos LIMIT 1;
    IF v_pos IS NULL THEN
        RETURN -1;
    END IF;

    -- v_pos becomes the position the new element takes if the tail side moves up by one.
    IF v_where = 'AFTER' THEN
        v_pos := v_pos + 1;
    END IF;
    IF v_head + v_card - v_pos <= v_pos - v_head THEN
        PERFORM pgkv._list_repack(v_id, v_pos, v_head + v_card - 1, v_pos + 1);
    ELSE
        PERFORM pgkv._list_repack(v_id, v_head, v_pos - 1, v_head - 1);
        v_head := v_head - 1;
        v_pos := v_pos - 1;
    END IF;
    INSERT INTO pgkv.list_items (id, pos, value) VALUES (v_id, v_pos, p_value);
    PERFORM pgkv._save(p_key, 'list', v_id, v_card + 1, v_head, v_expires_at);
    RETURN (v_card + 1)::integer;
END;
$$;

-- _LPOS: indexes of the elements equal to p_value. p_rank picks the first match to return
-- (2 = the second; negative searches from the tail), p_count how many (0 = all), p_maxlen
-- how many elements to compare (0 = all).
CREATE OR REPLACE FUNCTION pgkv._lpos(p_key TEXT, p_value TEXT, p_rank BIGINT, p_count BIGINT, p_maxlen BIGINT)
RETURNS BIGINT[]
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_head BIGINT;
BEGIN
    IF p_rank = 0 THEN
        PERFORM pgkv._err('ERR RANK can''t be zero: use 1 to start from the first match, 2 from the second ... or use negative to start from the end of the list');
    END IF;
    IF p_count < 0 THEN
        PERFORM pgkv._err('ERR COUNT can''t be negative');
    END IF;
    IF p_maxlen < 0 THEN
        PERFORM pgkv._err('ERR MAXLEN can''t be negative');
    END IF;

    v_peeked := pgkv._peek(p_key, 'list');
    v_id := v_peeked.o_id;
    v_card := v_peeked.o_card;
    v_head := v_peeked.o_head;
    IF v_id IS NULL THEN
        RETURN NULL;
    END IF;

    IF p_rank > 0 THEN
        RETURN ARRAY(
            SELECT i.pos - v_head FROM pgkv.list_items i
            WHERE i.id = v_id AND i.value = p_value
              AND (p_maxlen = 0 OR i.pos < v_head + p_maxlen)
            ORDER BY i.pos OFFSET p_rank - 1 LIMIT NULLIF(p_count, 0));
    END IF;
    RETURN ARRAY(
        SELECT i.pos - v_head FROM pgkv.list_items i
        WHERE i.id = v_id AND i.value = p_value
          AND (p_maxlen = 0 OR i.pos >= v_head + v_card - p_maxlen)
        ORDER BY i.pos DESC OFFSET -p_rank - 1 LIMIT NULLIF(p_count, 0));
END;
$$;

-- LPOS: Index of the first element equal to p_value (NULL if there is none).
-- p_rank 2 gives the second match, -1 the last.
CREATE OR REPLACE FUNCTION pgkv.lpos(p_key TEXT, p_value TEXT, p_rank BIGINT DEFAULT 1)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN (pgkv._lpos(p_key, p_value, p_rank, 1, 0))[1]::integer;
END;
$$;

-- LMOVE: Atomically move an element from one end of a list to an end of another (or the
-- same) list. p_from_side and p_to_side are LEFT or RIGHT. Returns the element, NULL if the
-- source does not exist.
CREATE OR REPLACE FUNCTION pgkv.lmove(p_source TEXT, p_destination TEXT, p_from_side TEXT, p_to_side TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_from TEXT := upper(p_from_side);
    v_to TEXT := upper(p_to_side);
    v_value TEXT;
BEGIN
    IF v_from NOT IN ('LEFT', 'RIGHT') OR v_to NOT IN ('LEFT', 'RIGHT') THEN
        PERFORM pgkv._err('ERR syntax error');
    END IF;

    -- Lock both keys in key order, and reject a destination of the wrong type before
    -- anything is popped.
    PERFORM pgkv._lock_keys(ARRAY[p_source, p_destination]);
    IF (SELECT p.o_id FROM pgkv._peek(p_source, 'list') p) IS NULL THEN
        RETURN NULL;
    END IF;
    PERFORM pgkv._peek(p_destination, 'list');

    IF p_source = p_destination AND (SELECT p.o_card FROM pgkv._peek(p_source, 'list') p) = 1 THEN
        -- Rotating a one-element list changes nothing; popping it would drop the key's expiry.
        RETURN to_jsonb((pgkv._lrange(p_source, 0, 0))[1]);
    END IF;

    v_value := (pgkv._pop(p_source, 1, v_from = 'LEFT'))[1];
    IF v_value IS NULL THEN
        RETURN NULL;
    END IF;
    PERFORM pgkv._push(p_destination, ARRAY[v_value], v_to = 'LEFT', FALSE);
    RETURN to_jsonb(v_value);
END;
$$;

-- RPOPLPUSH: Move the last element of a list to the head of another
CREATE OR REPLACE FUNCTION pgkv.rpoplpush(p_source TEXT, p_destination TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv.lmove(p_source, p_destination, 'RIGHT', 'LEFT');
END;
$$;

-- ============================================================================
-- Sets: one row per member in pgkv.set_members
-- ============================================================================

-- SADD: Add member(s) to a set. Returns the number of members added.
CREATE OR REPLACE FUNCTION pgkv.sadd(p_key TEXT, VARIADIC p_members TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_added INTEGER;
BEGIN
    v_opened := pgkv._open(p_key, 'set', TRUE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;

    IF array_length(p_members, 1) = 1 THEN
        INSERT INTO pgkv.set_members (id, member) VALUES (v_id, p_members[1])
        ON CONFLICT (id, member) DO NOTHING;
    ELSE
        INSERT INTO pgkv.set_members (id, member)
        SELECT v_id, m FROM unnest(p_members) AS u(m) GROUP BY m
        ON CONFLICT (id, member) DO NOTHING;
    END IF;
    GET DIAGNOSTICS v_added = ROW_COUNT;

    IF v_added > 0 OR v_card = 0 THEN
        PERFORM pgkv._save(p_key, 'set', v_id, v_card + v_added, NULL, v_expires_at);
    END IF;
    RETURN v_added;
END;
$$;

-- SREM: Remove member(s) from a set. Returns the number of members removed.
CREATE OR REPLACE FUNCTION pgkv.srem(p_key TEXT, VARIADIC p_members TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_removed INTEGER;
BEGIN
    v_opened := pgkv._open(p_key, 'set', FALSE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;
    IF v_new THEN
        RETURN 0;
    END IF;

    DELETE FROM pgkv.set_members m WHERE m.id = v_id AND m.member = ANY(p_members);
    GET DIAGNOSTICS v_removed = ROW_COUNT;
    IF v_removed > 0 THEN
        PERFORM pgkv._save(p_key, 'set', v_id, v_card - v_removed, NULL, v_expires_at);
    END IF;
    RETURN v_removed;
END;
$$;

-- _SMEMBERS: the members of a set as an array, in byte order.
CREATE OR REPLACE FUNCTION pgkv._smembers(p_key TEXT)
RETURNS TEXT[]
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
BEGIN
    v_peeked := pgkv._peek(p_key, 'set');
    v_id := v_peeked.o_id;
    RETURN ARRAY(SELECT m.member::text FROM pgkv.set_members m WHERE m.id = v_id ORDER BY m.member);
END;
$$;

-- SMEMBERS: All members of a set, in byte order
CREATE OR REPLACE FUNCTION pgkv.smembers(p_key TEXT)
RETURNS SETOF JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT to_jsonb(u.m) FROM unnest(pgkv._smembers(p_key)) WITH ORDINALITY AS u(m, ord) ORDER BY u.ord;
END;
$$;

-- SISMEMBER: 1 if the member is in the set, 0 if not
CREATE OR REPLACE FUNCTION pgkv.sismember(p_key TEXT, p_member TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_type TEXT;
    v_found BOOLEAN;
BEGIN
    SELECT s.type, m.member IS NOT NULL INTO v_type, v_found
    FROM pgkv.store s
    LEFT JOIN pgkv.set_members m ON m.id = s.id AND m.member = p_member
    WHERE s.key = p_key AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp());

    IF v_type <> 'set' THEN
        PERFORM pgkv._wrongtype();
    END IF;
    RETURN CASE WHEN v_found THEN 1 ELSE 0 END;
END;
$$;

-- SMISMEMBER: For each member, in order, 1 if it is in the set and 0 if not
CREATE OR REPLACE FUNCTION pgkv.smismember(p_key TEXT, VARIADIC p_members TEXT[])
RETURNS SETOF INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
BEGIN
    v_peeked := pgkv._peek(p_key, 'set');
    v_id := v_peeked.o_id;
    RETURN QUERY
    SELECT CASE WHEN m.member IS NULL THEN 0 ELSE 1 END
    FROM unnest(p_members) WITH ORDINALITY AS u(v, ord)
    LEFT JOIN pgkv.set_members m ON m.id = v_id AND m.member = u.v
    ORDER BY u.ord;
END;
$$;

-- SCARD: Number of members in a set
CREATE OR REPLACE FUNCTION pgkv.scard(p_key TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN COALESCE((SELECT p.o_card FROM pgkv._peek(p_key, 'set') p), 0);
END;
$$;

-- _SETOP: the result of SINTER, SUNION or SDIFF over p_keys, in byte order. Every key is
-- type-checked, including those after an empty one.
CREATE OR REPLACE FUNCTION pgkv._setop(p_op TEXT, p_keys TEXT[])
RETURNS TEXT[]
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_peeked RECORD;
    v_ids BIGINT[] := '{}';
    v_key TEXT;
    v_id BIGINT;
BEGIN
    -- 0 stands for a key that does not exist: no member has that id.
    FOREACH v_key IN ARRAY p_keys LOOP
        v_peeked := pgkv._peek(v_key, 'set');
        v_id := v_peeked.o_id;
        v_ids := v_ids || COALESCE(v_id, 0);
    END LOOP;

    IF p_op = 'union' THEN
        RETURN ARRAY(
            SELECT u.member::text
            FROM (SELECT DISTINCT m.member FROM pgkv.set_members m WHERE m.id = ANY(v_ids)) u
            ORDER BY u.member);
    ELSIF p_op = 'inter' THEN
        IF 0 = ANY(v_ids) THEN
            RETURN '{}';
        END IF;
        RETURN ARRAY(
            SELECT m.member::text FROM pgkv.set_members m
            WHERE m.id = ANY(v_ids)
            GROUP BY m.member
            HAVING COUNT(*) = (SELECT COUNT(DISTINCT i) FROM unnest(v_ids) AS i)
            ORDER BY m.member);
    END IF;
    RETURN ARRAY(
        SELECT a.member::text FROM pgkv.set_members a
        WHERE a.id = v_ids[1]
          AND NOT EXISTS (SELECT 1 FROM pgkv.set_members b WHERE b.id = ANY(v_ids[2:]) AND b.member = a.member)
        ORDER BY a.member);
END;
$$;

-- SINTER: Members common to all the given sets
CREATE OR REPLACE FUNCTION pgkv.sinter(VARIADIC p_keys TEXT[])
RETURNS SETOF JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT to_jsonb(u.m) FROM unnest(pgkv._setop('inter', p_keys)) WITH ORDINALITY AS u(m, ord) ORDER BY u.ord;
END;
$$;

-- SUNION: Members of any of the given sets
CREATE OR REPLACE FUNCTION pgkv.sunion(VARIADIC p_keys TEXT[])
RETURNS SETOF JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT to_jsonb(u.m) FROM unnest(pgkv._setop('union', p_keys)) WITH ORDINALITY AS u(m, ord) ORDER BY u.ord;
END;
$$;

-- SDIFF: Members of the first set that are in none of the others
CREATE OR REPLACE FUNCTION pgkv.sdiff(VARIADIC p_keys TEXT[])
RETURNS SETOF JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT to_jsonb(u.m) FROM unnest(pgkv._setop('diff', p_keys)) WITH ORDINALITY AS u(m, ord) ORDER BY u.ord;
END;
$$;

-- SINTERCARD: Size of the intersection of the given sets, counting no further than p_limit (0 = no limit)
CREATE OR REPLACE FUNCTION pgkv.sintercard(p_keys TEXT[], p_limit BIGINT DEFAULT 0)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_n INTEGER;
BEGIN
    IF p_limit < 0 THEN
        PERFORM pgkv._err('ERR LIMIT can''t be negative');
    END IF;
    v_n := cardinality(pgkv._setop('inter', p_keys));
    RETURN CASE WHEN p_limit > 0 THEN LEAST(v_n, p_limit) ELSE v_n END;
END;
$$;

-- _STORE_SET: replace p_destination with a set of p_members (the key is deleted if there are none).
CREATE OR REPLACE FUNCTION pgkv._store_set(p_destination TEXT, p_members TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_locked RECORD;
    v_type TEXT;
    v_id BIGINT;
    v_n INTEGER := COALESCE(cardinality(p_members), 0);
BEGIN
    v_locked := pgkv._lock_key(p_destination, TRUE);
    v_type := v_locked.o_type;
    v_id := v_locked.o_id;
    PERFORM pgkv._drop_elems(v_id, v_type);
    IF v_n > 0 THEN
        v_id := nextval('pgkv.collection_id');
        INSERT INTO pgkv.set_members (id, member) SELECT v_id, m FROM unnest(p_members) AS u(m);
    END IF;
    PERFORM pgkv._save(p_destination, 'set', v_id, v_n, NULL, NULL);
    RETURN v_n;
END;
$$;

-- _SETOP_STORE: SINTERSTORE, SUNIONSTORE, SDIFFSTORE.
CREATE OR REPLACE FUNCTION pgkv._setop_store(p_op TEXT, p_destination TEXT, p_keys TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
BEGIN
    PERFORM pgkv._lock_keys(p_keys, ARRAY[p_destination]);
    RETURN pgkv._store_set(p_destination, pgkv._setop(p_op, p_keys));
END;
$$;

-- SINTERSTORE: Store the intersection of the given sets in p_destination. Returns its size.
CREATE OR REPLACE FUNCTION pgkv.sinterstore(p_destination TEXT, VARIADIC p_keys TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._setop_store('inter', p_destination, p_keys);
END;
$$;

-- SUNIONSTORE: Store the union of the given sets in p_destination. Returns its size.
CREATE OR REPLACE FUNCTION pgkv.sunionstore(p_destination TEXT, VARIADIC p_keys TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._setop_store('union', p_destination, p_keys);
END;
$$;

-- SDIFFSTORE: Store the difference of the given sets in p_destination. Returns its size.
CREATE OR REPLACE FUNCTION pgkv.sdiffstore(p_destination TEXT, VARIADIC p_keys TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._setop_store('diff', p_destination, p_keys);
END;
$$;

-- SMOVE: Move a member from one set to another. Returns 1 if moved, 0 if it was not in the source.
CREATE OR REPLACE FUNCTION pgkv.smove(p_source TEXT, p_destination TEXT, p_member TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    PERFORM pgkv._lock_keys(ARRAY[p_source, p_destination]);
    IF (SELECT p.o_id FROM pgkv._peek(p_source, 'set') p) IS NULL THEN
        RETURN 0;
    END IF;
    PERFORM pgkv._peek(p_destination, 'set');
    IF pgkv.sismember(p_source, p_member) = 0 THEN
        RETURN 0;
    END IF;
    IF p_source <> p_destination THEN
        PERFORM pgkv.srem(p_source, p_member);
        PERFORM pgkv.sadd(p_destination, p_member);
    END IF;
    RETURN 1;
END;
$$;

-- SRANDMEMBER: Random members of a set. A positive p_count returns up to that many distinct
-- members; a negative one returns exactly that many, possibly repeating.
CREATE OR REPLACE FUNCTION pgkv.srandmember(p_key TEXT, p_count BIGINT DEFAULT 1)
RETURNS SETOF TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
    v_card BIGINT;
BEGIN
    v_peeked := pgkv._peek(p_key, 'set');
    v_id := v_peeked.o_id;
    v_card := v_peeked.o_card;
    IF v_id IS NULL OR p_count = 0 THEN
        RETURN;
    END IF;
    IF p_count > 0 THEN
        RETURN QUERY SELECT m.member::text FROM pgkv.set_members m WHERE m.id = v_id ORDER BY random() LIMIT p_count;
    ELSE
        RETURN QUERY
        SELECT r.member::text
        FROM generate_series(1, -p_count) AS g
        CROSS JOIN LATERAL (
            SELECT m.member FROM pgkv.set_members m
            WHERE m.id = v_id ORDER BY m.member OFFSET floor(random() * v_card + g * 0)::bigint LIMIT 1
        ) r;
    END IF;
END;
$$;

-- SPOP: Remove and return up to p_count random members of a set
CREATE OR REPLACE FUNCTION pgkv.spop(p_key TEXT, p_count BIGINT DEFAULT 1)
RETURNS SETOF TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_members TEXT[];
BEGIN
    IF p_count < 0 THEN
        PERFORM pgkv._err('ERR value is out of range, must be positive');
    END IF;
    v_opened := pgkv._open(p_key, 'set', FALSE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;
    IF v_new OR p_count = 0 THEN
        RETURN;
    END IF;

    v_members := ARRAY(SELECT m.member::text FROM pgkv.set_members m WHERE m.id = v_id ORDER BY random() LIMIT p_count);
    DELETE FROM pgkv.set_members m WHERE m.id = v_id AND m.member = ANY(v_members);
    PERFORM pgkv._save(p_key, 'set', v_id, v_card - cardinality(v_members), NULL, v_expires_at);
    RETURN QUERY SELECT u.m FROM unnest(v_members) AS u(m);
END;
$$;

-- SSCAN: Iterate the members of a set matching a pattern, p_count at a time, in byte order.
-- Each row carries the cursor for the next call; 0 means the sweep is complete.
CREATE OR REPLACE FUNCTION pgkv.sscan(p_key TEXT, p_cursor BIGINT DEFAULT 0, p_pattern TEXT DEFAULT '*', p_count INTEGER DEFAULT 10)
RETURNS TABLE(cursor BIGINT, member JSONB)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
    v_re TEXT := CASE WHEN COALESCE(p_pattern, '*') = '*' THEN NULL ELSE pgkv._glob_re(p_pattern) END;
BEGIN
    v_peeked := pgkv._peek(p_key, 'set');
    v_id := v_peeked.o_id;
    RETURN QUERY
    WITH page AS (
        SELECT m.member AS mem, row_number() OVER (ORDER BY m.member) AS rn
        FROM pgkv.set_members m
        WHERE m.id = v_id AND (v_re IS NULL OR m.member ~ v_re)
        ORDER BY m.member
        OFFSET p_cursor LIMIT p_count + 1
    )
    SELECT CASE WHEN (SELECT COUNT(*) FROM page) > p_count THEN p_cursor + p_count ELSE 0 END,
           to_jsonb(page.mem::text)
    FROM page WHERE page.rn <= p_cursor + p_count ORDER BY page.mem;
END;
$$;

-- ============================================================================
-- Sorted sets: one row per member in pgkv.zset_members. Scores are doubles, as in Redis;
-- members with equal scores are ordered by byte.
-- ============================================================================

-- ZADD_OPTS: ZADD with Redis options. p_pairs is score, member, score, member, ...
--   p_nx: only add new members       p_xx: only update existing members
--   p_gt / p_lt: update an existing member only if the new score is greater / less
--   p_ch: return the number of members added or changed, not just added
--   p_incr: add the score to the member's score (one pair only); returns the new score
-- Returns a JSON number: the count, or with p_incr the new score as a string, or JSON
-- null if p_incr was stopped by another option.
CREATE OR REPLACE FUNCTION pgkv.zadd_opts(
    p_key TEXT,
    p_pairs TEXT[],
    p_nx BOOLEAN DEFAULT FALSE,
    p_xx BOOLEAN DEFAULT FALSE,
    p_gt BOOLEAN DEFAULT FALSE,
    p_lt BOOLEAN DEFAULT FALSE,
    p_ch BOOLEAN DEFAULT FALSE,
    p_incr BOOLEAN DEFAULT FALSE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_n INTEGER := COALESCE(array_length(p_pairs, 1), 0);
    v_scores DOUBLE PRECISION[] := '{}';
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_added INTEGER := 0;
    v_changed INTEGER := 0;
    v_current DOUBLE PRECISION;
    v_score DOUBLE PRECISION;
    v_i INTEGER;
BEGIN
    IF p_nx AND p_xx THEN
        PERFORM pgkv._err('ERR XX and NX options at the same time are not compatible');
    END IF;
    IF (p_gt AND p_lt) OR (p_nx AND (p_gt OR p_lt)) THEN
        PERFORM pgkv._err('ERR GT, LT, and/or NX options at the same time are not compatible');
    END IF;
    IF v_n = 0 OR v_n % 2 <> 0 THEN
        PERFORM pgkv._err('ERR syntax error');
    END IF;
    IF p_incr AND v_n > 2 THEN
        PERFORM pgkv._err('ERR INCR option supports a single increment-element pair');
    END IF;
    -- Every score is checked before anything is written.
    FOR v_i IN 1..v_n BY 2 LOOP
        v_scores := v_scores || pgkv._float(p_pairs[v_i]);
    END LOOP;

    v_opened := pgkv._open(p_key, 'zset', NOT p_xx);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;
    IF v_new AND p_xx THEN
        RETURN CASE WHEN p_incr THEN 'null'::jsonb ELSE '0'::jsonb END;
    END IF;

    FOR v_i IN 1..v_n / 2 LOOP
        v_score := v_scores[v_i];
        SELECT z.score INTO v_current FROM pgkv.zset_members z WHERE z.id = v_id AND z.member = p_pairs[v_i * 2];
        IF NOT FOUND THEN
            IF p_xx THEN
                IF p_incr THEN RETURN 'null'::jsonb; END IF;
                CONTINUE;
            END IF;
            INSERT INTO pgkv.zset_members (id, member, score) VALUES (v_id, p_pairs[v_i * 2], v_score + 0);
            v_added := v_added + 1;
        ELSE
            IF p_incr THEN
                v_score := pgkv._fadd(v_current, v_score);
                IF v_score = 'NaN' THEN
                    PERFORM pgkv._err('ERR resulting score is not a number (NaN)');
                END IF;
            END IF;
            IF p_nx OR (p_gt AND v_score <= v_current) OR (p_lt AND v_score >= v_current) THEN
                IF p_incr THEN RETURN 'null'::jsonb; END IF;
                CONTINUE;
            END IF;
            IF v_score <> v_current THEN
                UPDATE pgkv.zset_members z SET score = v_score WHERE z.id = v_id AND z.member = p_pairs[v_i * 2];
                v_changed := v_changed + 1;
            END IF;
        END IF;
    END LOOP;

    IF v_added > 0 OR v_new THEN
        PERFORM pgkv._save(p_key, 'zset', v_id, v_card + v_added, NULL, v_expires_at);
    END IF;
    IF p_incr THEN
        RETURN to_jsonb(pgkv._fmt(v_score));
    END IF;
    RETURN to_jsonb(CASE WHEN p_ch THEN v_added + v_changed ELSE v_added END);
END;
$$;

-- ZADD: Add member(s) with scores to a sorted set, or update their scores.
-- Arguments are score, member, score, member, ... Returns the number of members added.
CREATE OR REPLACE FUNCTION pgkv.zadd(p_key TEXT, VARIADIC p_pairs TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_n INTEGER := COALESCE(array_length(p_pairs, 1), 0);
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_added INTEGER;
    v_scores DOUBLE PRECISION[] := '{}';
    v_i INTEGER;
BEGIN
    IF v_n = 0 OR v_n % 2 <> 0 THEN
        PERFORM pgkv._err('ERR syntax error');
    END IF;
    -- Every score is checked before the key is looked at, as in Redis. A score of -0 is stored as 0.
    FOR v_i IN 1..v_n BY 2 LOOP
        v_scores := v_scores || (pgkv._float(p_pairs[v_i]) + 0);
    END LOOP;

    v_opened := pgkv._open(p_key, 'zset', TRUE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;

    IF v_n = 2 THEN
        INSERT INTO pgkv.zset_members AS z (id, member, score)
        VALUES (v_id, p_pairs[2], v_scores[1])
        ON CONFLICT (id, member) DO UPDATE SET score = EXCLUDED.score
        WHERE z.score <> EXCLUDED.score
        RETURNING (z.xmax = 0)::integer INTO v_added;
        v_added := COALESCE(v_added, 0);
    ELSE
        -- A member given twice takes its last score. Unchanged scores are not rewritten.
        WITH written AS (
            INSERT INTO pgkv.zset_members AS z (id, member, score)
            SELECT v_id, d.m, d.s
            FROM (
                SELECT DISTINCT ON (p_pairs[i + 1]) p_pairs[i + 1] AS m, v_scores[(i + 1) / 2] AS s
                FROM generate_series(1, v_n, 2) AS i
                ORDER BY p_pairs[i + 1], i DESC
            ) d
            ON CONFLICT (id, member) DO UPDATE SET score = EXCLUDED.score
            WHERE z.score <> EXCLUDED.score
            RETURNING (z.xmax = 0) AS inserted
        )
        SELECT (COUNT(*) FILTER (WHERE inserted))::integer INTO v_added FROM written;
    END IF;

    IF v_added > 0 THEN
        PERFORM pgkv._save(p_key, 'zset', v_id, v_card + v_added, NULL, v_expires_at);
    END IF;
    RETURN v_added;
END;
$$;

-- ZINCRBY: Add p_increment to the score of a member, adding the member if needed. Returns the new score.
CREATE OR REPLACE FUNCTION pgkv.zincrby(p_key TEXT, p_increment DOUBLE PRECISION, p_member TEXT)
RETURNS DOUBLE PRECISION
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_current DOUBLE PRECISION;
    v_score DOUBLE PRECISION;
BEGIN
    IF p_increment IS NULL OR p_increment = 'NaN' THEN
        PERFORM pgkv._err('ERR value is not a valid float');
    END IF;
    v_opened := pgkv._open(p_key, 'zset', TRUE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;

    SELECT z.score INTO v_current FROM pgkv.zset_members z WHERE z.id = v_id AND z.member = p_member;
    IF NOT FOUND THEN
        INSERT INTO pgkv.zset_members (id, member, score) VALUES (v_id, p_member, p_increment + 0);
        PERFORM pgkv._save(p_key, 'zset', v_id, v_card + 1, NULL, v_expires_at);
        RETURN p_increment;
    END IF;

    v_score := pgkv._fadd(v_current, p_increment);
    IF v_score = 'NaN' THEN
        PERFORM pgkv._err('ERR resulting score is not a number (NaN)');
    END IF;
    UPDATE pgkv.zset_members z SET score = v_score WHERE z.id = v_id AND z.member = p_member;
    RETURN v_score;
END;
$$;

-- ZREM: Remove member(s) from a sorted set. Returns the number removed.
CREATE OR REPLACE FUNCTION pgkv.zrem(p_key TEXT, VARIADIC p_members TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_removed INTEGER;
BEGIN
    v_opened := pgkv._open(p_key, 'zset', FALSE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;
    IF v_new THEN
        RETURN 0;
    END IF;

    DELETE FROM pgkv.zset_members z WHERE z.id = v_id AND z.member = ANY(p_members);
    GET DIAGNOSTICS v_removed = ROW_COUNT;
    IF v_removed > 0 THEN
        PERFORM pgkv._save(p_key, 'zset', v_id, v_card - v_removed, NULL, v_expires_at);
    END IF;
    RETURN v_removed;
END;
$$;

-- ZSCORE: Score of a member (NULL if the member or the key does not exist)
CREATE OR REPLACE FUNCTION pgkv.zscore(p_key TEXT, p_member TEXT)
RETURNS DOUBLE PRECISION
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_type TEXT;
    v_score DOUBLE PRECISION;
BEGIN
    SELECT s.type, z.score INTO v_type, v_score
    FROM pgkv.store s
    LEFT JOIN pgkv.zset_members z ON z.id = s.id AND z.member = p_member
    WHERE s.key = p_key AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp());

    IF v_type <> 'zset' THEN
        PERFORM pgkv._wrongtype();
    END IF;
    RETURN v_score;
END;
$$;

-- ZMSCORE: Scores of several members, in order (NULL for a missing member)
CREATE OR REPLACE FUNCTION pgkv.zmscore(p_key TEXT, VARIADIC p_members TEXT[])
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
BEGIN
    v_peeked := pgkv._peek(p_key, 'zset');
    v_id := v_peeked.o_id;
    RETURN QUERY
    SELECT u.m, z.score
    FROM unnest(p_members) WITH ORDINALITY AS u(m, ord)
    LEFT JOIN pgkv.zset_members z ON z.id = v_id AND z.member = u.m
    ORDER BY u.ord;
END;
$$;

-- ZCARD: Number of members in a sorted set
CREATE OR REPLACE FUNCTION pgkv.zcard(p_key TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN COALESCE((SELECT p.o_card FROM pgkv._peek(p_key, 'zset') p), 0);
END;
$$;

-- _ZRANK: zero-based rank of a member, from the lowest score or (p_rev) the highest.
-- Counts the members before it, so it costs in proportion to the rank.
CREATE OR REPLACE FUNCTION pgkv._zrank(p_key TEXT, p_member TEXT, p_rev BOOLEAN, OUT o_rank BIGINT, OUT o_score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
    v_card BIGINT;
BEGIN
    v_peeked := pgkv._peek(p_key, 'zset');
    v_id := v_peeked.o_id;
    v_card := v_peeked.o_card;
    SELECT z.score INTO o_score FROM pgkv.zset_members z WHERE z.id = v_id AND z.member = p_member;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    IF p_rev THEN
        SELECT COUNT(*) INTO o_rank FROM pgkv.zset_members z
        WHERE z.id = v_id AND (z.id, z.score, z.member) > (v_id, o_score, p_member);
    ELSE
        SELECT COUNT(*) INTO o_rank FROM pgkv.zset_members z
        WHERE z.id = v_id AND (z.id, z.score, z.member) < (v_id, o_score, p_member);
    END IF;
END;
$$;

-- ZRANK: Zero-based rank of a member, lowest score first (NULL if it does not exist)
CREATE OR REPLACE FUNCTION pgkv.zrank(p_key TEXT, p_member TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN (SELECT r.o_rank FROM pgkv._zrank(p_key, p_member, FALSE) r)::integer;
END;
$$;

-- ZREVRANK: Zero-based rank of a member, highest score first (NULL if it does not exist)
CREATE OR REPLACE FUNCTION pgkv.zrevrank(p_key TEXT, p_member TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN (SELECT r.o_rank FROM pgkv._zrank(p_key, p_member, TRUE) r)::integer;
END;
$$;

-- _ZSCORE_BOUND: parse a Redis score bound: a float, optionally preceded by ( for exclusive.
-- Bounds go through C strtod in Redis, which is laxer than score parsing: leading spaces,
-- an empty string (0) and hexadecimal integers are accepted.
CREATE OR REPLACE FUNCTION pgkv._zscore_bound(p_text TEXT, OUT o_value DOUBLE PRECISION, OUT o_exclusive BOOLEAN)
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_text TEXT;
BEGIN
    o_exclusive := left(p_text, 1) = '(';
    v_text := ltrim(CASE WHEN o_exclusive THEN substr(p_text, 2) ELSE p_text END, E' \t\n\r\f\v');
    IF v_text = '' THEN
        o_value := 0;
    ELSIF v_text ~* '^[+-]?0x[0-9a-f]{1,13}$' THEN
        o_value := (CASE WHEN left(v_text, 1) = '-' THEN -1 ELSE 1 END)
            * ('x' || lpad(regexp_replace(v_text, '^[+-]?0[xX]', ''), 16, '0'))::bit(64)::bigint;
    ELSE
        o_value := pgkv._float(v_text, 'ERR min or max is not a float');
    END IF;
END;
$$;

-- _ZLEX_BOUND: parse a Redis lexicographic bound: [x inclusive, (x exclusive, - lowest, + highest.
-- o_infinite is -1 for -, 1 for +, 0 otherwise.
CREATE OR REPLACE FUNCTION pgkv._zlex_bound(p_text TEXT, OUT o_value TEXT, OUT o_exclusive BOOLEAN, OUT o_infinite INTEGER)
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
    o_exclusive := FALSE;
    o_infinite := 0;
    IF p_text = '-' THEN
        o_infinite := -1;
    ELSIF p_text = '+' THEN
        o_infinite := 1;
    ELSIF left(p_text, 1) IN ('[', '(') THEN
        o_exclusive := left(p_text, 1) = '(';
        o_value := substr(p_text, 2);
    ELSE
        RAISE EXCEPTION 'ERR min or max not valid string range item' USING ERRCODE = 'KV000';
    END IF;
END;
$$;

-- _ZRANGE: the members of a sorted set in a range, in order, with their scores.
--   p_by 'RANK':  p_min and p_max are start and stop indexes
--   p_by 'SCORE': score bounds ("1.5", "(1.5", "-inf", "+inf")
--   p_by 'LEX':   member bounds ("[a", "(a", "-", "+"), for sets whose scores are all equal
-- p_rev walks from the highest; p_min is then the upper bound, as in ZRANGE ... REV.
-- p_offset and p_count are LIMIT (not for RANK); a negative count means no limit.
CREATE OR REPLACE FUNCTION pgkv._zrange(
    p_key TEXT, p_by TEXT, p_min TEXT, p_max TEXT, p_rev BOOLEAN, p_offset BIGINT, p_count BIGINT
)
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_off BIGINT;
    v_len BIGINT;
    v_lo DOUBLE PRECISION;
    v_hi DOUBLE PRECISION;
    v_lo_ex BOOLEAN;
    v_hi_ex BOOLEAN;
    v_llo TEXT;
    v_lhi TEXT;
    v_lo_inf INTEGER;
    v_hi_inf INTEGER;
    v_limit BIGINT := CASE WHEN p_count < 0 THEN NULL ELSE p_count END;
BEGIN
    IF p_by = 'RANK' THEN
        v_off := pgkv._int(p_min);
        v_len := pgkv._int(p_max);
    ELSIF p_by = 'SCORE' THEN
        SELECT b.o_value, b.o_exclusive INTO v_lo, v_lo_ex FROM pgkv._zscore_bound(CASE WHEN p_rev THEN p_max ELSE p_min END) b;
        SELECT b.o_value, b.o_exclusive INTO v_hi, v_hi_ex FROM pgkv._zscore_bound(CASE WHEN p_rev THEN p_min ELSE p_max END) b;
    ELSE
        SELECT b.o_value, b.o_exclusive, b.o_infinite INTO v_llo, v_lo_ex, v_lo_inf FROM pgkv._zlex_bound(CASE WHEN p_rev THEN p_max ELSE p_min END) b;
        SELECT b.o_value, b.o_exclusive, b.o_infinite INTO v_lhi, v_hi_ex, v_hi_inf FROM pgkv._zlex_bound(CASE WHEN p_rev THEN p_min ELSE p_max END) b;
    END IF;

    v_peeked := pgkv._peek(p_key, 'zset');
    v_id := v_peeked.o_id;
    v_card := v_peeked.o_card;
    IF v_id IS NULL OR p_offset < 0 THEN
        RETURN;
    END IF;

    IF p_by = 'RANK' THEN
        SELECT r.o_off, r.o_len INTO v_off, v_len FROM pgkv._range(v_off, v_len, v_card) r;
        IF v_len = 0 THEN
            RETURN;
        ELSIF p_rev THEN
            RETURN QUERY SELECT z.member::text, z.score FROM pgkv.zset_members z WHERE z.id = v_id
                ORDER BY z.score DESC, z.member DESC OFFSET v_off LIMIT v_len;
        ELSE
            RETURN QUERY SELECT z.member::text, z.score FROM pgkv.zset_members z WHERE z.id = v_id
                ORDER BY z.score, z.member OFFSET v_off LIMIT v_len;
        END IF;
    ELSIF p_by = 'SCORE' THEN
        IF p_rev THEN
            RETURN QUERY SELECT z.member::text, z.score FROM pgkv.zset_members z
                WHERE z.id = v_id AND z.score >= v_lo AND z.score <= v_hi
                  AND (NOT v_lo_ex OR z.score > v_lo) AND (NOT v_hi_ex OR z.score < v_hi)
                ORDER BY z.score DESC, z.member DESC OFFSET p_offset LIMIT v_limit;
        ELSE
            RETURN QUERY SELECT z.member::text, z.score FROM pgkv.zset_members z
                WHERE z.id = v_id AND z.score >= v_lo AND z.score <= v_hi
                  AND (NOT v_lo_ex OR z.score > v_lo) AND (NOT v_hi_ex OR z.score < v_hi)
                ORDER BY z.score, z.member OFFSET p_offset LIMIT v_limit;
        END IF;
    ELSE
        IF v_lo_inf = 1 OR v_hi_inf = -1 THEN
            RETURN;
        ELSIF p_rev THEN
            RETURN QUERY SELECT z.member::text, z.score FROM pgkv.zset_members z
                WHERE z.id = v_id
                  AND (v_lo_inf = -1 OR z.member > v_llo OR (NOT v_lo_ex AND z.member = v_llo))
                  AND (v_hi_inf = 1 OR z.member < v_lhi OR (NOT v_hi_ex AND z.member = v_lhi))
                ORDER BY z.member DESC OFFSET p_offset LIMIT v_limit;
        ELSE
            RETURN QUERY SELECT z.member::text, z.score FROM pgkv.zset_members z
                WHERE z.id = v_id
                  AND (v_lo_inf = -1 OR z.member > v_llo OR (NOT v_lo_ex AND z.member = v_llo))
                  AND (v_hi_inf = 1 OR z.member < v_lhi OR (NOT v_hi_ex AND z.member = v_lhi))
                ORDER BY z.member OFFSET p_offset LIMIT v_limit;
        END IF;
    END IF;
END;
$$;

-- ZRANGE_BY: ZRANGE with every Redis option. See pgkv._zrange for the arguments, e.g.
--   pgkv.zrange_by('board', '(10', '+inf', 'SCORE', p_offset => 0, p_count => 20)
CREATE OR REPLACE FUNCTION pgkv.zrange_by(
    p_key TEXT,
    p_min TEXT,
    p_max TEXT,
    p_by TEXT DEFAULT 'RANK',
    p_rev BOOLEAN DEFAULT FALSE,
    p_offset BIGINT DEFAULT 0,
    p_count BIGINT DEFAULT -1
)
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    IF upper(p_by) NOT IN ('RANK', 'SCORE', 'LEX') THEN
        PERFORM pgkv._err('ERR syntax error');
    END IF;
    RETURN QUERY SELECT r.member, r.score FROM pgkv._zrange(p_key, upper(p_by), p_min, p_max, p_rev, p_offset, p_count) r;
END;
$$;

-- ZRANGE: Members between two ranks, lowest score first. score is NULL unless p_withscores.
CREATE OR REPLACE FUNCTION pgkv.zrange(p_key TEXT, p_start BIGINT, p_stop BIGINT, p_withscores BOOLEAN DEFAULT FALSE)
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT r.member, CASE WHEN p_withscores THEN r.score END
    FROM pgkv._zrange(p_key, 'RANK', p_start::text, p_stop::text, FALSE, 0, -1) r;
END;
$$;

-- ZREVRANGE: Members between two ranks, highest score first. score is NULL unless p_withscores.
CREATE OR REPLACE FUNCTION pgkv.zrevrange(p_key TEXT, p_start BIGINT, p_stop BIGINT, p_withscores BOOLEAN DEFAULT FALSE)
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT r.member, CASE WHEN p_withscores THEN r.score END
    FROM pgkv._zrange(p_key, 'RANK', p_start::text, p_stop::text, TRUE, 0, -1) r;
END;
$$;

-- ZRANGEBYSCORE: Members with scores between p_min and p_max (inclusive), lowest first.
-- score is NULL unless p_withscores. For exclusive bounds or LIMIT use pgkv.zrange_by.
CREATE OR REPLACE FUNCTION pgkv.zrangebyscore(p_key TEXT, p_min DOUBLE PRECISION, p_max DOUBLE PRECISION, p_withscores BOOLEAN DEFAULT FALSE)
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT r.member, CASE WHEN p_withscores THEN r.score END
    FROM pgkv._zrange(p_key, 'SCORE', p_min::text, p_max::text, FALSE, 0, -1) r;
END;
$$;

-- _ZCOUNT: number of members in a score or lexicographic range (bounds as for pgkv._zrange).
CREATE OR REPLACE FUNCTION pgkv._zcount(p_key TEXT, p_by TEXT, p_min TEXT, p_max TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
AS $$
BEGIN
    RETURN (SELECT COUNT(*) FROM pgkv._zrange(p_key, p_by, p_min, p_max, FALSE, 0, -1))::integer;
END;
$$;

-- ZCOUNT: Number of members with scores between p_min and p_max (inclusive)
CREATE OR REPLACE FUNCTION pgkv.zcount(p_key TEXT, p_min DOUBLE PRECISION, p_max DOUBLE PRECISION)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._zcount(p_key, 'SCORE', p_min::text, p_max::text);
END;
$$;

-- ZLEXCOUNT: Number of members between two lexicographic bounds ("[a", "(a", "-", "+")
CREATE OR REPLACE FUNCTION pgkv.zlexcount(p_key TEXT, p_min TEXT, p_max TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._zcount(p_key, 'LEX', p_min, p_max);
END;
$$;

-- _ZREMRANGE: remove the members in a range (arguments as for pgkv._zrange). Returns them.
CREATE OR REPLACE FUNCTION pgkv._zremrange(p_key TEXT, p_by TEXT, p_min TEXT, p_max TEXT, p_rev BOOLEAN)
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
AS $$
DECLARE
    v_opened RECORD;
    v_id BIGINT;
    v_card BIGINT;
    v_expires_at TIMESTAMPTZ;
    v_new BOOLEAN;
    v_members TEXT[];
    v_scores DOUBLE PRECISION[];
BEGIN
    v_opened := pgkv._open(p_key, 'zset', FALSE);
    v_id := v_opened.o_id;
    v_card := v_opened.o_card;
    v_expires_at := v_opened.o_expires_at;
    v_new := v_opened.o_new;

    SELECT array_agg(r.member ORDER BY r.ord), array_agg(r.score ORDER BY r.ord) INTO v_members, v_scores
    FROM pgkv._zrange(p_key, p_by, p_min, p_max, p_rev, 0, -1) WITH ORDINALITY AS r(member, score, ord);
    IF v_members IS NULL THEN
        RETURN;
    END IF;

    DELETE FROM pgkv.zset_members z WHERE z.id = v_id AND z.member = ANY(v_members);
    PERFORM pgkv._save(p_key, 'zset', v_id, v_card - cardinality(v_members), NULL, v_expires_at);
    RETURN QUERY SELECT u.m, u.s FROM unnest(v_members, v_scores) WITH ORDINALITY AS u(m, s, ord) ORDER BY u.ord;
END;
$$;

-- ZREMRANGEBYRANK: Remove the members between two ranks. Returns the number removed.
CREATE OR REPLACE FUNCTION pgkv.zremrangebyrank(p_key TEXT, p_start BIGINT, p_stop BIGINT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN (SELECT COUNT(*) FROM pgkv._zremrange(p_key, 'RANK', p_start::text, p_stop::text, FALSE))::integer;
END;
$$;

-- ZREMRANGEBYSCORE: Remove the members with scores between p_min and p_max (inclusive)
CREATE OR REPLACE FUNCTION pgkv.zremrangebyscore(p_key TEXT, p_min DOUBLE PRECISION, p_max DOUBLE PRECISION)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN (SELECT COUNT(*) FROM pgkv._zremrange(p_key, 'SCORE', p_min::text, p_max::text, FALSE))::integer;
END;
$$;

-- ZREMRANGEBYLEX: Remove the members between two lexicographic bounds ("[a", "(a", "-", "+")
CREATE OR REPLACE FUNCTION pgkv.zremrangebylex(p_key TEXT, p_min TEXT, p_max TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN (SELECT COUNT(*) FROM pgkv._zremrange(p_key, 'LEX', p_min, p_max, FALSE))::integer;
END;
$$;

-- ZPOPMIN: Remove and return the p_count members with the lowest scores
CREATE OR REPLACE FUNCTION pgkv.zpopmin(p_key TEXT, p_count BIGINT DEFAULT 1)
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    IF p_count < 0 THEN
        PERFORM pgkv._err('ERR value is out of range, must be positive');
    ELSIF p_count = 0 THEN
        PERFORM pgkv._peek(p_key, 'zset');
        RETURN;
    END IF;
    RETURN QUERY SELECT r.member, r.score FROM pgkv._zremrange(p_key, 'RANK', '0', (p_count - 1)::text, FALSE) r;
END;
$$;

-- ZPOPMAX: Remove and return the p_count members with the highest scores
CREATE OR REPLACE FUNCTION pgkv.zpopmax(p_key TEXT, p_count BIGINT DEFAULT 1)
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    IF p_count < 0 THEN
        PERFORM pgkv._err('ERR value is out of range, must be positive');
    ELSIF p_count = 0 THEN
        PERFORM pgkv._peek(p_key, 'zset');
        RETURN;
    END IF;
    RETURN QUERY SELECT r.member, r.score FROM pgkv._zremrange(p_key, 'RANK', '0', (p_count - 1)::text, TRUE) r;
END;
$$;

-- _STORE_ZSET: replace p_destination with a sorted set (the key is deleted if there are no members).
CREATE OR REPLACE FUNCTION pgkv._store_zset(p_destination TEXT, p_members TEXT[], p_scores DOUBLE PRECISION[])
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_locked RECORD;
    v_type TEXT;
    v_id BIGINT;
    v_n INTEGER := COALESCE(cardinality(p_members), 0);
BEGIN
    v_locked := pgkv._lock_key(p_destination, TRUE);
    v_type := v_locked.o_type;
    v_id := v_locked.o_id;
    PERFORM pgkv._drop_elems(v_id, v_type);
    IF v_n > 0 THEN
        v_id := nextval('pgkv.collection_id');
        -- A score of -0 is stored as 0.
        INSERT INTO pgkv.zset_members (id, member, score) SELECT v_id, u.m, u.s + 0 FROM unnest(p_members, p_scores) AS u(m, s);
    END IF;
    PERFORM pgkv._save(p_destination, 'zset', v_id, v_n, NULL, NULL);
    RETURN v_n;
END;
$$;

-- _ZRANGESTORE: store a range of p_source (arguments as for pgkv._zrange) in p_destination.
CREATE OR REPLACE FUNCTION pgkv._zrangestore(
    p_destination TEXT, p_source TEXT, p_by TEXT, p_min TEXT, p_max TEXT, p_rev BOOLEAN, p_offset BIGINT, p_count BIGINT
)
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_members TEXT[];
    v_scores DOUBLE PRECISION[];
BEGIN
    PERFORM pgkv._lock_keys(ARRAY[p_source], ARRAY[p_destination]);
    SELECT array_agg(r.member), array_agg(r.score) INTO v_members, v_scores
    FROM pgkv._zrange(p_source, p_by, p_min, p_max, p_rev, p_offset, p_count) r;
    RETURN pgkv._store_zset(p_destination, v_members, v_scores);
END;
$$;

-- ZRANGESTORE: Store the members of p_source between two ranks in p_destination. Returns how many.
-- p_rev counts ranks from the highest score.
CREATE OR REPLACE FUNCTION pgkv.zrangestore(p_destination TEXT, p_source TEXT, p_start BIGINT, p_stop BIGINT, p_rev BOOLEAN DEFAULT FALSE)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._zrangestore(p_destination, p_source, 'RANK', p_start::text, p_stop::text, p_rev, 0, -1);
END;
$$;

-- _ZCHECK: raise WRONGTYPE unless every key that exists holds a sorted set or a set.
CREATE OR REPLACE FUNCTION pgkv._zcheck(p_keys TEXT[])
RETURNS VOID
LANGUAGE plpgsql
STABLE
AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pgkv.store s
        WHERE s.key = ANY(p_keys) AND s.type NOT IN ('zset', 'set')
          AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp())
    ) THEN
        PERFORM pgkv._wrongtype();
    END IF;
END;
$$;

-- _ZCOMBINE: ZUNION, ZINTER or ZDIFF over p_keys, lowest score first. A plain set counts as
-- a sorted set whose scores are all 1. Scores are multiplied by the key's weight (default 1)
-- and combined with p_aggregate (SUM, MIN or MAX); a result that is not a number becomes 0.
CREATE OR REPLACE FUNCTION pgkv._zcombine(p_op TEXT, p_keys TEXT[], p_weights DOUBLE PRECISION[], p_aggregate TEXT)
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_aggregate TEXT := upper(COALESCE(p_aggregate, 'SUM'));
    v_n INTEGER := COALESCE(cardinality(p_keys), 0);
    v_key TEXT;
    v_type TEXT;
    v_id BIGINT;
    v_zsets BIGINT[] := '{}';
    v_sets BIGINT[] := '{}';
    v_ords INTEGER[] := '{}';
    v_i INTEGER := 0;
BEGIN
    IF v_aggregate NOT IN ('SUM', 'MIN', 'MAX') THEN
        PERFORM pgkv._err('ERR syntax error');
    END IF;
    IF v_n = 0 THEN
        PERFORM pgkv._err('ERR at least 1 input key is needed for ''' || p_op || ''' command');
    END IF;
    IF p_weights IS NOT NULL AND cardinality(p_weights) <> v_n THEN
        PERFORM pgkv._err('ERR syntax error');
    END IF;
    IF 'NaN' = ANY(p_weights) THEN
        PERFORM pgkv._err('ERR weight value is not a float');
    END IF;

    -- v_zsets[i] / v_sets[i] hold the id of key i if it is a sorted set / a set, else 0.
    FOREACH v_key IN ARRAY p_keys LOOP
        v_i := v_i + 1;
        SELECT s.type, s.id INTO v_type, v_id FROM pgkv.store s
        WHERE s.key = v_key AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp());
        IF v_type IS NOT NULL AND v_type NOT IN ('zset', 'set') THEN
            PERFORM pgkv._wrongtype();
        END IF;
        v_zsets := v_zsets || CASE WHEN v_type = 'zset' THEN v_id ELSE 0 END;
        v_sets := v_sets || CASE WHEN v_type = 'set' THEN v_id ELSE 0 END;
        v_ords := v_ords || v_i;
    END LOOP;

    RETURN QUERY
    WITH inputs AS (
        SELECT k.ord, z.member AS m, z.score AS s
        FROM unnest(v_ords, v_zsets) AS k(ord, id) JOIN pgkv.zset_members z ON z.id = k.id
        UNION ALL
        SELECT k.ord, sm.member, 1
        FROM unnest(v_ords, v_sets) AS k(ord, id) JOIN pgkv.set_members sm ON sm.id = k.id
    ), weighted AS (
        SELECT i.ord, i.m, CASE WHEN w.s = 'NaN' THEN 0 ELSE w.s END AS s
        FROM inputs i CROSS JOIN LATERAL (SELECT pgkv._fmul(i.s, COALESCE(p_weights[i.ord], 1)) AS s) w
    ), combined AS (
        SELECT w.m,
               CASE v_aggregate WHEN 'MIN' THEN MIN(w.s) WHEN 'MAX' THEN MAX(w.s) ELSE pgkv._fsum(w.s) END AS s,
               COUNT(*) AS n,
               MIN(w.ord) AS first_ord
        FROM weighted w
        GROUP BY w.m
    )
    SELECT c.m::text, CASE WHEN c.s = 'NaN' THEN 0 ELSE c.s END
    FROM combined c
    WHERE CASE p_op
        WHEN 'zinter' THEN c.n = v_n
        WHEN 'zdiff' THEN c.n = 1 AND c.first_ord = 1
        ELSE TRUE END
    ORDER BY 2, c.m;
END;
$$;

-- ZUNION: Union of sorted sets (see pgkv._zcombine), lowest score first
CREATE OR REPLACE FUNCTION pgkv.zunion(p_keys TEXT[], p_weights DOUBLE PRECISION[] DEFAULT NULL, p_aggregate TEXT DEFAULT 'SUM')
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT r.member, r.score FROM pgkv._zcombine('zunion', p_keys, p_weights, p_aggregate) r;
END;
$$;

-- ZINTER: Intersection of sorted sets, lowest score first
CREATE OR REPLACE FUNCTION pgkv.zinter(p_keys TEXT[], p_weights DOUBLE PRECISION[] DEFAULT NULL, p_aggregate TEXT DEFAULT 'SUM')
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT r.member, r.score FROM pgkv._zcombine('zinter', p_keys, p_weights, p_aggregate) r;
END;
$$;

-- ZDIFF: Members of the first sorted set that are in none of the others, lowest score first
CREATE OR REPLACE FUNCTION pgkv.zdiff(p_keys TEXT[])
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN QUERY SELECT r.member, r.score FROM pgkv._zcombine('zdiff', p_keys, NULL, 'SUM') r;
END;
$$;

-- ZINTERCARD: Size of the intersection of sorted sets, counting no further than p_limit (0 = no limit)
CREATE OR REPLACE FUNCTION pgkv.zintercard(p_keys TEXT[], p_limit BIGINT DEFAULT 0)
RETURNS INTEGER
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_n INTEGER;
BEGIN
    IF p_limit < 0 THEN
        PERFORM pgkv._err('ERR LIMIT can''t be negative');
    END IF;
    SELECT COUNT(*) INTO v_n FROM pgkv._zcombine('zinter', p_keys, NULL, 'SUM');
    RETURN CASE WHEN p_limit > 0 THEN LEAST(v_n, p_limit) ELSE v_n END;
END;
$$;

-- _ZCOMBINE_STORE: ZUNIONSTORE, ZINTERSTORE, ZDIFFSTORE.
CREATE OR REPLACE FUNCTION pgkv._zcombine_store(p_op TEXT, p_destination TEXT, p_keys TEXT[], p_weights DOUBLE PRECISION[], p_aggregate TEXT)
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_members TEXT[];
    v_scores DOUBLE PRECISION[];
BEGIN
    PERFORM pgkv._lock_keys(p_keys, ARRAY[p_destination]);
    SELECT array_agg(r.member), array_agg(r.score) INTO v_members, v_scores
    FROM pgkv._zcombine(p_op, p_keys, p_weights, p_aggregate) r;
    RETURN pgkv._store_zset(p_destination, v_members, v_scores);
END;
$$;

-- ZUNIONSTORE: Store the union of sorted sets in p_destination. Returns its size.
CREATE OR REPLACE FUNCTION pgkv.zunionstore(p_destination TEXT, p_keys TEXT[], p_weights DOUBLE PRECISION[] DEFAULT NULL, p_aggregate TEXT DEFAULT 'SUM')
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._zcombine_store('zunion', p_destination, p_keys, p_weights, p_aggregate);
END;
$$;

-- ZINTERSTORE: Store the intersection of sorted sets in p_destination. Returns its size.
CREATE OR REPLACE FUNCTION pgkv.zinterstore(p_destination TEXT, p_keys TEXT[], p_weights DOUBLE PRECISION[] DEFAULT NULL, p_aggregate TEXT DEFAULT 'SUM')
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._zcombine_store('zinter', p_destination, p_keys, p_weights, p_aggregate);
END;
$$;

-- ZDIFFSTORE: Store the difference of sorted sets in p_destination. Returns its size.
CREATE OR REPLACE FUNCTION pgkv.zdiffstore(p_destination TEXT, p_keys TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    RETURN pgkv._zcombine_store('zdiff', p_destination, p_keys, NULL, 'SUM');
END;
$$;

-- ZRANDMEMBER: Random members of a sorted set. A positive p_count returns up to that many
-- distinct members; a negative one returns exactly that many, possibly repeating.
CREATE OR REPLACE FUNCTION pgkv.zrandmember(p_key TEXT, p_count BIGINT DEFAULT 1)
RETURNS TABLE(member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
    v_card BIGINT;
BEGIN
    v_peeked := pgkv._peek(p_key, 'zset');
    v_id := v_peeked.o_id;
    v_card := v_peeked.o_card;
    IF v_id IS NULL OR p_count = 0 THEN
        RETURN;
    END IF;
    IF p_count > 0 THEN
        RETURN QUERY SELECT z.member::text, z.score FROM pgkv.zset_members z WHERE z.id = v_id ORDER BY random() LIMIT p_count;
    ELSE
        RETURN QUERY
        SELECT r.member::text, r.score
        FROM generate_series(1, -p_count) AS g
        CROSS JOIN LATERAL (
            SELECT z.member, z.score FROM pgkv.zset_members z
            WHERE z.id = v_id ORDER BY z.member OFFSET floor(random() * v_card + g * 0)::bigint LIMIT 1
        ) r;
    END IF;
END;
$$;

-- ZSCAN: Iterate the members of a sorted set matching a pattern, p_count at a time, in byte
-- order of the member. Each row carries the cursor for the next call; 0 means complete.
CREATE OR REPLACE FUNCTION pgkv.zscan(p_key TEXT, p_cursor BIGINT DEFAULT 0, p_pattern TEXT DEFAULT '*', p_count INTEGER DEFAULT 10)
RETURNS TABLE(cursor BIGINT, member TEXT, score DOUBLE PRECISION)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_peeked RECORD;
    v_id BIGINT;
    v_re TEXT := CASE WHEN COALESCE(p_pattern, '*') = '*' THEN NULL ELSE pgkv._glob_re(p_pattern) END;
BEGIN
    v_peeked := pgkv._peek(p_key, 'zset');
    v_id := v_peeked.o_id;
    RETURN QUERY
    WITH page AS (
        SELECT z.member AS mem, z.score AS sc, row_number() OVER (ORDER BY z.member) AS rn
        FROM pgkv.zset_members z
        WHERE z.id = v_id AND (v_re IS NULL OR z.member ~ v_re)
        ORDER BY z.member
        OFFSET p_cursor LIMIT p_count + 1
    )
    SELECT CASE WHEN (SELECT COUNT(*) FROM page) > p_count THEN p_cursor + p_count ELSE 0 END,
           page.mem::text, page.sc
    FROM page WHERE page.rn <= p_cursor + p_count ORDER BY page.mem;
END;
$$;

-- ============================================================================
-- JSON Operations
-- ============================================================================

CREATE OR REPLACE FUNCTION pgkv.json_set(p_key TEXT, p_path TEXT[], p_value JSONB)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_value JSONB;
    v_type TEXT;
    v_expires_at TIMESTAMPTZ;
BEGIN
    SELECT o_value, o_type, o_expires_at INTO v_value, v_type, v_expires_at
    FROM pgkv._lock_key(p_key, TRUE);

    IF v_type IS NULL THEN
        v_value := '{}'::jsonb;
    ELSIF v_type != 'json' THEN
        PERFORM pgkv._wrongtype();
    END IF;

    IF array_length(p_path, 1) IS NULL THEN
        v_value := p_value;
    ELSE
        v_value := jsonb_set(v_value, p_path, p_value, true);
    END IF;

    PERFORM pgkv._put(p_key, v_value, 'json', v_expires_at);
    RETURN 'OK';
END;
$$;

CREATE OR REPLACE FUNCTION pgkv.json_get(p_key TEXT, p_path TEXT[] DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_value JSONB;
    v_type TEXT;
BEGIN
    SELECT s.value, s.type INTO v_value, v_type FROM pgkv.store s
    WHERE s.key = p_key AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp());
    IF v_type IS NULL THEN RETURN NULL; END IF;
    IF v_type != 'json' THEN PERFORM pgkv._wrongtype(); END IF;
    IF p_path IS NULL OR array_length(p_path, 1) IS NULL THEN RETURN v_value; END IF;
    RETURN v_value #> p_path;
END;
$$;

CREATE OR REPLACE FUNCTION pgkv.json_del(p_key TEXT, p_path TEXT[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_value JSONB;
    v_type TEXT;
    v_expires_at TIMESTAMPTZ;
    v_parent_path TEXT[];
    v_leaf TEXT;
    v_parent JSONB;
BEGIN
    SELECT o_value, o_type, o_expires_at INTO v_value, v_type, v_expires_at
    FROM pgkv._lock_key(p_key, FALSE);
    IF v_type IS NULL THEN RETURN 0; END IF;
    IF v_type != 'json' THEN PERFORM pgkv._wrongtype(); END IF;
    IF p_path IS NULL OR array_length(p_path, 1) IS NULL THEN
        DELETE FROM pgkv.store WHERE key = p_key;
        RETURN 1;
    END IF;
    IF v_value #> p_path IS NULL THEN RETURN 0; END IF;

    v_leaf := p_path[array_length(p_path, 1)];
    v_parent_path := p_path[1:array_length(p_path, 1)-1];
    IF array_length(v_parent_path, 1) IS NULL THEN
        v_value := v_value - v_leaf;
    ELSE
        v_parent := (v_value #> v_parent_path) - v_leaf;
        v_value := jsonb_set(v_value, v_parent_path, v_parent, false);
    END IF;
    PERFORM pgkv._put(p_key, v_value, 'json', v_expires_at);
    RETURN 1;
END;
$$;

CREATE OR REPLACE FUNCTION pgkv.json_type(p_key TEXT, p_path TEXT[] DEFAULT NULL)
RETURNS TEXT
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_value JSONB;
BEGIN
    v_value := pgkv.json_get(p_key, p_path);
    IF v_value IS NULL THEN RETURN NULL; END IF;
    RETURN jsonb_typeof(v_value);
END;
$$;

CREATE OR REPLACE FUNCTION pgkv.json_objkeys(p_key TEXT, p_path TEXT[] DEFAULT NULL)
RETURNS SETOF TEXT
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_value JSONB;
BEGIN
    v_value := pgkv.json_get(p_key, p_path);
    IF v_value IS NULL THEN RETURN; END IF;
    IF jsonb_typeof(v_value) != 'object' THEN RAISE EXCEPTION 'WRONGTYPE JSON value is not an object' USING ERRCODE = 'KV001'; END IF;
    RETURN QUERY SELECT key FROM jsonb_object_keys(v_value) AS key ORDER BY key;
END;
$$;

CREATE OR REPLACE FUNCTION pgkv.json_arrappend(p_key TEXT, p_path TEXT[], VARIADIC p_values JSONB[])
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_value JSONB;
    v_type TEXT;
    v_expires_at TIMESTAMPTZ;
    v_array JSONB;
    v_item JSONB;
    v_root BOOLEAN := p_path IS NULL OR array_length(p_path, 1) IS NULL;
BEGIN
    SELECT o_value, o_type, o_expires_at INTO v_value, v_type, v_expires_at
    FROM pgkv._lock_key(p_key, TRUE);

    IF v_type IS NULL THEN
        v_value := '{}'::jsonb;
        v_array := '[]'::jsonb;
    ELSE
        IF v_type != 'json' THEN PERFORM pgkv._wrongtype(); END IF;
        v_array := CASE WHEN v_root THEN v_value ELSE v_value #> p_path END;
        IF v_array IS NULL THEN v_array := '[]'::jsonb; END IF;
    END IF;
    IF jsonb_typeof(v_array) != 'array' THEN RAISE EXCEPTION 'WRONGTYPE JSON value is not an array' USING ERRCODE = 'KV001'; END IF;
    FOREACH v_item IN ARRAY p_values LOOP
        v_array := v_array || jsonb_build_array(v_item);
    END LOOP;

    PERFORM pgkv._put(
        p_key,
        CASE WHEN v_root THEN v_array ELSE jsonb_set(v_value, p_path, v_array, true) END,
        'json',
        v_expires_at
    );
    RETURN jsonb_array_length(v_array);
END;
$$;

-- ============================================================================
-- The Redis command interface: pgkv.call, pgkv.try_call, pgkv.pipeline
--
--   SELECT pgkv.call('SET', 'k', 'v', 'EX', '10');   -- {"status": "OK"}
--   SELECT pgkv.call('LRANGE', 'jobs', '0', '-1');   -- ["a", "b"]
--
-- Arguments are the words of a Redis command, as text. The reply is what a Redis server
-- answers over RESP2, as JSONB:
--   integer        -> number          bulk string -> string
--   nil            -> null            array       -> array
--   simple string  -> {"status": "OK"} (so a client can tell +OK from the string "OK")
-- No command's reply is itself a JSON object, so an object at the top level or as an element
-- of a pipeline's result is always one of the markers: {"status": ...} or {"error": ...}.
--
-- The three functions differ in what happens to a Redis error reply:
--   pgkv.call(...)       raises it: SQLSTATE class KV, message starting with the Redis
--                        error code. Like any PostgreSQL error it aborts the transaction it
--                        happens in.
--                          KV000 ERR ...        KV001 WRONGTYPE ...
--                          KV002 ERR unknown command / wrong number of arguments (what
--                                Redis reports when a command is queued, before it runs)
--   pgkv.try_call(...)   returns it as {"error": "WRONGTYPE ..."} and undoes only that
--                        command, so the caller's transaction carries on.
--   pgkv.pipeline(commands, atomic)
--                        returns an array of replies with errors in place: one round trip
--                        for many commands, and MULTI/EXEC when atomic. A discarded
--                        transaction is {"error": "EXECABORT ...", "previous": [...]}.
-- A database error (deadlock, serialization failure) is raised by all three.
-- The client libraries in clients/ are thin wrappers over try_call and pipeline.
-- ============================================================================

-- _ARITY: the wrong-number-of-arguments error. Redis rejects most of these when a command is
-- queued in MULTI, from its command table (KV002); a few it only finds when the command
-- runs, such as an odd number of MSET arguments (p_at_run, KV000). The message is the same.
CREATE OR REPLACE FUNCTION pgkv._arity(p_command TEXT, p_at_run BOOLEAN DEFAULT FALSE)
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    IF p_at_run THEN
        RAISE EXCEPTION 'ERR wrong number of arguments for ''%'' command', lower(p_command) USING ERRCODE = 'KV000';
    END IF;
    RAISE EXCEPTION 'ERR wrong number of arguments for ''%'' command', lower(p_command) USING ERRCODE = 'KV002';
END;
$$;

CREATE OR REPLACE FUNCTION pgkv._unknown(argv TEXT[])
RETURNS JSONB
LANGUAGE plpgsql
AS $$
BEGIN
    IF cardinality(argv) < 2 THEN
        RAISE EXCEPTION 'ERR unknown command ''%''', argv[1] USING ERRCODE = 'KV002';
    END IF;
    RAISE EXCEPTION 'ERR unknown command ''%'', with args beginning with: %', argv[1],
        (SELECT string_agg('''' || a || ''' ', '') FROM unnest(argv[2:]) AS a)
        USING ERRCODE = 'KV002';
END;
$$;

-- _R: an array of text as a reply (NULL elements become nil).
CREATE OR REPLACE FUNCTION pgkv._r(p_values TEXT[])
RETURNS JSONB
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT CASE WHEN p_values IS NULL OR cardinality(p_values) = 0 THEN '[]'::jsonb ELSE to_jsonb(p_values) END
$$;

-- _RZ: members, with their scores interleaved if p_withscores, as a reply.
CREATE OR REPLACE FUNCTION pgkv._rz(p_members TEXT[], p_scores DOUBLE PRECISION[], p_withscores BOOLEAN)
RETURNS JSONB
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT COALESCE(jsonb_agg(v.e ORDER BY u.ord, v.k), '[]'::jsonb)
    FROM unnest(p_members, p_scores) WITH ORDINALITY AS u(m, s, ord)
    CROSS JOIN LATERAL (VALUES (1, to_jsonb(u.m)), (2, to_jsonb(pgkv._fmt(u.s)))) AS v(k, e)
    WHERE p_withscores OR v.k = 1
$$;

-- _SCAN_OPTS: parse the options of SCAN, HSCAN, SSCAN and ZSCAN from argv[p_from].
CREATE OR REPLACE FUNCTION pgkv._scan_opts(
    argv TEXT[], p_from INTEGER, p_cursor TEXT,
    OUT o_cursor BIGINT, OUT o_pattern TEXT, OUT o_count BIGINT, OUT o_type TEXT, OUT o_novalues BOOLEAN
)
LANGUAGE plpgsql
AS $$
DECLARE
    i INTEGER := p_from;
    n INTEGER := COALESCE(array_length(argv, 1), 0);
    v_opt TEXT;
BEGIN
    o_cursor := pgkv._int(p_cursor, 'ERR invalid cursor');
    IF o_cursor < 0 THEN
        PERFORM pgkv._err('ERR invalid cursor');
    END IF;
    o_pattern := '*';
    o_count := 10;
    o_novalues := FALSE;
    WHILE i <= n LOOP
        v_opt := upper(argv[i]);
        IF v_opt = 'NOVALUES' THEN
            o_novalues := TRUE;
            i := i + 1;
        ELSIF i = n THEN
            PERFORM pgkv._err('ERR syntax error');
        ELSIF v_opt = 'MATCH' THEN
            o_pattern := argv[i + 1];
            i := i + 2;
        ELSIF v_opt = 'COUNT' THEN
            o_count := pgkv._int(argv[i + 1]);
            IF o_count < 1 THEN
                PERFORM pgkv._err('ERR syntax error');
            END IF;
            i := i + 2;
        ELSIF v_opt = 'TYPE' THEN
            o_type := argv[i + 1];
            i := i + 2;
        ELSE
            PERFORM pgkv._err('ERR syntax error');
        END IF;
    END LOOP;
END;
$$;

-- _NUMKEYS: read "numkeys key [key ...]" from argv[p_at]. o_next is the index after the keys.
CREATE OR REPLACE FUNCTION pgkv._numkeys(argv TEXT[], p_at INTEGER, p_command TEXT, OUT o_keys TEXT[], OUT o_next INTEGER)
LANGUAGE plpgsql
AS $$
DECLARE
    v_num BIGINT := pgkv._int(argv[p_at]);
    n INTEGER := COALESCE(array_length(argv, 1), 0);
BEGIN
    IF v_num < 1 THEN
        IF p_command IN ('lmpop', 'zmpop', 'sintercard') THEN
            PERFORM pgkv._err('ERR numkeys should be greater than 0');
        END IF;
        PERFORM pgkv._err('ERR at least 1 input key is needed for ''' || p_command || ''' command');
    END IF;
    IF p_at + v_num > n THEN
        IF p_command = 'sintercard' THEN
            PERFORM pgkv._err('ERR Number of keys can''t be greater than number of args');
        END IF;
        PERFORM pgkv._err('ERR syntax error');
    END IF;
    o_keys := argv[p_at + 1 : p_at + v_num];
    o_next := p_at + v_num + 1;
END;
$$;

-- ---------------------------------------------------------------------------
-- Strings
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pgkv._call_string(c TEXT, argv TEXT[], n INTEGER)
RETURNS JSONB
LANGUAGE plpgsql
AS $$
DECLARE
    i INTEGER;
    v_opt TEXT;
    v_nx BOOLEAN := FALSE;
    v_xx BOOLEAN := FALSE;
    v_get BOOLEAN := FALSE;
    v_keepttl BOOLEAN := FALSE;
    v_persist BOOLEAN := FALSE;
    v_ex BIGINT;
    v_px BIGINT;
    v_exat BIGINT;
    v_pxat BIGINT;
    v_ifeq TEXT;
    v_has_ifeq BOOLEAN := FALSE;
    v_unit TEXT;
    v_amount TEXT;
    v_reply JSONB;
    v_text TEXT;
BEGIN
    CASE c
    WHEN 'SET' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        i := 4;
        WHILE i <= n LOOP
            v_opt := upper(argv[i]);
            IF v_opt = 'NX' THEN v_nx := TRUE;
            ELSIF v_opt = 'XX' THEN v_xx := TRUE;
            ELSIF v_opt = 'GET' THEN v_get := TRUE;
            ELSIF v_opt = 'KEEPTTL' THEN v_keepttl := TRUE;
            ELSIF v_opt IN ('EX', 'PX', 'EXAT', 'PXAT', 'IFEQ') AND i < n THEN
                i := i + 1;
                IF v_opt = 'IFEQ' THEN
                    v_ifeq := argv[i];
                    v_has_ifeq := TRUE;
                ELSIF v_unit IS NOT NULL THEN
                    PERFORM pgkv._err('ERR syntax error');
                ELSE
                    v_unit := v_opt;
                    v_amount := argv[i];
                END IF;
            ELSE
                PERFORM pgkv._err('ERR syntax error');
            END IF;
            i := i + 1;
        END LOOP;
        -- Redis checks the whole option list for syntax before it reads the expiry value.
        IF (v_nx AND v_xx) OR (v_keepttl AND v_unit IS NOT NULL) THEN
            PERFORM pgkv._err('ERR syntax error');
        END IF;
        IF v_unit = 'EX' THEN v_ex := pgkv._int(v_amount);
        ELSIF v_unit = 'PX' THEN v_px := pgkv._int(v_amount);
        ELSIF v_unit = 'EXAT' THEN v_exat := pgkv._int(v_amount);
        ELSIF v_unit = 'PXAT' THEN v_pxat := pgkv._int(v_amount);
        END IF;
        IF v_has_ifeq THEN
            IF v_nx OR v_xx THEN PERFORM pgkv._err('ERR syntax error'); END IF;
            IF v_get THEN
                v_text := pgkv.get(argv[2]) #>> '{}';
            END IF;
            i := pgkv.cas(argv[2], v_ifeq, argv[3], v_ex, v_px, v_exat, v_pxat, v_keepttl);
            IF v_get THEN RETURN COALESCE(to_jsonb(v_text), 'null'::jsonb); END IF;
            RETURN CASE WHEN i = 1 THEN '{"status":"OK"}'::jsonb ELSE 'null'::jsonb END;
        END IF;
        v_reply := pgkv.set_opts(argv[2], argv[3], v_nx, v_xx, v_get, v_ex, v_px, v_exat, v_pxat, v_keepttl);
        IF v_get THEN
            RETURN COALESCE(to_jsonb(v_reply #>> '{}'), 'null'::jsonb);
        END IF;
        RETURN CASE WHEN v_reply IS NULL THEN 'null'::jsonb ELSE '{"status":"OK"}'::jsonb END;
    WHEN 'SETNX' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.setnx(argv[2], argv[3]));
    WHEN 'SETEX', 'PSETEX' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        IF c = 'SETEX' THEN
            PERFORM pgkv._set(argv[2], to_jsonb(argv[4]), pgkv._expires_at(pgkv._int(argv[3]), NULL, NULL, NULL, FALSE, 'setex'), FALSE);
        ELSE
            PERFORM pgkv._set(argv[2], to_jsonb(argv[4]), pgkv._expires_at(NULL, pgkv._int(argv[3]), NULL, NULL, FALSE, 'psetex'), FALSE);
        END IF;
        RETURN '{"status":"OK"}'::jsonb;
    WHEN 'GETSET' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN COALESCE(to_jsonb(pgkv.getset(argv[2], argv[3]) #>> '{}'), 'null'::jsonb);
    WHEN 'GETDEL' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN COALESCE(to_jsonb(pgkv.getdel(argv[2]) #>> '{}'), 'null'::jsonb);
    WHEN 'GETEX' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        IF n > 2 THEN
            v_opt := upper(argv[3]);
            IF NOT ((v_opt = 'PERSIST' AND n = 3) OR (v_opt IN ('EX', 'PX', 'EXAT', 'PXAT') AND n = 4)) THEN
                PERFORM pgkv._err('ERR syntax error');
            END IF;
            -- As in Redis, a missing key answers nil before the expiry value is looked at.
            IF pgkv.get(argv[2]) IS NULL THEN
                RETURN 'null'::jsonb;
            END IF;
            IF v_opt = 'PERSIST' AND n = 3 THEN v_persist := TRUE;
            ELSIF n <> 4 THEN PERFORM pgkv._err('ERR syntax error');
            ELSIF v_opt = 'EX' THEN v_ex := pgkv._int(argv[4]);
            ELSIF v_opt = 'PX' THEN v_px := pgkv._int(argv[4]);
            ELSIF v_opt = 'EXAT' THEN v_exat := pgkv._int(argv[4]);
            ELSIF v_opt = 'PXAT' THEN v_pxat := pgkv._int(argv[4]);
            ELSE PERFORM pgkv._err('ERR syntax error');
            END IF;
        END IF;
        RETURN COALESCE(to_jsonb(pgkv.getex(argv[2], v_ex, v_px, v_exat, v_pxat, v_persist) #>> '{}'), 'null'::jsonb);
    WHEN 'INCR', 'DECR' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.incrby(argv[2], CASE WHEN c = 'INCR' THEN 1 ELSE -1 END));
    WHEN 'INCRBY' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.incrby(argv[2], pgkv._int(argv[3])));
    WHEN 'DECRBY' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.decrby(argv[2], pgkv._int(argv[3])));
    WHEN 'INCRBYFLOAT' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv._num_text(pgkv._incrbyfloat(argv[2], argv[3])));
    WHEN 'APPEND' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.append(argv[2], argv[3]));
    WHEN 'STRLEN' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.strlen(argv[2]));
    WHEN 'GETRANGE', 'SUBSTR' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.getrange(argv[2], pgkv._int(argv[3]), pgkv._int(argv[4])));
    WHEN 'SETRANGE' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.setrange(argv[2], pgkv._int(argv[3]), argv[4]));
    WHEN 'MGET' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN (SELECT jsonb_agg(m.value #>> '{}' ORDER BY m.ord)
                FROM pgkv.mget(VARIADIC argv[2:]) WITH ORDINALITY AS m(key, value, ord));
    WHEN 'MSET' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        IF n % 2 = 0 THEN PERFORM pgkv._arity(c, TRUE); END IF;
        PERFORM pgkv.mset(VARIADIC argv[2:]);
        RETURN '{"status":"OK"}'::jsonb;
    WHEN 'MSETNX' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        IF n % 2 = 0 THEN PERFORM pgkv._arity(c, TRUE); END IF;
        RETURN to_jsonb(pgkv.msetnx(VARIADIC argv[2:]));
    WHEN 'DELIFEQ' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.cad(argv[2], argv[3]));
    WHEN 'DELEX' THEN
        IF n = 2 THEN RETURN to_jsonb(pgkv.del(argv[2])); END IF;
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        IF upper(argv[3]) <> 'IFEQ' THEN PERFORM pgkv._err('ERR syntax error'); END IF;
        RETURN to_jsonb(pgkv.cad(argv[2], argv[4]));
    ELSE
        RETURN pgkv._unknown(argv);
    END CASE;
END;
$$;

-- ---------------------------------------------------------------------------
-- Keys, expiry, connection
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pgkv._call_keys(c TEXT, argv TEXT[], n INTEGER)
RETURNS JSONB
LANGUAGE plpgsql
AS $$
DECLARE
    v_cursor BIGINT;
    v_pattern TEXT;
    v_count BIGINT;
    v_type TEXT;
    v_next BIGINT;
    v_keys TEXT[];
    v_t BIGINT;
    v_replace BOOLEAN := FALSE;
    i INTEGER;
BEGIN
    CASE c
    WHEN 'DEL', 'UNLINK' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.del(VARIADIC argv[2:]));
    WHEN 'EXISTS', 'TOUCH' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.exists(VARIADIC argv[2:]));
    WHEN 'TYPE' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN jsonb_build_object('status', pgkv.type(argv[2]));
    WHEN 'EXPIRE', 'PEXPIRE', 'EXPIREAT', 'PEXPIREAT' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        -- The options are checked before the time, as in Redis.
        PERFORM pgkv._expire_mode(argv[4:]);
        RETURN to_jsonb(pgkv._expire(
            argv[2],
            pgkv._when(pgkv._int(argv[3]), CASE WHEN left(c, 1) = 'P' THEN 'ms' ELSE 's' END, c LIKE '%AT', lower(c)),
            array_to_string(argv[4:], ' ')));
    WHEN 'TTL' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        v_t := pgkv.pttl(argv[2]);
        RETURN to_jsonb(CASE WHEN v_t < 0 THEN v_t ELSE (v_t + 500) / 1000 END);
    WHEN 'PTTL' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.pttl(argv[2]));
    WHEN 'EXPIRETIME' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.expiretime(argv[2]));
    WHEN 'PEXPIRETIME' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.pexpiretime(argv[2]));
    WHEN 'PERSIST' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.persist(argv[2]));
    WHEN 'KEYS' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN pgkv._r(ARRAY(SELECT k FROM pgkv.keys(argv[2]) AS k));
    WHEN 'SCAN' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        SELECT o.o_cursor, o.o_pattern, o.o_count, o.o_type INTO v_cursor, v_pattern, v_count, v_type
        FROM pgkv._scan_opts(argv, 3, argv[2]) o;
        SELECT s.o_next, s.o_keys INTO v_next, v_keys FROM pgkv._scan(v_cursor, v_pattern, v_count, v_type) s;
        RETURN jsonb_build_array(v_next::text, pgkv._r(v_keys));
    WHEN 'DBSIZE' THEN
        IF n <> 1 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.dbsize());
    WHEN 'FLUSHDB', 'FLUSHALL' THEN
        IF n > 2 OR (n = 2 AND upper(argv[2]) NOT IN ('ASYNC', 'SYNC')) THEN PERFORM pgkv._err('ERR syntax error'); END IF;
        PERFORM pgkv.flushall();
        RETURN '{"status":"OK"}'::jsonb;
    WHEN 'RANDOMKEY' THEN
        IF n <> 1 THEN PERFORM pgkv._arity(c); END IF;
        RETURN COALESCE(to_jsonb(pgkv.randomkey()), 'null'::jsonb);
    WHEN 'RENAME' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        PERFORM pgkv.rename(argv[2], argv[3]);
        RETURN '{"status":"OK"}'::jsonb;
    WHEN 'RENAMENX' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.renamenx(argv[2], argv[3]));
    WHEN 'COPY' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        i := 4;
        WHILE i <= n LOOP
            IF upper(argv[i]) = 'REPLACE' THEN
                v_replace := TRUE;
            ELSIF upper(argv[i]) = 'DB' AND i < n THEN
                i := i + 1;
                IF pgkv._int(argv[i]) <> 0 THEN PERFORM pgkv._err('ERR DB index is out of range'); END IF;
            ELSE
                PERFORM pgkv._err('ERR syntax error');
            END IF;
            i := i + 1;
        END LOOP;
        RETURN to_jsonb(pgkv.copy(argv[2], argv[3], v_replace));
    WHEN 'PING' THEN
        IF n > 2 THEN PERFORM pgkv._arity(c, TRUE); END IF;
        RETURN CASE WHEN n = 2 THEN to_jsonb(argv[2]) ELSE '{"status":"PONG"}'::jsonb END;
    WHEN 'ECHO' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(argv[2]);
    WHEN 'TIME' THEN
        IF n <> 1 THEN PERFORM pgkv._arity(c); END IF;
        v_t := (extract(epoch FROM clock_timestamp())::numeric * 1000000)::bigint;
        RETURN jsonb_build_array((v_t / 1000000)::text, (v_t % 1000000)::text);
    WHEN 'SELECT' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        IF pgkv._int(argv[2], 'ERR invalid DB index') <> 0 THEN PERFORM pgkv._err('ERR DB index is out of range'); END IF;
        RETURN '{"status":"OK"}'::jsonb;
    ELSE
        RETURN pgkv._unknown(argv);
    END CASE;
END;
$$;

-- ---------------------------------------------------------------------------
-- Hashes
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pgkv._call_hash(c TEXT, argv TEXT[], n INTEGER)
RETURNS JSONB
LANGUAGE plpgsql
AS $$
DECLARE
    v_cursor BIGINT;
    v_pattern TEXT;
    v_count BIGINT;
    v_novalues BOOLEAN;
    v_with BOOLEAN := FALSE;
    v_fields TEXT[];
    v_values TEXT[];
BEGIN
    CASE c
    WHEN 'HGET' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN COALESCE(to_jsonb(pgkv.hget(argv[2], argv[3]) #>> '{}'), 'null'::jsonb);
    WHEN 'HSET', 'HMSET' THEN
        IF n < 4 THEN PERFORM pgkv._arity(c); END IF;
        IF n % 2 <> 0 THEN PERFORM pgkv._arity(c, TRUE); END IF;
        IF c = 'HMSET' THEN
            PERFORM pgkv.hset(argv[2], VARIADIC argv[3:]);
            RETURN '{"status":"OK"}'::jsonb;
        END IF;
        RETURN to_jsonb(pgkv.hset(argv[2], VARIADIC argv[3:]));
    WHEN 'HSETNX' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.hsetnx(argv[2], argv[3], argv[4]));
    WHEN 'HMGET' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN (SELECT jsonb_agg(h.value #>> '{}' ORDER BY h.ord)
                FROM pgkv.hmget(argv[2], VARIADIC argv[3:]) WITH ORDINALITY AS h(field, value, ord));
    WHEN 'HGETALL' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN (SELECT COALESCE(jsonb_agg(v.e ORDER BY h.ord, v.k), '[]'::jsonb)
                FROM pgkv.hgetall(argv[2]) WITH ORDINALITY AS h(field, value, ord)
                CROSS JOIN LATERAL (VALUES (1, to_jsonb(h.field)), (2, to_jsonb(h.value #>> '{}'))) AS v(k, e));
    WHEN 'HDEL' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.hdel(argv[2], VARIADIC argv[3:]));
    WHEN 'HEXISTS' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.hexists(argv[2], argv[3]));
    WHEN 'HLEN' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.hlen(argv[2]));
    WHEN 'HSTRLEN' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.hstrlen(argv[2], argv[3]));
    WHEN 'HKEYS' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN pgkv._r(ARRAY(SELECT h.field FROM pgkv.hgetall(argv[2]) h));
    WHEN 'HVALS' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN pgkv._r(ARRAY(SELECT h.value #>> '{}' FROM pgkv.hgetall(argv[2]) h));
    WHEN 'HINCRBY' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.hincrby(argv[2], argv[3], pgkv._int(argv[4])));
    WHEN 'HINCRBYFLOAT' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv._num_text(pgkv._hincrbyfloat(argv[2], argv[3], argv[4])));
    WHEN 'HRANDFIELD' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        IF n = 2 THEN
            RETURN COALESCE((SELECT to_jsonb(h.field) FROM pgkv.hrandfield(argv[2], 1) h), 'null'::jsonb);
        END IF;
        IF n = 4 AND upper(argv[4]) = 'WITHVALUES' THEN
            v_with := TRUE;
        ELSIF n <> 3 THEN
            PERFORM pgkv._err('ERR syntax error');
        END IF;
        SELECT array_agg(h.field), array_agg(h.value #>> '{}') INTO v_fields, v_values
        FROM pgkv.hrandfield(argv[2], pgkv._int(argv[3])) h;
        RETURN (SELECT COALESCE(jsonb_agg(v.e ORDER BY u.ord, v.k), '[]'::jsonb)
                FROM unnest(v_fields, v_values) WITH ORDINALITY AS u(f, val, ord)
                CROSS JOIN LATERAL (VALUES (1, to_jsonb(u.f)), (2, to_jsonb(u.val))) AS v(k, e)
                WHERE v_with OR v.k = 1);
    WHEN 'HSCAN' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        SELECT o.o_cursor, o.o_pattern, o.o_count, o.o_novalues INTO v_cursor, v_pattern, v_count, v_novalues
        FROM pgkv._scan_opts(argv, 4, argv[3]) o;
        SELECT array_agg(h.field ORDER BY h.ord), array_agg(h.value #>> '{}' ORDER BY h.ord) INTO v_fields, v_values
        FROM pgkv.hscan(argv[2], v_cursor, v_pattern, (v_count + 1)::integer) WITH ORDINALITY AS h(cursor, field, value, ord);
        RETURN jsonb_build_array(
            CASE WHEN COALESCE(cardinality(v_fields), 0) > v_count THEN (v_cursor + v_count)::text ELSE '0' END,
            (SELECT COALESCE(jsonb_agg(v.e ORDER BY u.ord, v.k), '[]'::jsonb)
             FROM unnest(v_fields[1:v_count], v_values[1:v_count]) WITH ORDINALITY AS u(f, val, ord)
             CROSS JOIN LATERAL (VALUES (1, to_jsonb(u.f)), (2, to_jsonb(u.val))) AS v(k, e)
             WHERE NOT v_novalues OR v.k = 1));
    ELSE
        RETURN pgkv._unknown(argv);
    END CASE;
END;
$$;

-- ---------------------------------------------------------------------------
-- Lists
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pgkv._call_list(c TEXT, argv TEXT[], n INTEGER)
RETURNS JSONB
LANGUAGE plpgsql
AS $$
DECLARE
    v_values TEXT[];
    v_keys TEXT[];
    v_key TEXT;
    v_next INTEGER;
    v_rank BIGINT := 1;
    v_count BIGINT;
    v_maxlen BIGINT := 0;
    v_positions BIGINT[];
    v_opt TEXT;
    i INTEGER;
BEGIN
    CASE c
    WHEN 'LPUSH', 'RPUSH', 'LPUSHX', 'RPUSHX' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv._push(argv[2], argv[3:], left(c, 1) = 'L', right(c, 1) = 'X'));
    WHEN 'LPOP', 'RPOP' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        IF n > 3 THEN PERFORM pgkv._arity(c, TRUE); END IF;
        IF n = 2 THEN
            RETURN COALESCE(to_jsonb((pgkv._pop(argv[2], 1, c = 'LPOP'))[1]), 'null'::jsonb);
        END IF;
        v_values := pgkv._pop(argv[2], pgkv._int(argv[3], 'ERR value is out of range, must be positive'), c = 'LPOP');
        RETURN CASE WHEN v_values IS NULL THEN 'null'::jsonb ELSE pgkv._r(v_values) END;
    WHEN 'LLEN' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.llen(argv[2]));
    WHEN 'LRANGE' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        RETURN pgkv._r(pgkv._lrange(argv[2], pgkv._int(argv[3]), pgkv._int(argv[4])));
    WHEN 'LINDEX' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN COALESCE(pgkv.lindex(argv[2], pgkv._int(argv[3])), 'null'::jsonb);
    WHEN 'LSET' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        PERFORM pgkv.lset(argv[2], pgkv._int(argv[3]), argv[4]);
        RETURN '{"status":"OK"}'::jsonb;
    WHEN 'LTRIM' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        PERFORM pgkv.ltrim(argv[2], pgkv._int(argv[3]), pgkv._int(argv[4]));
        RETURN '{"status":"OK"}'::jsonb;
    WHEN 'LREM' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.lrem(argv[2], pgkv._int(argv[3]), argv[4]));
    WHEN 'LINSERT' THEN
        IF n <> 5 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.linsert(argv[2], argv[3], argv[4], argv[5]));
    WHEN 'LPOS' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        i := 4;
        WHILE i <= n LOOP
            v_opt := upper(argv[i]);
            IF i = n OR v_opt NOT IN ('RANK', 'COUNT', 'MAXLEN') THEN
                PERFORM pgkv._err('ERR syntax error');
            ELSIF v_opt = 'RANK' THEN
                v_rank := pgkv._int(argv[i + 1]);
                IF v_rank = 0 THEN
                    PERFORM pgkv._err('ERR RANK can''t be zero: use 1 to start from the first match, 2 from the second ... or use negative to start from the end of the list');
                END IF;
            ELSIF v_opt = 'COUNT' THEN
                v_count := pgkv._int(argv[i + 1]);
                IF v_count < 0 THEN PERFORM pgkv._err('ERR COUNT can''t be negative'); END IF;
            ELSE
                v_maxlen := pgkv._int(argv[i + 1]);
                IF v_maxlen < 0 THEN PERFORM pgkv._err('ERR MAXLEN can''t be negative'); END IF;
            END IF;
            i := i + 2;
        END LOOP;
        v_positions := pgkv._lpos(argv[2], argv[3], v_rank, COALESCE(v_count, 1), v_maxlen);
        IF v_count IS NULL THEN
            RETURN COALESCE(to_jsonb(v_positions[1]), 'null'::jsonb);
        END IF;
        RETURN CASE WHEN COALESCE(cardinality(v_positions), 0) = 0 THEN '[]'::jsonb ELSE to_jsonb(v_positions) END;
    WHEN 'LMOVE' THEN
        IF n <> 5 THEN PERFORM pgkv._arity(c); END IF;
        RETURN COALESCE(pgkv.lmove(argv[2], argv[3], argv[4], argv[5]), 'null'::jsonb);
    WHEN 'RPOPLPUSH' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN COALESCE(pgkv.lmove(argv[2], argv[3], 'RIGHT', 'LEFT'), 'null'::jsonb);
    WHEN 'LMPOP' THEN
        IF n < 4 THEN PERFORM pgkv._arity(c); END IF;
        SELECT k.o_keys, k.o_next INTO v_keys, v_next FROM pgkv._numkeys(argv, 2, 'lmpop') k;
        v_opt := upper(argv[v_next]);
        v_count := 1;
        IF v_opt IS NULL OR v_opt NOT IN ('LEFT', 'RIGHT') THEN
            PERFORM pgkv._err('ERR syntax error');
        END IF;
        IF n = v_next + 2 AND upper(argv[v_next + 1]) = 'COUNT' THEN
            v_count := pgkv._int(argv[v_next + 2], 'ERR count should be greater than 0');
            IF v_count < 1 THEN PERFORM pgkv._err('ERR count should be greater than 0'); END IF;
        ELSIF n <> v_next THEN
            PERFORM pgkv._err('ERR syntax error');
        END IF;
        FOREACH v_key IN ARRAY v_keys LOOP
            v_values := pgkv._pop(v_key, v_count, v_opt = 'LEFT');
            IF v_values IS NOT NULL THEN
                RETURN jsonb_build_array(v_key, pgkv._r(v_values));
            END IF;
        END LOOP;
        RETURN 'null'::jsonb;
    ELSE
        RETURN pgkv._unknown(argv);
    END CASE;
END;
$$;

-- ---------------------------------------------------------------------------
-- Sets
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION pgkv._call_set(c TEXT, argv TEXT[], n INTEGER)
RETURNS JSONB
LANGUAGE plpgsql
AS $$
DECLARE
    v_cursor BIGINT;
    v_pattern TEXT;
    v_count BIGINT;
    v_keys TEXT[];
    v_next INTEGER;
    v_members TEXT[];
    v_limit BIGINT := 0;
BEGIN
    CASE c
    WHEN 'SADD' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.sadd(argv[2], VARIADIC argv[3:]));
    WHEN 'SREM' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.srem(argv[2], VARIADIC argv[3:]));
    WHEN 'SMEMBERS' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN pgkv._r(pgkv._smembers(argv[2]));
    WHEN 'SISMEMBER' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.sismember(argv[2], argv[3]));
    WHEN 'SMISMEMBER' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN (SELECT jsonb_agg(s.v ORDER BY s.ord) FROM pgkv.smismember(argv[2], VARIADIC argv[3:]) WITH ORDINALITY AS s(v, ord));
    WHEN 'SCARD' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.scard(argv[2]));
    WHEN 'SINTER', 'SUNION', 'SDIFF' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN pgkv._r(pgkv._setop(lower(substr(c, 2)), argv[2:]));
    WHEN 'SINTERSTORE', 'SUNIONSTORE', 'SDIFFSTORE' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv._setop_store(lower(substr(c, 2, length(c) - 6)), argv[2], argv[3:]));
    WHEN 'SINTERCARD' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        SELECT k.o_keys, k.o_next INTO v_keys, v_next FROM pgkv._numkeys(argv, 2, 'sintercard') k;
        IF n = v_next + 1 AND upper(argv[v_next]) = 'LIMIT' THEN
            v_limit := pgkv._int(argv[v_next + 1], 'ERR LIMIT can''t be negative');
        ELSIF n >= v_next THEN
            PERFORM pgkv._err('ERR syntax error');
        END IF;
        RETURN to_jsonb(pgkv.sintercard(v_keys, v_limit));
    WHEN 'SMOVE' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.smove(argv[2], argv[3], argv[4]));
    WHEN 'SPOP' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        IF n > 3 THEN PERFORM pgkv._err('ERR syntax error'); END IF;
        IF n = 2 THEN
            RETURN COALESCE((SELECT to_jsonb(m) FROM pgkv.spop(argv[2], 1) AS m), 'null'::jsonb);
        END IF;
        RETURN pgkv._r(ARRAY(SELECT m FROM pgkv.spop(argv[2], pgkv._int(argv[3], 'ERR value is out of range, must be positive')) AS m));
    WHEN 'SRANDMEMBER' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        IF n > 3 THEN PERFORM pgkv._err('ERR syntax error'); END IF;
        IF n = 2 THEN
            RETURN COALESCE((SELECT to_jsonb(m) FROM pgkv.srandmember(argv[2], 1) AS m), 'null'::jsonb);
        END IF;
        RETURN pgkv._r(ARRAY(SELECT m FROM pgkv.srandmember(argv[2], pgkv._int(argv[3])) AS m));
    WHEN 'SSCAN' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        SELECT o.o_cursor, o.o_pattern, o.o_count INTO v_cursor, v_pattern, v_count FROM pgkv._scan_opts(argv, 4, argv[3]) o;
        v_members := ARRAY(SELECT s.member #>> '{}' FROM pgkv.sscan(argv[2], v_cursor, v_pattern, (v_count + 1)::integer) s);
        RETURN jsonb_build_array(
            CASE WHEN cardinality(v_members) > v_count THEN (v_cursor + v_count)::text ELSE '0' END,
            pgkv._r(v_members[1:v_count]));
    ELSE
        RETURN pgkv._unknown(argv);
    END CASE;
END;
$$;

-- ---------------------------------------------------------------------------
-- Sorted sets
-- ---------------------------------------------------------------------------

-- _ZARGS: parse "numkeys key [key ...] [WEIGHTS w ...] [AGGREGATE SUM|MIN|MAX] [WITHSCORES]".
CREATE OR REPLACE FUNCTION pgkv._zargs(
    argv TEXT[], p_at INTEGER, p_command TEXT, p_allow_withscores BOOLEAN,
    OUT o_keys TEXT[], OUT o_weights DOUBLE PRECISION[], OUT o_aggregate TEXT, OUT o_withscores BOOLEAN
)
LANGUAGE plpgsql
AS $$
DECLARE
    n INTEGER := COALESCE(array_length(argv, 1), 0);
    i INTEGER;
    j INTEGER;
    v_opt TEXT;
BEGIN
    SELECT k.o_keys, k.o_next INTO o_keys, i FROM pgkv._numkeys(argv, p_at, p_command) k;
    -- Redis looks the keys up, and rejects a wrong type, before it reads the options.
    PERFORM pgkv._zcheck(o_keys);
    o_aggregate := 'SUM';
    o_withscores := FALSE;
    WHILE i <= n LOOP
        v_opt := upper(argv[i]);
        IF v_opt = 'WEIGHTS' AND p_command NOT LIKE 'zdiff%' AND i + cardinality(o_keys) <= n THEN
            o_weights := '{}';
            FOR j IN 1..cardinality(o_keys) LOOP
                o_weights := o_weights || pgkv._float(argv[i + j], 'ERR weight value is not a float');
            END LOOP;
            i := i + cardinality(o_keys) + 1;
        ELSIF v_opt = 'AGGREGATE' AND p_command NOT LIKE 'zdiff%' AND i < n AND upper(argv[i + 1]) IN ('SUM', 'MIN', 'MAX') THEN
            o_aggregate := upper(argv[i + 1]);
            i := i + 2;
        ELSIF v_opt = 'WITHSCORES' AND p_allow_withscores THEN
            o_withscores := TRUE;
            i := i + 1;
        ELSE
            PERFORM pgkv._err('ERR syntax error');
        END IF;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION pgkv._call_zset(c TEXT, argv TEXT[], n INTEGER)
RETURNS JSONB
LANGUAGE plpgsql
AS $$
DECLARE
    i INTEGER;
    v_opt TEXT;
    v_nx BOOLEAN := FALSE;
    v_xx BOOLEAN := FALSE;
    v_gt BOOLEAN := FALSE;
    v_lt BOOLEAN := FALSE;
    v_ch BOOLEAN := FALSE;
    v_incr BOOLEAN := FALSE;
    v_with BOOLEAN := FALSE;
    v_rev BOOLEAN := FALSE;
    v_by TEXT := 'RANK';
    v_offset BIGINT := 0;
    v_count BIGINT := -1;
    v_has_limit BOOLEAN := FALSE;
    v_members TEXT[];
    v_scores DOUBLE PRECISION[];
    v_keys TEXT[];
    v_key TEXT;
    v_weights DOUBLE PRECISION[];
    v_aggregate TEXT;
    v_next INTEGER;
    v_rank BIGINT;
    v_score DOUBLE PRECISION;
    v_cursor BIGINT;
    v_pattern TEXT;
    v_base INTEGER;
BEGIN
    CASE c
    WHEN 'ZADD' THEN
        IF n < 4 THEN PERFORM pgkv._arity(c); END IF;
        i := 3;
        WHILE i <= n LOOP
            v_opt := upper(argv[i]);
            IF v_opt = 'NX' THEN v_nx := TRUE;
            ELSIF v_opt = 'XX' THEN v_xx := TRUE;
            ELSIF v_opt = 'GT' THEN v_gt := TRUE;
            ELSIF v_opt = 'LT' THEN v_lt := TRUE;
            ELSIF v_opt = 'CH' THEN v_ch := TRUE;
            ELSIF v_opt = 'INCR' THEN v_incr := TRUE;
            ELSE EXIT;
            END IF;
            i := i + 1;
        END LOOP;
        IF i > n OR (n - i + 1) % 2 <> 0 THEN
            PERFORM pgkv._err('ERR syntax error');
        END IF;
        IF i = 3 THEN
            RETURN to_jsonb(pgkv.zadd(argv[2], VARIADIC argv[3:]));
        END IF;
        RETURN pgkv.zadd_opts(argv[2], argv[i:], v_nx, v_xx, v_gt, v_lt, v_ch, v_incr);
    WHEN 'ZINCRBY' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv._fmt(pgkv.zincrby(argv[2], pgkv._float(argv[3]), argv[4])));
    WHEN 'ZREM' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.zrem(argv[2], VARIADIC argv[3:]));
    WHEN 'ZSCORE' THEN
        IF n <> 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN COALESCE(to_jsonb(pgkv._fmt(pgkv.zscore(argv[2], argv[3]))), 'null'::jsonb);
    WHEN 'ZMSCORE' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        RETURN (SELECT jsonb_agg(pgkv._fmt(z.score) ORDER BY z.ord)
                FROM pgkv.zmscore(argv[2], VARIADIC argv[3:]) WITH ORDINALITY AS z(member, score, ord));
    WHEN 'ZCARD' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv.zcard(argv[2]));
    WHEN 'ZRANK', 'ZREVRANK' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        IF n > 4 THEN PERFORM pgkv._arity(c, TRUE); END IF;
        IF n = 4 AND upper(argv[4]) <> 'WITHSCORE' THEN PERFORM pgkv._err('ERR syntax error'); END IF;
        SELECT r.o_rank, r.o_score INTO v_rank, v_score FROM pgkv._zrank(argv[2], argv[3], c = 'ZREVRANK') r;
        IF v_rank IS NULL THEN
            RETURN 'null'::jsonb;
        END IF;
        RETURN CASE WHEN n = 4 THEN jsonb_build_array(v_rank, pgkv._fmt(v_score)) ELSE to_jsonb(v_rank) END;
    WHEN 'ZCOUNT' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv._zcount(argv[2], 'SCORE', argv[3], argv[4]));
    WHEN 'ZLEXCOUNT' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        RETURN to_jsonb(pgkv._zcount(argv[2], 'LEX', argv[3], argv[4]));
    WHEN 'ZRANGE', 'ZREVRANGE', 'ZRANGEBYSCORE', 'ZREVRANGEBYSCORE', 'ZRANGEBYLEX', 'ZREVRANGEBYLEX', 'ZRANGESTORE' THEN
        -- v_base: index of the key; min and max follow it.
        v_base := CASE WHEN c = 'ZRANGESTORE' THEN 3 ELSE 2 END;
        IF n < v_base + 2 THEN PERFORM pgkv._arity(c); END IF;
        v_rev := c LIKE 'ZREV%';
        IF c LIKE '%BYSCORE' THEN v_by := 'SCORE'; ELSIF c LIKE '%BYLEX' THEN v_by := 'LEX'; END IF;
        i := v_base + 3;
        WHILE i <= n LOOP
            v_opt := upper(argv[i]);
            IF v_opt = 'WITHSCORES' AND c NOT IN ('ZRANGEBYLEX', 'ZREVRANGEBYLEX', 'ZRANGESTORE') THEN
                v_with := TRUE;
            ELSIF v_opt = 'LIMIT' AND i + 2 <= n AND c NOT IN ('ZREVRANGE') THEN
                v_offset := pgkv._int(argv[i + 1]);
                v_count := pgkv._int(argv[i + 2]);
                v_has_limit := TRUE;
                i := i + 2;
            ELSIF v_opt = 'BYSCORE' AND c IN ('ZRANGE', 'ZRANGESTORE') THEN
                v_by := 'SCORE';
            ELSIF v_opt = 'BYLEX' AND c IN ('ZRANGE', 'ZRANGESTORE') THEN
                v_by := 'LEX';
            ELSIF v_opt = 'REV' AND c IN ('ZRANGE', 'ZRANGESTORE') THEN
                v_rev := TRUE;
            ELSE
                PERFORM pgkv._err('ERR syntax error');
            END IF;
            i := i + 1;
        END LOOP;
        IF v_has_limit AND v_by = 'RANK' THEN
            PERFORM pgkv._err('ERR syntax error, LIMIT is only supported in combination with either BYSCORE or BYLEX');
        END IF;
        IF v_with AND v_by = 'LEX' THEN
            PERFORM pgkv._err('ERR syntax error, WITHSCORES not supported in combination with BYLEX');
        END IF;
        IF c = 'ZRANGESTORE' THEN
            RETURN to_jsonb(pgkv._zrangestore(argv[2], argv[3], v_by, argv[4], argv[5], v_rev, v_offset, v_count));
        END IF;
        SELECT array_agg(r.member ORDER BY r.ord), array_agg(r.score ORDER BY r.ord) INTO v_members, v_scores
        FROM pgkv._zrange(argv[2], v_by, argv[3], argv[4], v_rev, v_offset, v_count) WITH ORDINALITY AS r(member, score, ord);
        RETURN pgkv._rz(v_members, v_scores, v_with);
    WHEN 'ZREMRANGEBYRANK', 'ZREMRANGEBYSCORE', 'ZREMRANGEBYLEX' THEN
        IF n <> 4 THEN PERFORM pgkv._arity(c); END IF;
        -- Validate the bounds even when the key does not exist.
        PERFORM 1 FROM pgkv._zrange('', substr(c, 12), argv[3], argv[4], FALSE, 0, 0);
        RETURN to_jsonb((SELECT COUNT(*) FROM pgkv._zremrange(argv[2], substr(c, 12), argv[3], argv[4], FALSE)));
    WHEN 'ZPOPMIN', 'ZPOPMAX' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        IF n > 3 THEN PERFORM pgkv._err('ERR syntax error'); END IF;
        v_count := CASE WHEN n = 3 THEN pgkv._int(argv[3], 'ERR value is out of range, must be positive') ELSE 1 END;
        IF v_count < 0 THEN PERFORM pgkv._err('ERR value is out of range, must be positive'); END IF;
        IF v_count = 0 THEN
            PERFORM pgkv._peek(argv[2], 'zset');
            RETURN '[]'::jsonb;
        END IF;
        SELECT array_agg(r.member ORDER BY r.ord), array_agg(r.score ORDER BY r.ord) INTO v_members, v_scores
        FROM pgkv._zremrange(argv[2], 'RANK', '0', (v_count - 1)::text, c = 'ZPOPMAX') WITH ORDINALITY AS r(member, score, ord);
        RETURN pgkv._rz(v_members, v_scores, TRUE);
    WHEN 'ZMPOP' THEN
        IF n < 4 THEN PERFORM pgkv._arity(c); END IF;
        SELECT k.o_keys, k.o_next INTO v_keys, v_next FROM pgkv._numkeys(argv, 2, 'zmpop') k;
        v_opt := upper(argv[v_next]);
        v_count := 1;
        IF v_opt IS NULL OR v_opt NOT IN ('MIN', 'MAX') THEN
            PERFORM pgkv._err('ERR syntax error');
        END IF;
        IF n = v_next + 2 AND upper(argv[v_next + 1]) = 'COUNT' THEN
            v_count := pgkv._int(argv[v_next + 2], 'ERR count should be greater than 0');
            IF v_count < 1 THEN PERFORM pgkv._err('ERR count should be greater than 0'); END IF;
        ELSIF n <> v_next THEN
            PERFORM pgkv._err('ERR syntax error');
        END IF;
        FOREACH v_key IN ARRAY v_keys LOOP
            SELECT array_agg(r.member ORDER BY r.ord), array_agg(r.score ORDER BY r.ord) INTO v_members, v_scores
            FROM pgkv._zremrange(v_key, 'RANK', '0', (v_count - 1)::text, v_opt = 'MAX') WITH ORDINALITY AS r(member, score, ord);
            IF v_members IS NOT NULL THEN
                RETURN jsonb_build_array(v_key, (
                    SELECT jsonb_agg(jsonb_build_array(u.m, pgkv._fmt(u.s)) ORDER BY u.ord)
                    FROM unnest(v_members, v_scores) WITH ORDINALITY AS u(m, s, ord)));
            END IF;
        END LOOP;
        RETURN 'null'::jsonb;
    WHEN 'ZUNIONSTORE', 'ZINTERSTORE', 'ZDIFFSTORE' THEN
        IF n < 4 THEN PERFORM pgkv._arity(c); END IF;
        SELECT a.o_keys, a.o_weights, a.o_aggregate INTO v_keys, v_weights, v_aggregate
        FROM pgkv._zargs(argv, 3, lower(c), FALSE) a;
        RETURN to_jsonb(pgkv._zcombine_store(lower(substr(c, 1, length(c) - 5)), argv[2], v_keys, v_weights, v_aggregate));
    WHEN 'ZUNION', 'ZINTER', 'ZDIFF' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        SELECT a.o_keys, a.o_weights, a.o_aggregate, a.o_withscores INTO v_keys, v_weights, v_aggregate, v_with
        FROM pgkv._zargs(argv, 2, lower(c), TRUE) a;
        SELECT array_agg(r.member ORDER BY r.ord), array_agg(r.score ORDER BY r.ord) INTO v_members, v_scores
        FROM pgkv._zcombine(lower(c), v_keys, v_weights, v_aggregate) WITH ORDINALITY AS r(member, score, ord);
        RETURN pgkv._rz(v_members, v_scores, v_with);
    WHEN 'ZINTERCARD' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        SELECT k.o_keys, k.o_next INTO v_keys, v_next FROM pgkv._numkeys(argv, 2, 'zintercard') k;
        PERFORM pgkv._zcheck(v_keys);
        v_count := 0;
        IF n = v_next + 1 AND upper(argv[v_next]) = 'LIMIT' THEN
            v_count := pgkv._int(argv[v_next + 1], 'ERR LIMIT can''t be negative');
        ELSIF n >= v_next THEN
            PERFORM pgkv._err('ERR syntax error');
        END IF;
        RETURN to_jsonb(pgkv.zintercard(v_keys, v_count));
    WHEN 'ZRANDMEMBER' THEN
        IF n < 2 THEN PERFORM pgkv._arity(c); END IF;
        IF n = 2 THEN
            RETURN COALESCE((SELECT to_jsonb(z.member) FROM pgkv.zrandmember(argv[2], 1) z), 'null'::jsonb);
        END IF;
        IF n = 4 AND upper(argv[4]) = 'WITHSCORES' THEN
            v_with := TRUE;
        ELSIF n <> 3 THEN
            PERFORM pgkv._err('ERR syntax error');
        END IF;
        SELECT array_agg(z.member), array_agg(z.score) INTO v_members, v_scores
        FROM pgkv.zrandmember(argv[2], pgkv._int(argv[3])) z;
        RETURN pgkv._rz(v_members, v_scores, v_with);
    WHEN 'ZSCAN' THEN
        IF n < 3 THEN PERFORM pgkv._arity(c); END IF;
        SELECT o.o_cursor, o.o_pattern, o.o_count INTO v_cursor, v_pattern, v_count FROM pgkv._scan_opts(argv, 4, argv[3]) o;
        SELECT array_agg(z.member ORDER BY z.ord), array_agg(z.score ORDER BY z.ord) INTO v_members, v_scores
        FROM pgkv.zscan(argv[2], v_cursor, v_pattern, (v_count + 1)::integer) WITH ORDINALITY AS z(cursor, member, score, ord);
        RETURN jsonb_build_array(
            CASE WHEN COALESCE(cardinality(v_members), 0) > v_count THEN (v_cursor + v_count)::text ELSE '0' END,
            pgkv._rz(v_members[1:v_count], v_scores[1:v_count], TRUE));
    ELSE
        RETURN pgkv._unknown(argv);
    END CASE;
END;
$$;

-- _DISPATCH: run one Redis command given as an array of words.
CREATE OR REPLACE FUNCTION pgkv._dispatch(argv TEXT[])
RETURNS JSONB
LANGUAGE plpgsql
AS $$
DECLARE
    n INTEGER := COALESCE(array_length(argv, 1), 0);
    c TEXT;
BEGIN
    IF n = 0 OR array_position(argv, NULL) IS NOT NULL THEN
        PERFORM pgkv._err('ERR pgkv.call takes a command name followed by non-null arguments');
    END IF;
    c := upper(argv[1]);

    -- The commonest commands first, then by family.
    IF c = 'GET' THEN
        IF n <> 2 THEN PERFORM pgkv._arity(c); END IF;
        RETURN COALESCE(to_jsonb(pgkv.get(argv[2]) #>> '{}'), 'null'::jsonb);
    ELSIF c = 'SET' AND n = 3 THEN
        PERFORM pgkv._set(argv[2], to_jsonb(argv[3]), NULL, FALSE);
        RETURN '{"status":"OK"}'::jsonb;
    END IF;

    CASE left(c, 1)
    WHEN 'H' THEN
        RETURN pgkv._call_hash(c, argv, n);
    WHEN 'Z' THEN
        RETURN pgkv._call_zset(c, argv, n);
    WHEN 'L' THEN
        RETURN pgkv._call_list(c, argv, n);
    WHEN 'S' THEN
        IF c IN ('SET', 'SETEX', 'SETNX', 'SETRANGE', 'STRLEN', 'SUBSTR') THEN
            RETURN pgkv._call_string(c, argv, n);
        ELSIF c IN ('SCAN', 'SELECT') THEN
            RETURN pgkv._call_keys(c, argv, n);
        END IF;
        RETURN pgkv._call_set(c, argv, n);
    WHEN 'R' THEN
        IF c IN ('RPUSH', 'RPOP', 'RPUSHX', 'RPOPLPUSH') THEN
            RETURN pgkv._call_list(c, argv, n);
        END IF;
        RETURN pgkv._call_keys(c, argv, n);
    WHEN 'G', 'I', 'A', 'M' THEN
        RETURN pgkv._call_string(c, argv, n);
    ELSE
        IF c IN ('DECR', 'DECRBY', 'DELIFEQ', 'DELEX', 'PSETEX') THEN
            RETURN pgkv._call_string(c, argv, n);
        END IF;
        RETURN pgkv._call_keys(c, argv, n);
    END CASE;
END;
$$;

-- CALL: Run a Redis command. See the top of this section.
CREATE OR REPLACE FUNCTION pgkv.call(VARIADIC argv TEXT[])
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_value TEXT;
    v_type TEXT;
BEGIN
    -- GET is by far the commonest command: answer it here, without the dispatcher.
    IF argv[1] IN ('GET', 'get') AND array_length(argv, 1) = 2 AND argv[2] IS NOT NULL THEN
        SELECT s.value #>> '{}', s.type INTO v_value, v_type
        FROM pgkv.store s
        WHERE s.key = argv[2] AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp());
        IF v_type <> 'string' THEN
            PERFORM pgkv._wrongtype();
        END IF;
        RETURN COALESCE(to_jsonb(v_value), 'null'::jsonb);
    END IF;
    RETURN pgkv._dispatch(argv);
END;
$$;

-- TRY_CALL: Run a Redis command; an error reply is returned as {"error": "<message>"}
-- rather than raised, and undoes only what that command did. Use it inside a transaction
-- you want to survive a WRONGTYPE or a bad argument. It costs a subtransaction per call.
CREATE OR REPLACE FUNCTION pgkv.try_call(VARIADIC argv TEXT[])
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_value TEXT;
    v_type TEXT;
BEGIN
    -- GET, as in pgkv.call: it cannot write, so it needs no subtransaction either.
    IF argv[1] IN ('GET', 'get') AND array_length(argv, 1) = 2 AND argv[2] IS NOT NULL THEN
        SELECT s.value #>> '{}', s.type INTO v_value, v_type
        FROM pgkv.store s
        WHERE s.key = argv[2] AND (s.expires_at IS NULL OR s.expires_at >= clock_timestamp());
        IF v_type <> 'string' THEN
            RETURN jsonb_build_object('error', 'WRONGTYPE Operation against a key holding the wrong kind of value');
        END IF;
        RETURN COALESCE(to_jsonb(v_value), 'null'::jsonb);
    END IF;

    BEGIN
        RETURN pgkv._dispatch(argv);
    EXCEPTION WHEN SQLSTATE 'KV000' OR SQLSTATE 'KV001' OR SQLSTATE 'KV002' THEN
        RETURN jsonb_build_object('error', SQLERRM);
    END;
END;
$$;

-- PIPELINE: Run several Redis commands in one call. p_commands is a JSON array of commands,
-- each an array of strings: '[["SET","k","v"],["INCR","n"]]'. Returns the array of replies;
-- a command that fails contributes {"error": "<message>"} and undoes only itself, the others
-- still apply, as in Redis.
-- The commands run in one statement, so other sessions see all of their effects or none.
-- p_atomic makes it MULTI/EXEC: if a command is unknown or has the wrong number of
-- arguments (the errors Redis detects while queueing), nothing is applied and the result is
-- not an array but the object
--   {"error": "EXECABORT Transaction discarded because of previous errors.",
--    "previous": [{"index": 1, "error": "ERR unknown command ..."}]}
-- listing every refused command by its zero-based position.
-- A Redis error never raises here, so it never aborts the caller's transaction. A database
-- error (deadlock, serialization failure) is raised and undoes everything.
CREATE OR REPLACE FUNCTION pgkv.pipeline(p_commands JSONB, p_atomic BOOLEAN DEFAULT FALSE)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_words TEXT[];
    v_lengths INTEGER[];
    v_length INTEGER;
    v_at INTEGER := 1;
    v_index INTEGER := 0;
    v_replies JSONB[] := '{}';
    v_refused JSONB[] := '{}';
BEGIN
    IF p_commands IS NULL OR jsonb_typeof(p_commands) <> 'array'
        OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_commands) AS c(command) WHERE jsonb_typeof(c.command) <> 'array') THEN
        PERFORM pgkv._err('ERR pgkv.pipeline takes a JSON array of commands, each an array of strings');
    END IF;

    -- Every command's words in one array, and how many words each command has.
    SELECT array_agg(jsonb_array_length(c.command) ORDER BY c.ord) INTO v_lengths
    FROM jsonb_array_elements(p_commands) WITH ORDINALITY AS c(command, ord);
    SELECT array_agg(w.word ORDER BY c.ord, w.ord) INTO v_words
    FROM jsonb_array_elements(p_commands) WITH ORDINALITY AS c(command, ord)
    CROSS JOIN LATERAL jsonb_array_elements_text(c.command) WITH ORDINALITY AS w(word, ord);

    -- The inner block is a subtransaction per command, so a failure undoes that command only.
    -- The outer block is what a discarded transaction rolls back to.
    BEGIN
        FOREACH v_length IN ARRAY COALESCE(v_lengths, '{}') LOOP
            BEGIN
                v_replies := v_replies || pgkv._dispatch(COALESCE(v_words[v_at : v_at + v_length - 1], '{}'));
            EXCEPTION
                WHEN SQLSTATE 'KV002' THEN
                    v_replies := v_replies || jsonb_build_object('error', SQLERRM);
                    IF p_atomic THEN
                        v_refused := v_refused || jsonb_build_object('index', v_index, 'error', SQLERRM);
                    END IF;
                WHEN SQLSTATE 'KV000' OR SQLSTATE 'KV001' THEN
                    v_replies := v_replies || jsonb_build_object('error', SQLERRM);
            END;
            v_at := v_at + v_length;
            v_index := v_index + 1;
        END LOOP;

        IF cardinality(v_refused) > 0 THEN
            RAISE EXCEPTION 'EXECABORT Transaction discarded because of previous errors.' USING ERRCODE = 'KV003';
        END IF;
    EXCEPTION WHEN SQLSTATE 'KV003' THEN
        RETURN jsonb_build_object('error', SQLERRM, 'previous', to_jsonb(v_refused));
    END;

    RETURN to_jsonb(v_replies);
END;
$$;

-- COMMANDS: The Redis commands pgkv.call understands
CREATE OR REPLACE FUNCTION pgkv.commands()
RETURNS SETOF TEXT
LANGUAGE sql
IMMUTABLE
SECURITY DEFINER
SET search_path = pgkv, pg_temp
AS $$
    SELECT unnest(ARRAY[
        'APPEND', 'COPY', 'DBSIZE', 'DECR', 'DECRBY', 'DEL', 'DELEX', 'DELIFEQ', 'ECHO', 'EXISTS', 'EXPIRE',
        'EXPIREAT', 'EXPIRETIME', 'FLUSHALL', 'FLUSHDB', 'GET', 'GETDEL', 'GETEX', 'GETRANGE', 'GETSET',
        'HDEL', 'HEXISTS', 'HGET', 'HGETALL', 'HINCRBY', 'HINCRBYFLOAT', 'HKEYS', 'HLEN', 'HMGET', 'HMSET',
        'HRANDFIELD', 'HSCAN', 'HSET', 'HSETNX', 'HSTRLEN', 'HVALS', 'INCR', 'INCRBY', 'INCRBYFLOAT', 'KEYS',
        'LINDEX', 'LINSERT', 'LLEN', 'LMOVE', 'LMPOP', 'LPOP', 'LPOS', 'LPUSH', 'LPUSHX', 'LRANGE', 'LREM',
        'LSET', 'LTRIM', 'MGET', 'MSET', 'MSETNX', 'PERSIST', 'PEXPIRE', 'PEXPIREAT', 'PEXPIRETIME', 'PING',
        'PSETEX', 'PTTL', 'RANDOMKEY', 'RENAME', 'RENAMENX', 'RPOP', 'RPOPLPUSH', 'RPUSH', 'RPUSHX', 'SADD',
        'SCAN', 'SCARD', 'SDIFF', 'SDIFFSTORE', 'SELECT', 'SET', 'SETEX', 'SETNX', 'SETRANGE', 'SINTER',
        'SINTERCARD', 'SINTERSTORE', 'SISMEMBER', 'SMEMBERS', 'SMISMEMBER', 'SMOVE', 'SPOP', 'SRANDMEMBER',
        'SREM', 'SSCAN', 'STRLEN', 'SUBSTR', 'SUNION', 'SUNIONSTORE', 'TIME', 'TOUCH', 'TTL', 'TYPE',
        'UNLINK', 'ZADD', 'ZCARD', 'ZCOUNT', 'ZDIFF', 'ZDIFFSTORE', 'ZINCRBY', 'ZINTER', 'ZINTERCARD',
        'ZINTERSTORE', 'ZLEXCOUNT', 'ZMPOP', 'ZMSCORE', 'ZPOPMAX', 'ZPOPMIN', 'ZRANDMEMBER', 'ZRANGE',
        'ZRANGEBYLEX', 'ZRANGEBYSCORE', 'ZRANGESTORE', 'ZRANK', 'ZREM', 'ZREMRANGEBYLEX', 'ZREMRANGEBYRANK',
        'ZREMRANGEBYSCORE', 'ZREVRANGE', 'ZREVRANGEBYLEX', 'ZREVRANGEBYSCORE', 'ZREVRANK', 'ZSCAN', 'ZSCORE',
        'ZUNION', 'ZUNIONSTORE'
    ])
$$;

-- ============================================================================
-- Access: who may use pgkv
-- ============================================================================
-- pgkv is one shared keyspace behind SECURITY DEFINER functions, so a role that can execute
-- them can read, overwrite and delete every key. Nothing is granted to PUBLIC: the owner
-- (the role that created the extension) names the roles that get access.

-- GRANT_ACCESS: Let a role use pgkv: USAGE on the schema and EXECUTE on the data commands.
-- The maintenance functions (cleanup_expired, set_unlogged and these two) stay with the
-- owner. Run it again after every upgrade, so the role also gets the functions that are new.
CREATE OR REPLACE FUNCTION pgkv.grant_access(p_role REGROLE)
RETURNS VOID
LANGUAGE plpgsql
SET search_path = pgkv, pg_temp
AS $$
DECLARE
    v_function REGPROCEDURE;
BEGIN
    IF p_role IS NULL THEN
        RAISE EXCEPTION 'pgkv.grant_access: role is required';
    END IF;
    EXECUTE format('GRANT USAGE ON SCHEMA pgkv TO %s', p_role);
    FOR v_function IN
        SELECT p.oid::regprocedure FROM pg_catalog.pg_proc p
        WHERE p.pronamespace = 'pgkv'::regnamespace
          AND p.proname NOT LIKE E'\\_%'
          AND p.proname <> ALL (ARRAY['grant_access', 'revoke_access', 'cleanup_expired', 'set_unlogged'])
    LOOP
        EXECUTE format('GRANT EXECUTE ON ROUTINE %s TO %s', v_function, p_role);
    END LOOP;
END;
$$;

-- REVOKE_ACCESS: Take back everything grant_access gave, and any other privilege the role
-- holds on pgkv's schema and functions.
CREATE OR REPLACE FUNCTION pgkv.revoke_access(p_role REGROLE)
RETURNS VOID
LANGUAGE plpgsql
SET search_path = pgkv, pg_temp
AS $$
BEGIN
    IF p_role IS NULL THEN
        RAISE EXCEPTION 'pgkv.revoke_access: role is required';
    END IF;
    EXECUTE format('REVOKE ALL ON ALL ROUTINES IN SCHEMA pgkv FROM %s', p_role);
    EXECUTE format('REVOKE ALL ON SCHEMA pgkv FROM %s', p_role);
END;
$$;
-- ============================================================================
-- Security: closed by default
-- ============================================================================
-- Shared by the fresh install and the upgrade from 0.3.0 (which first revokes what roles
-- were granted by name, sql/upgrade-0.3.0-grants.sql). Access is given afterwards, outside
-- the extension scripts, with pgkv.grant_access.

-- PostgreSQL lets PUBLIC execute a new function unless told otherwise, and versions before
-- 0.4.0 granted the schema and every function to PUBLIC.
REVOKE ALL ON SCHEMA pgkv FROM PUBLIC;
REVOKE ALL ON ALL ROUTINES IN SCHEMA pgkv FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA pgkv
    REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

-- No direct access to the tables or the sequence
REVOKE ALL ON ALL TABLES IN SCHEMA pgkv FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA pgkv
    REVOKE ALL ON TABLES FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA pgkv FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA pgkv
    REVOKE ALL ON SEQUENCES FROM PUBLIC;

-- Monitoring access (following pgmq pattern)
GRANT USAGE ON SCHEMA pgkv TO pg_monitor;
GRANT SELECT ON ALL TABLES IN SCHEMA pgkv TO pg_monitor;
ALTER DEFAULT PRIVILEGES IN SCHEMA pgkv
    GRANT SELECT ON TABLES TO pg_monitor;
